Base-ring-tree 基环树 概念 基环树是一种特殊的图,我们知道树是由 N 个点,N-1 条边组成的,那么在树上任意两结点之间加上一条边都会产生一个环,我们把这种由 N 个结点、N 条边组成的联通无向图称为基环树。如果不保证联通,也可能是基环树森林。注意,基环树森林中的每个结点都必须有一条边连接起来。如果存在独立的结点,那么很可能其中的一个联通子图中存在两个环，而基环树要求有且只有一个环。 有向基环树图又分为内向树和外向树。 内向树和外向树 所谓内向树的定义是每个点有且只有一条出边。也就是这棵树给人的大体感觉是向内的。 所谓外向树的定义是每个点有且只有一条入边。也就是这棵树给人的大题感觉是外向的。 比如上面的基环树，变成内向树就是：
变成外向树就是：
常见题型 一般的题型包括:求基环树的直径(树上两结点之间距离的最大值)求基环树上的动态规划、求基环树两结点之间的距离。 这些模型的解决通法一般是： 断环成树，然后将若干棵树处理好之后，再考虑环对答案的影响。也就是将环、树分开讨论解决问题。这时，用”环套树“这个名词来形容基环树，很是容易理解。 常见解题思路 基环树的最大特征就是有且只有一个环,所以解题(接下来以求基环树的直径为例)时一般从环入手,先找到环。其中找环过程可以用 BFS 的拓扑排序或 DFS 遍历。然后考虑从环上每个结点出发,在不经过环上其他点的情况下求出这棵子树的最长链,以及叶子结点到根结点的最长距离。然后我们知道基环树的直径只可能有以下两种情况: (1). 树上的最长链出现在子树中。 (2). 环上两棵子树中的叶子结点到另一棵子树的叶子结点经过环。 所以，只在环上再进行一遍 dp(动态规划)把环上的边考虑进来就可以了。 典型例题 骑士 [ZJOI2008] 骑士 题目描述 Z 国的骑士团是一个很有势力的组织，帮会中汇聚了来自各地的精英。他们劫富济贫，惩恶扬善，受到社会各界的赞扬。 最近发生了一件可怕的事情，邪恶的 Y 国发动了一场针对 Z 国的侵略战争。战火绵延五百里，在和平环境中安逸了数百年的 Z 国又怎能抵挡的住 Y 国的军队。于是人们把所有的希望都寄托在了骑士团的身上，就像期待有一个真龙天子的降生，带领正义打败邪恶。 骑士团是肯定具有打败邪恶势力的能力的，但是骑士们互相之间往往有一些矛盾。每个骑士都有且仅有一个自己最厌恶的骑士（当然不是他自己），他是绝对不会与自己最厌恶的人一同出征的。 战火绵延，人民生灵涂炭，组织起一个骑士军团加入战斗刻不容缓！国王交给了你一个艰巨的任务，从所有的骑士中选出一个骑士军团，使得军团内没有矛盾的两人（不存在一个骑士与他最痛恨的人一同被选入骑士军团的情况），并且，使得这支骑士军团最具有战斗力。 为了描述战斗力，我们将骑士按照 111 至 nnn 编号，给每名骑士一个战斗力的估计，一个军团的战斗力为所有骑士的战斗力总和。 输入格式 第一行包含一个整数 nnn，描述骑士团的人数。 接下来 nnn 行，每行两个整数，按顺序描述每一名骑士的战斗力和他最痛恨的骑士。 输出格式 应输出一行，包含一个整数，表示你所选出的骑士军团的战斗力。 样例 #1 样例输入 #1 310 220 330 1 样例输出 #1 30 提示 数据规模与约定 对于 30%30\%30% 的测试数据，满足 n≤10n \le 10n≤10； 对于 60%60\%60% 的测试数据，满足 n≤100n \le 100n≤100； 对于 80%80\%80% 的测试数据，满足 n≤104n \le 10 ^4n≤104。 对于 100%100\%100% 的测试数据，满足 1≤n≤1061\le n \le 10^61≤n≤106，每名骑士的战斗力都是不大于 10610^6106 的正整数。 AC代码
在存的时候存一下每个人最讨厌的人为他的父亲,对每个没访问的点DFS,在这个没访问的点所在的连通块上找环,找到以后强制不选它的父亲对它进行DP,然后强制不选它对它的父亲进行DP,然后取一个最大值即可,在DP里面,先考虑f[x][0]是不选x,初始值为0,f[x][1]是选x,初值为val[x],这是一个很好的赋值方法然后跑DP就行了。
#include&lt;iostream&gt;#include&lt;cstdio&gt;#include&lt;cstring&gt;#define M 2000007#define ll long longusing namespace std;int n, cnt;ll ans;int root;ll f[M][2];int head[M], val[M], vis[M], fa[M];struct edge &#123; int pre, to;&#125; e[M];inline void add(int from, int to) &#123; e[++cnt].pre = head[from]; e[cnt].to = to; head[from] = cnt;&#125;void dp(int now) &#123; vis[now] = 1; f[now][0] = 0, f[now][1] = val[now]; for (int i = head[now]; i; i = e[i].pre) &#123; int go = e[i].to; if (go != root) &#123; dp(go); f[now][0] += max(f[go][1], f[go][0]); f[now][1] += f[go][0]; &#125; else &#123; f[go][1] = -M; &#125; &#125;&#125;void find_circle(int x) &#123; vis[x] = 1; root = x; while (!vis[fa[root]]) &#123; root = fa[root]; vis[root] = 1; &#125; dp(root); ll t = max(f[root][0], f[root][1]); vis[root] = 1; root = fa[root]; dp(root); ans += max(t, max(f[root][0], f[root][1])); return;&#125;int main() &#123; cin &gt;&gt; n; for (int i = 1; i &lt;= n; i++) &#123; int x; cin &gt;&gt; val[i] &gt;&gt; x; add(x, i); fa[i] = x; &#125; for (int i = 1; i &lt;= n; i++) &#123; if (!vis[i]) &#123; find_circle(i); &#125; &#125; printf(&quot;%lld\n&quot;, ans); return 0;&#125;

 C++笔记汇总2 模板及STL
 1.模板
template &lt;typename T&gt;void My_swap(T&amp; a, T&amp; b) &#123;    T tmp = a;    a = b;    b = tmp;&#125;void test01() &#123;    int a, b;    a = 10, b = 20;    // 1.自动类型推导    My_swap(a, b);    // 2.显示指定类型    My_swap&lt;int&gt;(a, b);    cout &lt;&lt; &quot;a:&quot; &lt;&lt; a &lt;&lt; endl;    cout &lt;&lt; &quot;b:&quot; &lt;&lt; b &lt;&lt; endl;&#125;//函数模板注意事项：template &lt;class T&gt;  // typename可以替换为classvoid MySwap(T&amp; a, T&amp; b) &#123;    T tmp = a;    a = b;    b = tmp;&#125;// 1.自动类型推导必须推导出一致的数据类型T才能使用void test02() &#123;    int a, b;    a = 10, b = 20;    char c = &#x27;c&#x27;;    MySwap(a, b);    // MySwap(a, c);//类型不一致，报错    cout &lt;&lt; &quot;a:&quot; &lt;&lt; a &lt;&lt; endl;    cout &lt;&lt; &quot;b:&quot; &lt;&lt; b &lt;&lt; endl;&#125;// 2.模板必须要确定出T的数据类型，才可以使用template &lt;class T&gt;void func() &#123;    cout &lt;&lt; &quot;func()&quot; &lt;&lt; endl;&#125;void test03() &#123;    // func();//报错，推导不出T的类型    func&lt;int&gt;();&#125;
 普通函数和函数模板区别：
1.普通模板调用可以发生隐式类型转换
2.函数模板用自动类型推导，不可以发生隐式类型转换
3.函数模板用显示指定类型，可以发生隐式类型转换
 普通函数和函数模板调用的规则:
1.如果函数模板和普通函数都可以调用，优先调用普通函数
2.可以通过空模板参数列表强制调用函数模板
3.函数模板可以发生函数重载
4.如果函数模板可以产生更好的匹配，优先调用函数模板
void myPrint(int a, int b) &#123;    cout &lt;&lt; &quot;common&quot; &lt;&lt; endl;&#125;template &lt;class T&gt;void myPrint(T a, T b) &#123;    cout &lt;&lt; &quot;template-2&quot; &lt;&lt; endl;&#125;template &lt;class T&gt;void myPrint(T a, T b, T c) &#123;    cout &lt;&lt; &quot;template-3&quot; &lt;&lt; endl;&#125;void test04() &#123;    int a = 10;    int b = 20;    myPrint(a, b);    // 空模板参数列表    myPrint&lt;&gt;(a, b);    double c = 10;    double d = 20;    myPrint(c, d);&#125;
 模板的局限性
模板并不是万能的，有些特定数据类型，需要用具体化方式做特殊实现
class Person &#123;   public:    int age;    string name;&#125;;template &lt;class T&gt;bool myCompare(T&amp; a, T&amp; b) &#123;    if (a == b) &#123;        return false;    &#125; else &#123;        return true;    &#125;&#125;template &lt;&gt;bool myCompare(Person&amp; a, Person&amp; b) &#123;    if (a.age == b.age &amp;&amp; a.name == b.name) &#123;        return true;    &#125; else &#123;        return false;    &#125;&#125;void test05() &#123;    int a = 10;    int b = 20;    cout &lt;&lt; myCompare(a, b) &lt;&lt; endl;    // 如果用一个类就会报错,所以要重新定义    Person p1, p2;    p1.age = 10;    p2.age = 10;    p1.name = &quot;小红&quot;;    p2.name = &quot;小红&quot;;    cout &lt;&lt; myCompare(p1, p2) &lt;&lt; endl;&#125;
 类模板
template &lt;class NameType, class AgeType = int&gt;  // 默认参数class Person1 &#123;   public:    Person1(NameType name, AgeType age) &#123;        this-&gt;name = name;        this-&gt;age = age;    &#125;    NameType name;    AgeType age;    void showPerson() &#123;        cout &lt;&lt; &quot;age:&quot; &lt;&lt; this-&gt;age &lt;&lt; endl;        cout &lt;&lt; &quot;name:&quot; &lt;&lt; this-&gt;name &lt;&lt; endl;    &#125;&#125;;void test06() &#123;    Person1&lt;string, int&gt; p1(&quot;杜金阳&quot;, 18);    p1.showPerson();&#125;
 类模板和函数模板的区别：
1.类模板没有自动类型推导的使用方法
2.类模板在模板参数列表中可以有默认参数
 类模板和普通模板在成员函数创造时机的区别：
1.普通类中成员函数一开始就可以创建
2.类模板中的成员函数在调用时才创建
 类模板对象做函数参数
 三种传入方式
1.指定传入的类型[常用]
2.参数模板化
3.整个类模板化
 类模板遇到继承时的注意事项:
1.当子类继承的父类是一个类模板时，子类在声明的时候，要指定出父类中T的类型
2.如果不指定，编译器无法给子类分配内存
3.如果想灵活指定出父类中T的类型，子类也需变为类模板
 类模板和友元：
全局函数类内实现-直接在类内声明友元即可
全局函数类外实现-需要提前让编译器知道全局函数的存在
 2.STL
 algorithm 部分
 常用算术生成算法accumulate:计算区间内容器元素累计总和
class myPrint &#123;   public:    void operator()(int val) &#123; printf(&quot;%d &quot;, val); &#125;&#125;;void test01() &#123;    vector&lt;int&gt; v;    for (int i = 0; i &lt;= 100; i++) &#123;        v.push_back(i);    &#125;    for_each(v.begin(), v.end(), myPrint());    puts(&quot;&quot;);    int ans = accumulate(v.begin(), v.end(), 0);    //参数3为起始累加值    printf(&quot;%d&quot;, ans);&#125;
 常见查找算法adjacent_find:查找相邻重复元素
void test() &#123;    vector&lt;int&gt; v;    v.push_back(20);    v.push_back(50);    v.push_back(10);    v.push_back(10);    v.push_back(30);    v.push_back(40);    v.push_back(20);    vector&lt;int&gt;::iterator pos = adjacent_find(v.begin(), v.end());    if (pos == v.end()) &#123;        printf(&quot;not discover\n&quot;);    &#125; else &#123;        printf(&quot;val:%d\n&quot;, *pos);    &#125;&#125;
 常见查找算法binary_search
void test() &#123;    vector&lt;int&gt; v;    v.push_back(10);    v.push_back(20);    v.push_back(30);    v.push_back(40);    v.push_back(50);    bool ret = binary_search(v.begin(), v.end(), 30);    //查找必须为有序序列    printf(&quot;val:%d\n&quot;, ret);&#125;
 常用拷贝和替换算法copy
class myPrint &#123;   public:    void operator()(int val) &#123; printf(&quot;%d &quot;, val); &#125;&#125;;void test01() &#123;    vector&lt;int&gt; v1;    for (int i = 0; i &lt; 10; i++) &#123;        v1.push_back(i * 10);    &#125;    vector&lt;int&gt; v2;    v2.resize(v1.size());    copy(v1.begin(), v1.end(), v2.begin());    for_each(v2.begin(), v2.end(), myPrint());    puts(&quot;&quot;);&#125;
 常用查找算法count
void test01() &#123;    vector&lt;int&gt; v;    v.push_back(10);    v.push_back(40);    v.push_back(30);    v.push_back(40);    v.push_back(50);    v.push_back(60);    v.push_back(20);    v.push_back(20);    v.push_back(40);    v.push_back(50);    int num = count(v.begin(), v.end(), 20);    printf(&quot;%d&quot;, num);&#125;class Person &#123;   public:    string name;    int age;    Person(string name, int age) &#123;        this-&gt;name = name;        this-&gt;age = age;    &#125;    bool operator==(const Person&amp; p) &#123;        if (this-&gt;age == p.age) &#123;            return true;        &#125; else &#123;            return false;        &#125;    &#125;&#125;;void test02() &#123;    vector&lt;Person&gt; v;    Person p1(&quot;Charles&quot;, 19);    Person p2(&quot;Lucas&quot;, 23);    Person p3(&quot;Jerry&quot;, 19);    Person p4(&quot;Tom&quot;, 14);    v.push_back(p1);    v.push_back(p2);    v.push_back(p3);    v.push_back(p4);    Person p(&quot;Luis&quot;, 14);    int num = count(v.begin(), v.end(), p);    printf(&quot;%d&quot;, num);&#125;
 常用查找算法count_if
class cmp &#123;   public:    bool operator()(int val) &#123; return val &gt; 20; &#125;&#125;;void test01() &#123;    vector&lt;int&gt; v;    v.push_back(10);    v.push_back(40);    v.push_back(30);    v.push_back(40);    v.push_back(50);    v.push_back(60);    v.push_back(20);    v.push_back(20);    v.push_back(40);    v.push_back(50);    int num = count_if(v.begin(), v.end(), cmp());    printf(&quot;%d &quot;, num);&#125;class Person &#123;   public:    string name;    int age;    Person(string name, int age) &#123;        this-&gt;name = name;        this-&gt;age = age;    &#125;    bool operator==(const Person&amp; p) &#123;        if (this-&gt;age == p.age) &#123;            return true;        &#125; else &#123;            return false;        &#125;    &#125;&#125;;class cmp2 &#123;   public:    bool operator()(const Person&amp; p) &#123; return p.age &gt; 15; &#125;&#125;;void test02() &#123;    vector&lt;Person&gt; v;    Person p1(&quot;Charles&quot;, 19);    Person p2(&quot;Lucas&quot;, 23);    Person p3(&quot;Jerry&quot;, 19);    Person p4(&quot;Tom&quot;, 14);    v.push_back(p1);    v.push_back(p2);    v.push_back(p3);    v.push_back(p4);    int num = count_if(v.begin(), v.end(), cmp2());    printf(&quot;%d &quot;, num);&#125;
 常用算术生成算法fill:向容器中填充指定的元素
class myPrint &#123;   public:    void operator()(int val) &#123; printf(&quot;%d &quot;, val); &#125;&#125;;void test01() &#123;    vector&lt;int&gt; v;    for (int i = 0; i &lt;= 100; i++) &#123;        v.push_back(i);    &#125;    for_each(v.begin(), v.end(), myPrint());    puts(&quot;&quot;);    fill(v.begin(), v.begin() + 8, 0);    //参数3为起始累加值    for_each(v.begin(), v.end(), myPrint());    puts(&quot;&quot;);&#125;
 常见查找算法find
void test01() &#123;    vector&lt;int&gt; v;    for (int i = 0; i &lt; 10; i++) &#123;        v.push_back(i);    &#125;    vector&lt;int&gt;::iterator it = find(v.begin(), v.end(), 5);    if (it == v.end()) &#123;        printf(&quot;not discover\n&quot;);    &#125; else &#123;        printf(&quot;val:%d\n&quot;, *it);    &#125;&#125;class Person &#123;   public:    string name;    int age;    Person(string name, int age) &#123;        this-&gt;name = name;        this-&gt;age = age;    &#125;    bool operator==(const Person&amp; p) &#123;        if (this-&gt;age == p.age &amp;&amp; this-&gt;name == p.name) &#123;            return true;        &#125; else &#123;            return false;        &#125;    &#125;    //自定义类型需要重载以确定如何对比数据类型&#125;;void test02() &#123;    vector&lt;Person&gt; v;    Person p1(&quot;Charles&quot;, 19);    Person p2(&quot;Lucas&quot;, 23);    Person p3(&quot;Jerry&quot;, 19);    Person p4(&quot;Tom&quot;, 14);    v.push_back(p1);    v.push_back(p2);    v.push_back(p3);    v.push_back(p4);    vector&lt;Person&gt;::iterator it = find(v.begin(), v.end(), p2);    if (it == v.end()) &#123;        printf(&quot;not discover\n&quot;);    &#125; else &#123;        printf(&quot;key:%s val:%d\n&quot;, it-&gt;name.c_str(), it-&gt;age);    &#125;&#125;
 常见查找算法find_if
class cmp &#123;   public:    bool operator()(int val) &#123; return val &gt; 5; &#125;&#125;;void test01() &#123;    vector&lt;int&gt; v;    for (int i = 0; i &lt; 10; i++) &#123;        v.push_back(i);    &#125;    vector&lt;int&gt;::iterator pos = find_if(v.begin(), v.end(), cmp());    if (pos == v.end()) &#123;        printf(&quot;not discover\n&quot;);    &#125; else &#123;        printf(&quot;val:%d\n&quot;, *pos);    &#125;&#125;class Person &#123;   public:    string Name;    int Age;   public:    Person(string name, int age) &#123;        this-&gt;Name = name;        this-&gt;Age = age;    &#125;    bool operator==(const Person&amp; p) &#123;        if (this-&gt;Age == p.Age &amp;&amp; this-&gt;Name == p.Name) &#123;            return true;        &#125; else &#123;            return false;        &#125;    &#125;&#125;;class my_cmp &#123;   public:    bool operator()(Person&amp; p) &#123; return p.Age &gt; 20; &#125;&#125;;void test02() &#123;    vector&lt;Person&gt; v;    Person p1(&quot;Charles&quot;, 19);    Person p2(&quot;Lucas&quot;, 23);    Person p3(&quot;Jerry&quot;, 19);    Person p4(&quot;Tom&quot;, 14);    v.push_back(p1);    v.push_back(p2);    v.push_back(p3);    v.push_back(p4);    vector&lt;Person&gt;::iterator it = find_if(v.begin(), v.end(), my_cmp());    if (it == v.end()) &#123;        printf(&quot;not discover\n&quot;);    &#125; else &#123;        printf(&quot;key:%s val:%d\n&quot;, it-&gt;Name.c_str(), it-&gt;Age);    &#125;&#125;
 常用遍历算法for_each
// 普通函数void print01(int val) &#123;    printf(&quot;%d &quot;, val);&#125;// 仿函数class print02 &#123;   public:    void operator()(int val) &#123; printf(&quot;%d&quot;, val); &#125;&#125;;void test01() &#123;    vector&lt;int&gt; v;    for (int i = 0; i &lt; 10; i++) &#123;        v.push_back(i);    &#125;    for_each(v.begin(), v.end(), print01);    puts(&quot;&quot;);    for_each(v.begin(), v.end(), print02());    puts(&quot;&quot;);&#125;
 常用排序算法merge
// merge用于将两个有序序列合并void printVector(vector&lt;int&gt;&amp; v) &#123;    for (vector&lt;int&gt;::iterator it = v.begin(); it != v.end(); it++) &#123;        printf(&quot;%d &quot;, *it);    &#125;    puts(&quot;&quot;);&#125;void test01() &#123;    vector&lt;int&gt; v1;    v1.push_back(10);    v1.push_back(20);    v1.push_back(30);    v1.push_back(40);    v1.push_back(50);    vector&lt;int&gt; v2;    v2.push_back(15);    v2.push_back(25);    v2.push_back(35);    v2.push_back(45);    v2.push_back(55);    // 升序    vector&lt;int&gt; v;    v.resize(v1.size() + v2.size());  //分配空间    merge(v1.begin(), v1.end(), v2.begin(), v2.end(), v.begin());    printVector(v);&#125;
 常用排序算法random_shuffle:洗牌 指定范围内随机调整次序
void printVector(vector&lt;int&gt;&amp; v) &#123;    for (vector&lt;int&gt;::iterator it = v.begin(); it != v.end(); it++) &#123;        printf(&quot;%d &quot;, *it);    &#125;    puts(&quot;&quot;);&#125;void test() &#123;    srand((unsigned int)time(NULL));    //时间随机数种子，用于利用时间生成真正的随机数    vector&lt;int&gt; v;    for (int i = 1; i &lt;= 10; i++) &#123;        v.push_back(i * 10);    &#125;    printVector(v);    random_shuffle(v.begin(), v.end());    printVector(v);&#125;
 常用拷贝和替换算法replace
