 deque
#include &lt;bits/stdc++.h&gt;using namespace std;#define M 100007#define N 1007#define INF 0x3f3f3f3f#define ll long long#define db doublevoid printDeque(const deque&lt;int&gt;&amp; d) &#123;    for (deque&lt;int&gt;::const_iterator it = d.begin(); it != d.end(); it++) &#123;        printf(&quot;%d &quot;, *it);    &#125;    puts(&quot;&quot;);&#125;void build_deque() &#123;    //构造容器的4种方式    deque&lt;int&gt; d1;    for (int i = 0; i &lt; 10; i++) &#123;        d1.push_back(i);        d1.push_front(i);    &#125;  // deque可以从首尾两个方向插入    printDeque(d1);    deque&lt;int&gt; d2(d1.begin(), d1.end());    printDeque(d2);    deque&lt;int&gt; d3(10, 100);    printDeque(d3);    deque&lt;int&gt; d4(d3);    printDeque(d4);&#125;void value_deque() &#123;    deque&lt;int&gt; d1;    for (int i = 0; i &lt; 10; i++) &#123;        d1.push_back(i);    &#125;    printDeque(d1);    // operator = 赋值    deque&lt;int&gt; d2;    d2 = d1;    printDeque(d2);    // assign 赋值    deque&lt;int&gt; d3;    d3.assign(d1.begin(), d1.end());    printDeque(d3);    deque&lt;int&gt; d4;    d4.assign(10, 100);    printDeque(d4);&#125;void size_deque() &#123;    deque&lt;int&gt; d1;    for (int i = 0; i &lt; 10; i++) &#123;        d1.push_back(i);    &#125;    if (d1.empty()) &#123;        printf(&quot;d1为空\n&quot;);    &#125; else &#123;        printf(&quot;d1不为空\n&quot;);        printf(&quot;大小:%d\n&quot;, d1.size());        // deque容器没有容量概念    &#125;    // 重新指定大小    d1.resize(15);    printDeque(d1);  //默认0填充    d1.resize(17, 100);    printDeque(d1);    d1.resize(5);  //小于容量会将多余部分删除    printDeque(d1);&#125;void calc_deque() &#123;    deque&lt;int&gt; d1;    d1.push_back(10);   //尾插法    d1.push_front(40);  //头插法    d1.push_back(20);    d1.push_front(50);    d1.push_back(30);    printDeque(d1);    d1.pop_back();  //尾部删除    d1.pop_front();    d1.insert(d1.begin(), 100);    d1.insert(d1.begin(), 2, 1000);    d1.insert(d1.begin(), d1.begin() + 3, d1.end());    //在某个位置插入某两个区间之间的所有值    printDeque(d1);    d1.erase(d1.begin());    d1.erase(d1.begin() + 3, d1.end());    printDeque(d1);    d1.clear();&#125;void operator_deque() &#123;    deque&lt;int&gt; d1;    for (int i = 0; i &lt; 5; i++) &#123;        d1.push_back(i);        d1.push_front(i);    &#125;    //利用[]访问元素    for (int i = 0; i &lt; d1.size(); i++) &#123;        printf(&quot;%d &quot;, d1[i]);    &#125;    puts(&quot;&quot;);    // 利用at访问    for (int i = 0; i &lt; d1.size(); i++) &#123;        printf(&quot;%d &quot;, d1.at(i));    &#125;    puts(&quot;&quot;);    printf(&quot;%d %d&quot;, d1.front(), d1.back());&#125;void sort_deque() &#123;    deque&lt;int&gt; d;    d.push_back(20);    d.push_back(30);    d.push_back(40);    d.push_front(50);    d.push_front(60);    d.push_front(70);    printDeque(d);    sort(d.begin(), d.end());  //默认升序    //对于支持随机访问的迭代器的容器，都支持利用sort算法排序(利用vector也支持sort)    printDeque(d);&#125;int main() &#123;    build_deque();    value_deque();    size_deque();    calc_deque();    operator_deque();    sort_deque();    return 0;&#125;
 list
#include &lt;bits/stdc++.h&gt;using namespace std;#define M 100007#define N 1007#define INF 0x3f3f3f3f#define ll long long#define db double//链表list容器[双向循环链表]void printList(const list&lt;int&gt;&amp; l) &#123;    for (list&lt;int&gt;::const_iterator it = l.begin(); it != l.end(); it++) &#123;        printf(&quot;%d &quot;, *it);    &#125;    puts(&quot;&quot;);&#125;void build_list() &#123;    list&lt;int&gt; l1;    l1.push_back(40);    l1.push_front(10);    l1.push_back(20);    l1.push_front(30);    l1.push_back(50);    printList(l1);    list&lt;int&gt; l2(l1.begin(), l1.end());    printList(l2);    list&lt;int&gt; l3(l1);    printList(l3);    list&lt;int&gt; l4(10, 100);    printList(l4);&#125;void value_list() &#123;    //赋值    list&lt;int&gt; l1;    l1.push_back(10);    l1.push_back(20);    l1.push_back(30);    l1.push_back(40);    l1.push_back(50);    printList(l1);    list&lt;int&gt; l2 = l1;    printList(l2);    list&lt;int&gt; l3;    l3.assign(l2.begin(), l2.end());    printList(l3);    list&lt;int&gt; l4;    l4.assign(10, 100);    printList(l4);    // 交换    list&lt;int&gt; l5;    l5.assign(10, 100);    l1.swap(l5);    printList(l1);    printList(l5);&#125;void size_list() &#123;    list&lt;int&gt; l1;    for (int i = 0; i &lt; 10; i++) &#123;        l1.push_back(i);    &#125;    if (l1.empty()) &#123;        printf(&quot;l1为空\n&quot;);    &#125; else &#123;        printf(&quot;l1不为空\n&quot;);        printf(&quot;大小:%d\n&quot;, l1.size());        // list容器没有容量概念    &#125;    // 重新指定大小    l1.resize(15);    printList(l1);  //默认0填充    l1.resize(17, 100);    printList(l1);    l1.resize(5);  //小于容量会将多余部分删除    printList(l1);&#125;void calc_list() &#123;    list&lt;int&gt; l1;    l1.push_back(10);   //尾插法    l1.push_front(40);  //头插法    l1.push_back(20);    l1.push_front(50);    l1.push_back(30);    printList(l1);    l1.pop_back();  //尾部删除    l1.pop_front();    l1.insert(l1.begin(), 100);    l1.insert(l1.begin(), 2, 1000);    l1.insert(l1.begin(), l1.begin(), l1.end());    //在某个位置插入某两个区间之间的所有值    printList(l1);    l1.remove(10);  //删除容器中所有与elem值匹配的元素    list&lt;int&gt;::iterator it = l1.begin();    l1.erase(it++);    l1.erase(++it, l1.end());    printList(l1);    l1.clear();&#125;void operator_list() &#123;    list&lt;int&gt; l1;    for (int i = 0; i &lt; 5; i++) &#123;        l1.push_back(i);        l1.push_front(i);    &#125;    printf(&quot;%d %d&quot;, l1.front(), l1.back());&#125;// list不能使用[]或at方法进行访问bool cmp(int v1, int v2) &#123;    return v1 &gt; v2;&#125;void function_list() &#123;    list&lt;int&gt; l1;    l1.push_back(10);    l1.push_back(50);    l1.push_back(30);    l1.push_back(20);    l1.push_back(40);    printList(l1);    //反转    l1.reverse();    printList(l1);    // 排序    l1.sort();    //这里不是随机访问的迭代器，所以不能使用迭代器索引排序    printList(l1);    l1.sort(cmp);    printList(l1);&#125;int main() &#123;    build_list();    value_list();    size_list();    calc_list();    operator_list();    function_list();    return 0;&#125;
 map
#include &lt;bits/stdc++.h&gt;using namespace std;#define M 100007#define N 1007#define INF 0x3f3f3f3f#define ll long long#define db double// map中所有元素都是pair，第一个为key，第二个为value// map底层为二叉树// 所有元素会按照key自动排序/* map和multimap的区别：1.map不允许出现重复key元素，value可以重复2.multimap允许出现重复key元素 */void printMap(map&lt;int, int&gt;&amp; m) &#123;    for (map&lt;int, int&gt;::iterator it = m.begin(); it != m.end(); it++) &#123;        printf(&quot;key:%d value:%d\n&quot;, it-&gt;first, it-&gt;second);    &#125;    puts(&quot;&quot;);&#125;void build_map() &#123;    map&lt;int, int&gt; m1;    m1.insert(pair&lt;int, int&gt;(1, 21373191));    m1.insert(pair&lt;int, int&gt;(3, 21373119));    m1.insert(pair&lt;int, int&gt;(2, 21373181));    m1.insert(pair&lt;int, int&gt;(4, 21373190));    m1.insert(pair&lt;int, int&gt;(3, 21373190));    // key相同时直接插入失败，而Java中为覆盖    printMap(m1);  //自动排序，可以存在重复value值    map&lt;int, int&gt; m2(m1);    printMap(m2);    map&lt;int, int&gt; m3;    m3 = m1;    printMap(m3);&#125;void size_map() &#123;    map&lt;int, int&gt; m1;    //大小    m1.insert(pair&lt;int, int&gt;(1, 21373191));    m1.insert(pair&lt;int, int&gt;(3, 21373119));    m1.insert(pair&lt;int, int&gt;(2, 21373181));    m1.insert(pair&lt;int, int&gt;(4, 21373190));    printMap(m1);    if (m1.empty()) &#123;        printf(&quot;m1为空\n&quot;);    &#125; else &#123;        printf(&quot;m1不为空\n&quot;);        printf(&quot;大小:%d\n&quot;, m1.size());    &#125;    // 交换    map&lt;int, int&gt; m2;    m2.insert(pair&lt;int, int&gt;(4, 191));    m2.insert(pair&lt;int, int&gt;(3, 119));    m2.insert(pair&lt;int, int&gt;(5, 181));    m2.insert(pair&lt;int, int&gt;(6, 190));    m1.swap(m2);    printMap(m1);    printMap(m2);&#125;void calc_map() &#123;    map&lt;int, int&gt; m1;    //四种插入方式    m1.insert(pair&lt;int, int&gt;(1, 21373191));    m1.insert(make_pair(3, 21373119));    m1.insert(map&lt;int, int&gt;::value_type(2, 21373181));    m1[4] = 21373190;  //不建议用这种方式创建，但适合用来访问value    printMap(m1);    m1.erase(m1.begin());    map&lt;int, int&gt;::iterator it = m1.begin();    it++;    m1.erase(++it, m1.end());    m1.erase(2);  //类似remove，按照key删除    printMap(m1);    m1.clear();&#125;void statistics_map() &#123;    map&lt;int, int&gt; m;    m.insert(pair&lt;int, int&gt;(1, 21373191));    m.insert(pair&lt;int, int&gt;(3, 21373119));    m.insert(pair&lt;int, int&gt;(2, 21373181));    m.insert(pair&lt;int, int&gt;(4, 21373190));    //查找    map&lt;int, int&gt;::iterator pos = m.find(3);    if (pos != m.end()) &#123;        printf(&quot;key:%d value:%d\n&quot;, pos-&gt;first, pos-&gt;second);    &#125; else &#123;        printf(&quot;not discover\n&quot;);    &#125;    // 统计    int num = m.count(2);    printf(&quot;%d\n&quot;, num);&#125;class cmp &#123;   public:    bool operator()(int v1, int v2) &#123; return v1 &gt; v2; &#125;&#125;;void sort_map() &#123;    map&lt;int, int&gt; m1;    m1.insert(pair&lt;int, int&gt;(1, 21373191));    m1.insert(pair&lt;int, int&gt;(3, 21373119));    m1.insert(pair&lt;int, int&gt;(2, 21373181));    m1.insert(pair&lt;int, int&gt;(4, 21373190));    for (map&lt;int, int&gt;::iterator it = m1.begin(); it != m1.end(); it++) &#123;        printf(&quot;key:%d value:%d\n&quot;, it-&gt;first, it-&gt;second);    &#125;    puts(&quot;&quot;);    //降序排列    map&lt;int, int, cmp&gt; m2;    m2.insert(pair&lt;int, int&gt;(1, 21373191));    m2.insert(pair&lt;int, int&gt;(3, 21373119));    m2.insert(pair&lt;int, int&gt;(2, 21373181));    m2.insert(pair&lt;int, int&gt;(4, 21373190));    for (map&lt;int, int, cmp&gt;::iterator it = m2.begin(); it != m2.end(); it++) &#123;        printf(&quot;key:%d value:%d\n&quot;, it-&gt;first, it-&gt;second);    &#125;    puts(&quot;&quot;);&#125;int main() &#123;    // build_map();    // size_map();    // calc_map();    statistics_map();    // sort_map();    return 0;&#125;
 map与unordered_map的区别

对于map的底层原理，是通过红黑树（一种非严格意义上的平衡二叉树）来实现的，因此map内部所有的数据都是有序的（默认按key进行升序排序），map的查询、插入、删除操作的时间复杂度都是O(logn)。
unordered_map和map类似，都是存储的key-value的值，可以通过key快速索引到value。不同的是unordered_map不会根据key的大小进行排序，存储时是根据key的hash值判断元素是否相同，即unordered_map内部元素是无序的。unordered_map的底层是一个防冗余的哈希表（开链法避免地址冲突）。

 queue
#include &lt;bits/stdc++.h&gt;using namespace std;#define M 100007#define N 1007#define INF 0x3f3f3f3f#define ll long long#define db double// queue容器void build_queue() &#123;    queue&lt;int&gt; q;    q.push(10);    q.push(50);    q.push(40);    q.push(30);    q.push(20);    printf(&quot;%d\n&quot;, q.size());    printf(&quot;%d\n&quot;, q.back());    while (!q.empty()) &#123;        printf(&quot;%d &quot;, q.front());        q.pop();    &#125;&#125;int main() &#123;    build_queue();    return 0;&#125;
 set
#include &lt;bits/stdc++.h&gt;using namespace std;#define M 100007#define N 1007#define INF 0x3f3f3f3f#define ll long long#define db double// set为集合，底层结构为二叉树// 所有元素都会在插入时自动被排序/* set和multiset的区别：1.set不允许出现重复元素2.multiset允许出现重复元素 */void printSet(set&lt;int&gt;&amp; s) &#123;    for (set&lt;int&gt;::iterator it = s.begin(); it != s.end(); it++) &#123;        printf(&quot;%d &quot;, *it);    &#125;    puts(&quot;&quot;);&#125;void printMultiset(multiset&lt;int&gt;&amp; ms) &#123;    for (multiset&lt;int&gt;::iterator it = ms.begin(); it != ms.end(); it++) &#123;        printf(&quot;%d &quot;, *it);    &#125;    puts(&quot;&quot;);&#125;void build_set() &#123;    set&lt;int&gt; s1;    s1.insert(10);    s1.insert(30);    s1.insert(20);    s1.insert(30);    s1.insert(40);    printSet(s1);  //自动排序且去除重复元素    set&lt;int&gt; s2(s1);    printSet(s2);    set&lt;int&gt; s3;    s3 = s2;    printSet(s3);&#125;void size_set() &#123;    set&lt;int&gt; s1;    //大小    for (int i = 0; i &lt; 10; i++) &#123;        s1.insert(i);    &#125;    printSet(s1);    if (s1.empty()) &#123;        printf(&quot;s1为空\n&quot;);    &#125; else &#123;        printf(&quot;s1不为空\n&quot;);        printf(&quot;大小:%d\n&quot;, s1.size());    &#125;    // 交换    set&lt;int&gt; s2;    for (int i = 0; i &lt; 10; i++) &#123;        s2.insert(i * 10);    &#125;    s1.swap(s2);    printSet(s1);    printSet(s2);&#125;void calc_set() &#123;    set&lt;int&gt; s1;    for (int i = 0; i &lt; 10; i++) &#123;        s1.insert(i * 10);    &#125;    s1.insert(100);    printSet(s1);    s1.erase(s1.begin());    set&lt;int&gt;::iterator it = s1.begin();    it++;    it++;    s1.erase(++it, s1.end());    s1.erase(100);  //类似remove，特有重载    printSet(s1);    s1.clear();&#125;void statistics_set() &#123;    set&lt;int&gt; s;    s.insert(10);    s.insert(40);    s.insert(30);    s.insert(20);    //查找    set&lt;int&gt;::iterator pos = s.find(30);    if (pos != s.end()) &#123;        printf(&quot;%d\n&quot;, *pos);    &#125; else &#123;        printf(&quot;not discover\n&quot;);    &#125;    // 统计    int num = s.count(20);    printf(&quot;%d\n&quot;, num);&#125;void differ_multiset() &#123;    set&lt;int&gt; s;    s.insert(10);    s.insert(10);    multiset&lt;int&gt; ms;    ms.insert(10);    ms.insert(10);    printSet(s);    printMultiset(ms);&#125;void pair_set() &#123;    // pair对组创建    pair&lt;string, int&gt; p1(&quot;Charles&quot;, 19);    printf(&quot;%s %d\n&quot;, p1.first.c_str(), p1.second);    // printf不能直接输出String字符串类型，需要如上转化，而cout可以    pair&lt;string, int&gt; p2 = make_pair(&quot;Jerry&quot;, 23);    printf(&quot;%s %d\n&quot;, p2.first.c_str(), p2.second);&#125;class cmp &#123;   public:    bool operator()(int v1, int v2) &#123; return v1 &gt; v2; &#125;&#125;;class Person &#123;   public:    Person(string name, int age) &#123;        this-&gt;m_name = name;        this-&gt;m_age = age;    &#125;    string m_name;    int m_age;&#125;;class cmp_Class &#123;   public:    bool operator()(const Person&amp; p1, const Person&amp; p2) &#123;        if (p1.m_age != p2.m_age) &#123;            return p1.m_age &gt; p2.m_age;        &#125; else &#123;            return strcmp(p1.m_name.c_str(), p2.m_name.c_str());        &#125;    &#125;&#125;;void sort_set() &#123;    set&lt;int&gt; s1;    s1.insert(10);    s1.insert(20);    s1.insert(30);    s1.insert(40);    s1.insert(50);    printSet(s1);    //降序排列    set&lt;int, cmp&gt; s2;    s2.insert(10);    s2.insert(20);    s2.insert(30);    s2.insert(40);    s2.insert(50);    for (set&lt;int, cmp&gt;::iterator it = s2.begin(); it != s2.end(); it++) &#123;        //需要修改迭代器        printf(&quot;%d &quot;, *it);    &#125;    puts(&quot;&quot;);    // set存放自定义类型    set&lt;Person, cmp_Class&gt; s;    Person p1(&quot;Charles&quot;, 19);    Person p2(&quot;Lucas&quot;, 25);    Person p3(&quot;Tom&quot;, 19);    Person p4(&quot;Jerry&quot;, 28);    s.insert(p1);    s.insert(p2);    s.insert(p3);    s.insert(p4);    for (set&lt;Person, cmp_Class&gt;::iterator it = s.begin(); it != s.end(); it++) &#123;        printf(&quot;%s %d\n&quot;, it-&gt;m_name.c_str(), it-&gt;m_age);    &#125;&#125;int main() &#123;    build_set();    size_set();    calc_set();    statistics_set();    differ_multiset();    pair_set();    sort_set();    return 0;&#125;
 stack
#include &lt;bits/stdc++.h&gt;using namespace std;#define M 100007#define N 1007#define INF 0x3f3f3f3f#define ll long long#define db double// stack容器void build_stack() &#123;    stack&lt;int&gt; s;    s.push(10);  //入栈    s.push(20);    s.push(30);    s.push(40);    if (!s.empty()) &#123;  //判断栈是否为空        int temp = s.top();        printf(&quot;%d\n&quot;, temp);    &#125;    s.pop();  //出栈    cout &lt;&lt; s.size() &lt;&lt; endl;&#125;int main() &#123;    build_stack();    return 0;&#125;
 vector
#include &lt;bits/stdc++.h&gt;using namespace std;#define M 100007#define N 1007#define INF 0x3f3f3f3f#define ll long long#define db double// vector相关笔记void printVector(vector&lt;int&gt;&amp; v) &#123;  //用引用的方式传入    for (vector&lt;int&gt;::iterator it = v.begin(); it != v.end();         it++) &#123;  //迭代器遍历        printf(&quot;%d &quot;, *it);    &#125;    puts(&quot;&quot;);&#125;void build_vector() &#123;    // 创建vector容器并向里面填入数值    vector&lt;int&gt; v1;    for (int i = 0; i &lt; 10; i++) &#123;        v1.push_back(i);  //向vector中推入值    &#125;    printVector(v1);    // vector赋值    //方法1：operator=    vector&lt;int&gt; v2;    v2 = v1;    printVector(v2);    //方法2：assign读入    vector&lt;int&gt; v3;    v3.assign(v1.begin(), v1.end());    printVector(v3);    //方法3：assign赋值    vector&lt;int&gt; v4;    v4.assign(10, 100);  //赋值10个100    printVector(v4);&#125;void capacity_vector() &#123;    // vector容器的容量和大小操作    vector&lt;int&gt; v1;    for (int i = 0; i &lt; 10; i++) &#123;        v1.push_back(i);    &#125;    if (v1.empty()) &#123;        printf(&quot;v1为空\n&quot;);    &#125; else &#123;        printf(&quot;v1不为空\n&quot;);        printf(&quot;容量:%d 大小:%d\n&quot;, v1.capacity(), v1.size());        //容量&gt;=大小    &#125;    // 重新指定大小    v1.resize(15);    printVector(v1);  //默认0填充    v1.resize(15, 100);    printVector(v1);    v1.resize(5);  //小于容量会将多余部分删除    printVector(v1);&#125;void calc_vector() &#123;    vector&lt;int&gt; v1;    v1.push_back(10);  //尾插法    v1.push_back(40);    v1.push_back(20);    v1.push_back(50);    v1.push_back(30);    printVector(v1);    v1.pop_back();  //尾部删除    v1.insert(v1.begin(), 100);    v1.insert(v1.begin(), 2, 1000);    printVector(v1);    v1.erase(v1.begin());    v1.erase(v1.begin() + 3, v1.end());    printVector(v1);    v1.clear();&#125;void operator_vector() &#123;    vector&lt;int&gt; v1;    for (int i = 0; i &lt; 10; i++) &#123;        v1.push_back(i);    &#125;    //利用[]访问元素    for (int i = 0; i &lt; v1.size(); i++) &#123;        printf(&quot;%d &quot;, v1[i]);    &#125;    puts(&quot;&quot;);    // 利用at访问    for (int i = 0; i &lt; v1.size(); i++) &#123;        printf(&quot;%d &quot;, v1.at(i));    &#125;    puts(&quot;&quot;);    printf(&quot;%d %d&quot;, v1.front(), v1.back());&#125;void swap_vector() &#123;    vector&lt;int&gt; v1;    for (int i = 0; i &lt; 10; i++) &#123;        v1.push_back(i);    &#125;    vector&lt;int&gt; v2;    for (int i = 9; i &gt;= 0; i--) &#123;        v2.push_back(i);    &#125;    v1.swap(v2);  //容器互换    printVector(v1);    printVector(v2);    // 实际用途    vector&lt;int&gt; v;    for (int i = 0; i &lt; 100000; i++) &#123;        v.push_back(i);    &#125;    printf(&quot;容量:%d 大小:%d\n&quot;, v.capacity(), v.size());    v.resize(3);    vector&lt;int&gt;(v).swap(v);  //用于收缩容器容量，避免空间浪费    printf(&quot;容量:%d 大小:%d\n&quot;, v.capacity(), v.size());&#125;void reserve_vector() &#123;    vector&lt;int&gt; v;    //利用reserve预留空间    v.reserve(100000);    int num = 0, *p = NULL;  // num统计开辟次数    for (int i = 0; i &lt; 100000; i++) &#123;        v.push_back(i);        if (p != &amp;v[0]) &#123;            p = &amp;v[0];            num++;        &#125;    &#125;    printf(&quot;%d&quot;, num);&#125;int main() &#123;    build_vector();    capacity_vector();    calc_vector();    operator_vector();    swap_vector();    reserve_vector();    return 0;&#125;
