 Inner_function
#include &lt;bits/stdc++.h&gt;using namespace std;#define M 100007#define N 1007#define INF 0x3f3f3f3f#define ll long long#define db double// 内建函数对象// 1.算数仿函数// negate 一元仿函数 取反仿函数void test01() &#123;    negate&lt;int&gt; n;    printf(&quot;%d\n&quot;, n(50));&#125;// plus 二元仿函数 加法void test02() &#123;    plus&lt;int&gt; p;    printf(&quot;%d\n&quot;, p(10, 20));&#125;/* 类似函数plus 加法minus 减法multiplies 乘法divides 除法modulus 取模negate 取反 */// 2.关系仿函数// greater 大于void test03() &#123;    vector&lt;int&gt; v;    v.push_back(10);    v.push_back(30);    v.push_back(40);    v.push_back(20);    v.push_back(50);    //降序排列    sort(v.begin(), v.end(), greater&lt;int&gt;());    for (vector&lt;int&gt;::iterator it = v.begin(); it != v.end(); it++) &#123;        printf(&quot;%d &quot;, *it);    &#125;    puts(&quot;&quot;);&#125;// 3.逻辑仿函数// logical_not 逻辑非void test04() &#123;    vector&lt;bool&gt; v1;    v1.push_back(true);    v1.push_back(false);    v1.push_back(true);    v1.push_back(false);    for (vector&lt;bool&gt;::iterator it = v1.begin(); it != v1.end(); it++) &#123;        cout &lt;&lt; *it &lt;&lt; &quot; &quot;;  //不知道为什么这里bool不能用printf    &#125;    puts(&quot;&quot;);    vector&lt;bool&gt; v2;    v2.resize(v1.size());  //首先需要扩大容量    transform(v1.begin(), v1.end(), v2.begin(), logical_not&lt;bool&gt;());    for (vector&lt;bool&gt;::iterator it = v2.begin(); it != v2.end(); it++) &#123;        cout &lt;&lt; *it &lt;&lt; &quot; &quot;;    &#125;    puts(&quot;&quot;);&#125;int main() &#123;    test01();    test02();    test03();    test04();    return 0;&#125;
 function_object
#include &lt;bits/stdc++.h&gt;using namespace std;#define M 100007#define N 1007#define INF 0x3f3f3f3f#define ll long long#define db double//函数对象// 1.函数对象在使用时，可以像普通函数那样调用，可以有参数，可以有返回值class MyAdd &#123;   public:    int operator()(int v1, int v2) &#123; return v1 + v2; &#125;&#125;;void test01() &#123;    MyAdd myAdd;    printf(&quot;%d\n&quot;, myAdd(10, 10));&#125;// 2.函数对象超出普通函数的概念，函数对象可以有自己的状态class MyPrint &#123;   public:    int count;  //内部自己的状态    MyPrint() &#123; this-&gt;count = 0; &#125;    void operator()(string test) &#123;        printf(&quot;%s\n&quot;, test.c_str());        this-&gt;count++;    &#125;&#125;;void test02() &#123;    MyPrint MyPrint;    MyPrint(&quot;hello world&quot;);    printf(&quot;%d\n&quot;, MyPrint.count);&#125;// 3.函数对象可以作为参数传递void doPrint(MyPrint&amp; mp, string test) &#123;    mp(test);&#125;void test03() &#123;    MyPrint myPrint;    doPrint(myPrint, &quot;Hello c++&quot;);&#125;int main() &#123;    test01();    test02();    test03();    return 0;&#125;
