#include &lt;bits/stdc++.h&gt;using namespace std;#define M 100007#define N 1007#define INF 0x3f3f3f3f#define ll long long#define db double//函数对象// 1.函数对象在使用时，可以像普通函数那样调用，可以有参数，可以有返回值class MyAdd &#123;   public:    int operator()(int v1, int v2) &#123; return v1 + v2; &#125;&#125;;void test01() &#123;    MyAdd myAdd;    printf(&quot;%d\n&quot;, myAdd(10, 10));&#125;// 2.函数对象超出普通函数的概念，函数对象可以有自己的状态class MyPrint &#123;   public:    int count;  //内部自己的状态    MyPrint() &#123; this-&gt;count = 0; &#125;    void operator()(string test) &#123;        printf(&quot;%s\n&quot;, test.c_str());        this-&gt;count++;    &#125;&#125;;void test02() &#123;    MyPrint MyPrint;    MyPrint(&quot;hello world&quot;);    printf(&quot;%d\n&quot;, MyPrint.count);&#125;// 3.函数对象可以作为参数传递void doPrint(MyPrint&amp; mp, string test) &#123;    mp(test);&#125;void test03() &#123;    MyPrint myPrint;    doPrint(myPrint, &quot;Hello c++&quot;);&#125;int main() &#123;    test01();    test02();    test03();    return 0;&#125;

C++笔记汇总3 类和对象 类和对象 1、封装 设计一个圆类，求圆的周长 #define PI 3.14 class Circle &#123; // 使用权限 public: // 属性 int r; // 行为 double calc() &#123; return 2 * PI * r; &#125;&#125;; 三种权限 公共权限 public 成员类内可以访问，类外可以访问 保护权限 protected 成员类内可以访问，类外不可以访问，继承中儿子可以访问父亲权限 私有权限 private 成员类内可以访问，类外不可以访问，继承中儿子可以不访问父亲权限 class Person &#123; public: string m_Name; protected: string m_Car; private: int m_Password; public: void fun() &#123; m_Name = &quot;张三&quot;; m_Car = &quot;拖拉机&quot;; m_Password = 123456; &#125; private: void fun2() &#123; m_Name = &quot;张三&quot;; m_Car = &quot;拖拉机&quot;; m_Password = 123456; &#125;&#125;; struct 和 class 的区别 struct 默认的权限为 公共 public class 默认的权限为 私有 private class C1 &#123; int m_A;&#125;;struct C2 &#123; int m_A;&#125;; 2.对象的初始化和清理 1. 构造函数 没有返回值 函数名和类名相同 构造函数可以有参数，可以发生重载 创建对象的时候，构造函数自动调用一次，而且仅调用一次 2. 析构函数 没有返回值 函数名和类名相同 无参数，不能发生重载 对象销毁前自动调用，且仅调用一次 构造和析构都是必须有的实现，如果我们自己不提供，编译器会自动提供一个空实现的构造和析构 class Person1 &#123; public: // 构造函数 Person1() &#123; cout &lt;&lt; &quot;Person1函数的调用&quot; &lt;&lt; endl; &#125; // 析构函数 ~Person1() &#123; cout &lt;&lt; &quot;~Person1函数的调用&quot; &lt;&lt; endl; &#125;&#125;;void test01() &#123; Person1 p1;&#125; 构造函数的分类及调用 // 分类class Person2 &#123; public: int age; // 普通构造函数 Person2() &#123; cout &lt;&lt; &quot;Person2函数调用&quot; &lt;&lt; endl; &#125; Person2(int a) &#123; age = a; cout &lt;&lt; a &lt;&lt; endl; &#125; // 拷贝构造函数 Person2(const Person2&amp; p) &#123; age = p.age; cout &lt;&lt; age &lt;&lt; endl; &#125; // 析构函数 ~Person2() &#123; cout &lt;&lt; &quot;~Person2函数调用&quot; &lt;&lt; endl; &#125;&#125;;// 调用void test02() &#123; // 1.括号法 Person2 p1; Person2 p2(10); // 拷贝构造函数调用 Person2 p3(p2); // 注意事项 // 调用默认构造函数时，不要加(),否则编译器会以为是函数声明 // 2.显示法 Person2 p4 = Person2(10); Person2 p5 = Person2(p4); // 拷贝构造 Person2(10); // 匿名对象 // 特点：当前行结束后先调用析构函数，系统立即回收掉匿名对象，之后再继续执行后面的代码 // 注意事项 // 不要使用拷贝构造来初始化匿名对象 // Person2(p5); //编译器理解为Person p5 // 3.隐式转换法 Person2 p6 = 10; // 相当于Person2 p6=Person2(10);&#125;// 拷贝构造函数调用的时机class Person3 &#123; public: int age; Person3() &#123; cout &lt;&lt; &quot;Person3函数的调用&quot; &lt;&lt; endl; &#125; Person3(int age) &#123; this-&gt;age = age; // this指针 cout &lt;&lt; &quot;Person3函数的调用&quot; &lt;&lt; endl; &#125; Person3(Person3&amp; p) &#123; this-&gt;age = p.age; cout &lt;&lt; &quot;Person3函数的调用&quot; &lt;&lt; endl; &#125; ~Person3() &#123; cout &lt;&lt; &quot;~Person3函数的调用&quot; &lt;&lt; endl; &#125;&#125;;void do_work(Person3 p) &#123; p.age = 10;&#125;Person3 do_work2() &#123; Person3 p(10); return p;&#125;void test03() &#123; // 1.使用一个已经创建完毕的对象来初始化一个新对象 Person3 p1(20); Person3 p2(p1); // 2.值传递的方式给函数参数传值 Person3 p4; do_work(p4); // 3.值方式返回局部变量 // Person3 p5 = do_work2();//按教程写的，但是会报错&#125; 如果用户定义有参构造函数，c++不再提供默认无参构造，但是会提供默认拷贝构造 如果用户定义拷贝构造函数，c++不会再提供其他构造函数 深拷贝和浅拷贝 浅拷贝:简单复制拷贝操作 深拷贝:在堆区重新申请空间,进行拷贝构造 class Person4 &#123; public: Person4() &#123; cout &lt;&lt; &quot;Person4函数的调用&quot; &lt;&lt; endl; &#125; Person4(int age, int height) &#123; this-&gt;age = age; // 浅拷贝 this-&gt;height = new int(height); // 深拷贝 &#125; Person4(const Person4&amp; p) &#123; // 重写拷贝构造函数 this-&gt;age = p.age; this-&gt;height = new int(*p.height); cout &lt;&lt; &quot;Person4拷贝构造函数调用&quot; &lt;&lt; endl; &#125; ~Person4() &#123; // 析构代码,将堆区开辟数据做释放操作 if (this-&gt;height != NULL) &#123; delete this-&gt;height; this-&gt;height = NULL; &#125; cout &lt;&lt; &quot;~Person4函数的调用&quot; &lt;&lt; endl; &#125; int age; int* height;&#125;;void test04() &#123; Person4 p1(18, 160); Person4 p2(p1);&#125; 初始化列表 class Person5 &#123; public: int a, b, c; // 传统初始化操作 // Person5(int a, int b, int c) &#123; // this-&gt;a = a; // this-&gt;b = b; // this-&gt;c = c; // &#125; // 初始化列表初始化属性 Person5(int a, int b, int c) : a(a), b(b), c(c) &#123;&#125;&#125;; Static // 类对象可以作为类成员// 静态成员变量/* 1.所有对象都共用同一份数据 2.编译阶段就分配内存 3.类内声明,类外初始化操作 */class Person6 &#123; public: static int a; // 类内声明 private: static int b;&#125;;int Person6::a = 100; // 类外初始化int Person6::b = 200;void test06() &#123; Person6 p1; cout &lt;&lt; p1.a &lt;&lt; endl; Person6 p2; p2.a = 200; // 所有对象共用一份数据 cout &lt;&lt; p1.a &lt;&lt; endl; // 静态成员变量的访问方式: // 1.通过对象进行访问 Person6 p3; cout &lt;&lt; p3.a &lt;&lt; endl; // 2.通过类名进行访问 cout &lt;&lt; Person6::a &lt;&lt; endl; // cout &lt;&lt; Person6::b &lt;&lt; endl; // 私有权限类外无法访问(b)&#125;// 静态成员函数/* 1.所有对象共享同一个函数2.静态成员函数只能访问静态成员变量 */class Person7 &#123; public: static void func() &#123; a = 100; // b = 200;//报错，不能访问非静态变量 cout &lt;&lt; &quot;static void fun的调用&quot; &lt;&lt; endl; &#125; static int a; int b; // 静态成员函数也有访问权限 private: static void fun2() &#123; cout &lt;&lt; &quot;static void fun2调用&quot; &lt;&lt; endl; &#125;&#125;;int Person7::a;void test07() &#123; // 两种访问方式: // 1.通过对象访问 Person7 p1; p1.func(); // 2.通过类名访问 Person7::func(); // Person7::func2();//private不可访问&#125; 成员对象和成员函数分开存储 class Person1 &#123; int a; static int b; void func() &#123;&#125; static void func2() &#123;&#125;&#125;;int Person1::b;void test01() &#123; Person1 p; cout &lt;&lt; sizeof(p) &lt;&lt; endl;&#125; Summary: 1.空对象默认字节为 1,若非空则不占字节 2.非静态变量属于类的对象，占用字节空间 3.静态变量不属于类的对象，不占用字节空间 4.静态函数不属于类的对象，不占用字节空间 5.非静态函数不属于类的对象，不占用字节空间 this指针作用: 1.解决名称冲突 2.返回对象本身用*this class Person2 &#123; public: int age; Person2(int age) &#123; this-&gt;age = age; &#125; Person2&amp; PersonAddAge(Person2&amp; p) &#123; this-&gt;age += p.age; return *this; &#125;&#125;;void test02() &#123; Person2 p1(10); Person2 p2(20); // 链式编程思想 p1.PersonAddAge(p2).PersonAddAge(p2); cout &lt;&lt; p1.age &lt;&lt; endl;&#125;// 空指针访问成员函数class Person3 &#123; public: void showClassName() &#123; cout &lt;&lt; &quot;this is Person3 class&quot; &lt;&lt; endl; &#125; void showPersonAge() &#123; cout &lt;&lt; &quot;age=&quot; &lt;&lt; age &lt;&lt; endl; &#125; int age;&#125;;void test03() &#123; Person3* p = NULL; p-&gt;showClassName(); // 可以正常运行 // p-&gt;showPersonAge(); // 报错&#125; const修饰成员函数 class Person4 &#123; public: // this指针的本质是一个指针常量 // Person4 *const this; // 在成员函数后面加const，修饰的是this指向，让指针指向的值也不可以修改 void showPerson() const &#123; this-&gt;b = 100; // a=100;//报错 // this = NULL;//报错，this指针不可以改变指针的指向 &#125; void fun() &#123; a = 10; &#125; int a; mutable int b; // 特殊变量，即使在常函数也可以修改这个值&#125;;void test04() &#123; // const Person4 p; // 在对象前加const，变成常对象[不知道为什么vscode会报错] // p.a=10;//报错 // p.b = 200; // 常对象只能调用常函数 // p.showPerson(); // p.fun(); // 常对象不可以调用普通成员函数，因为普通成员函数可以修改属性&#125; 友元 1.全局函数做友元 class Building &#123; friend void goodGay(Building&amp; building); // 友元 public: string m_SittingRoom; Building() &#123; m_SittingRoom = &quot;客厅&quot;; m_BedRoom = &quot;卧室&quot;; &#125; private: string m_BedRoom;&#125;;void goodGay(Building&amp; building) &#123; cout &lt;&lt; &quot;visit&quot; &lt;&lt; building.m_SittingRoom &lt;&lt; endl; cout &lt;&lt; &quot;visit&quot; &lt;&lt; building.m_BedRoom &lt;&lt; endl;&#125;void demo1() &#123; Building building; goodGay(building);&#125; 2.类做友元 class Building2; // 类似函数声明class GoodGay &#123; public: GoodGay(); void visit(); Building2* building;&#125;;class Building2 &#123; friend class GoodGay; // 友元 public: Building2(); string m_SittingRoom; private: string m_BedRoom;&#125;;// 类外写成员函数，初始化GoodGay::GoodGay() &#123; building = new Building2;&#125;;void GoodGay::visit() &#123; cout &lt;&lt; &quot;visit&quot; &lt;&lt; building-&gt;m_SittingRoom &lt;&lt; endl; cout &lt;&lt; &quot;visit&quot; &lt;&lt; building-&gt;m_BedRoom &lt;&lt; endl;&#125;Building2::Building2() &#123; m_SittingRoom = &quot;客厅&quot;; m_BedRoom = &quot;卧室&quot;;&#125;void demo2() &#123; GoodGay gg; gg.visit();&#125; 3.成员函数做友元 class Building3; // 类似函数声明class GoodGay1 &#123; public: GoodGay1(); void visit(); void visit2(); Building3* building;&#125;;class Building3 &#123; friend void GoodGay1::visit(); // 友元 public: Building3(); string m_SittingRoom; private: string m_BedRoom;&#125;;GoodGay1::GoodGay1() &#123; building = new Building3;&#125;;void GoodGay1::visit() &#123; cout &lt;&lt; &quot;visit&quot; &lt;&lt; building-&gt;m_SittingRoom &lt;&lt; endl; cout &lt;&lt; &quot;visit&quot; &lt;&lt; building-&gt;m_BedRoom &lt;&lt; endl;&#125;void GoodGay1::visit2() &#123; cout &lt;&lt; &quot;visit2&quot; &lt;&lt; building-&gt;m_SittingRoom &lt;&lt; endl; // cout &lt;&lt; &quot;visit2&quot; &lt;&lt; building-&gt;m_BedRoom &lt;&lt; endl;//报错&#125;Building3::Building3() &#123; m_SittingRoom = &quot;客厅&quot;; m_BedRoom = &quot;卧室&quot;;&#125;void demo3() &#123; GoodGay1 gg; gg.visit(); // gg.visit2();//报错&#125; 3.运算符重载 一.加法运算符重载 class Person1 &#123; public: int a, b; // 1.通过成员函数重载 Person1 operator+(Person1&amp; p) &#123; Person1 tmp; tmp.a = this-&gt;a + p.a; tmp.b = this-&gt;b + p.b; return tmp; &#125;&#125;;// 2.通过全局函数重载Person1 operator-(Person1&amp; p1, Person1&amp; p2) &#123; Person1 tmp; tmp.a = p1.a - p2.a; tmp.b = p1.b - p2.b; return tmp;&#125;//函数重载的版本Person1 operator+(Person1&amp; p1, int num) &#123; Person1 tmp; tmp.a = p1.a + num; tmp.b = p1.b + num; return tmp;&#125;void test01() &#123; Person1 p1; p1.a = 10; p1.b = 20; Person1 p2; p2.a = 30; p2.b = 40; Person1 p3 = p1 + p2; //本质Person1 p3=p1.operator+(p2); Person1 p4 = p1 - p2; //本质Person1 p4=operator-(p1,p2); cout &lt;&lt; &quot;p3.a:&quot; &lt;&lt; p3.a &lt;&lt; &quot;
p3.b:&quot; &lt;&lt; p3.b &lt;&lt; endl; cout &lt;&lt; &quot;p4.a:&quot; &lt;&lt; p4.a &lt;&lt; &quot;
p4.b:&quot; &lt;&lt; p4.b &lt;&lt; endl; //运算符重载也可以发生函数重载 Person1 p5 = p1 + 10; cout &lt;&lt; &quot;p5.a:&quot; &lt;&lt; p5.a &lt;&lt; &quot;
p5.b:&quot; &lt;&lt; p5.b &lt;&lt; endl;&#125; 二.左移运算符重载 class Person2 &#123; friend ostream&amp; operator&lt;&lt;(ostream&amp; out, Person2&amp; p); //友元 public: void setA(int a) &#123; this-&gt;a = a; &#125; void setB(int b) &#123; this-&gt;b = b; &#125; private: int a, b; // 利用成员函数重载左移运算符 p.operator&lt;&lt;(cout) 简化版本 p&lt;&lt;cout; // 故不会利用成员函数重载&lt;&lt;运算符&#125;;ostream&amp; operator&lt;&lt;(ostream&amp; out, Person2&amp; p) &#123; out &lt;&lt; &quot;p.a:&quot; &lt;&lt; p.a &lt;&lt; endl; out &lt;&lt; &quot;p.b:&quot; &lt;&lt; p.b &lt;&lt; endl; return out;&#125;void test02() &#123; Person2 p; p.setA(10); p.setB(20); cout &lt;&lt; p &lt;&lt; endl;&#125; 三.递增运算符重载 class MyInteger &#123; friend ostream&amp; operator&lt;&lt;(ostream&amp; out, MyInteger my); // friend MyInteger&amp; operator++(MyInteger&amp; my); // friend MyInteger operator++(MyInteger&amp; my, int); public: MyInteger() &#123; num = 0; &#125; // 前置++ MyInteger&amp; operator++() &#123; ++num; return *this; &#125; //后置++ // MyInteger&amp; operator++(int)中int为占位参数 // 可以用于区分前置后置，防止无法函数重载 MyInteger operator++(int) &#123; MyInteger tmp = *this; ++num; return tmp; &#125; private: int num;&#125;;ostream&amp; operator&lt;&lt;(ostream&amp; out, MyInteger my) &#123; out &lt;&lt; my.num; return out;&#125;/* //前置++[全局变量写法]MyInteger&amp; operator++(MyInteger&amp; my) &#123; ++my.num; return my;&#125;//后置++[全局变量写法]MyInteger operator++(MyInteger&amp; my, int) &#123; MyInteger tmp = my; ++my.num; return tmp;&#125; */void test03() &#123; MyInteger my; cout &lt;&lt; ++my &lt;&lt; endl; cout &lt;&lt; my++ &lt;&lt; endl;&#125; 四.赋值运算符重载 class Person4 &#123; public: Person4(int age) &#123; this-&gt;age = new int(age); &#125; ~Person4() &#123; if (this-&gt;age != NULL) &#123; delete this-&gt;age; this-&gt;age = NULL; &#125; &#125; // 由于=非重载为浅拷贝，析构函数导致代码崩溃，需要赋值运算符的函数重载 // 重载 Person4&amp; operator=(Person4&amp; p) &#123; if (this-&gt;age != NULL) &#123; delete this-&gt;age; this-&gt;age = NULL; &#125; this-&gt;age = new int(*p.age); return *this; &#125; int* age;&#125;;void test04() &#123; Person4 p1(18); Person4 p2(20); Person4 p3(30); cout &lt;&lt; &quot;p1年龄为&quot; &lt;&lt; *p1.age &lt;&lt; endl; cout &lt;&lt; &quot;p2年龄为&quot; &lt;&lt; *p2.age &lt;&lt; endl; cout &lt;&lt; &quot;p3年龄为&quot; &lt;&lt; *p3.age &lt;&lt; endl; p2 = p1 = p3; // 赋值操作 cout &lt;&lt; &quot;p1年龄为&quot; &lt;&lt; *p1.age &lt;&lt; endl; cout &lt;&lt; &quot;p2年龄为&quot; &lt;&lt; *p2.age &lt;&lt; endl; cout &lt;&lt; &quot;p3年龄为&quot; &lt;&lt; *p3.age &lt;&lt; endl;&#125; 五.关系运算符重载 class Person5 &#123; public: string name; int age; Person5(string name, int age) &#123; this-&gt;age = age; this-&gt;name = name; &#125; // 函数重载 bool operator==(Person5&amp; p) &#123; if (this-&gt;age == p.age &amp;&amp; this-&gt;name == p.name) &#123; return true; &#125; return false; &#125; bool operator!=(Person5&amp; p) &#123; if (this-&gt;age == p.age &amp;&amp; this-&gt;name == p.name) &#123; return false; &#125; return true; &#125;&#125;;void test05() &#123; Person5 p1(&quot;Tom&quot;, 18); Person5 p2(&quot;Tom&quot;, 18); if (p1 == p2) &#123; cout &lt;&lt; &quot;p1==p2&quot; &lt;&lt; endl; &#125; else &#123; cout &lt;&lt; &quot;p1!=p2&quot; &lt;&lt; endl; &#125;&#125; 六.函数调用运算符()重载[仿函数] class MyPrint &#123; public: void operator()(string test) &#123; cout &lt;&lt; test &lt;&lt; endl; &#125;&#125;;void MyPrint02(string test) &#123; cout &lt;&lt; test &lt;&lt; endl;&#125;void test06() &#123; MyPrint my; my(&quot;hello world&quot;); MyPrint02(&quot;hello world&quot;);&#125; 4.继承 继承的好处： 1.减少重复代码 2.子类也成为派生类，父类也称基类 语法:class子类:继承方式 父类 class BasePage &#123; public: void header() &#123; cout &lt;&lt; &quot;头部&quot; &lt;&lt; endl; &#125; void footer() &#123; cout &lt;&lt; &quot;脚部&quot; &lt;&lt; endl; &#125; void left() &#123; cout &lt;&lt; &quot;左侧&quot; &lt;&lt; endl; &#125;&#125;;class Java : public BasePage &#123; public: void content() &#123; cout &lt;&lt; &quot;Java内容&quot; &lt;&lt; endl; &#125;&#125;;class Python : public BasePage &#123; public: void content() &#123; cout &lt;&lt; &quot;Python内容&quot; &lt;&lt; endl; &#125;&#125;;void test01() &#123; Java ja; ja.header(); ja.footer(); ja.left(); ja.content(); Python py; py.header(); py.footer(); py.left(); py.content();&#125; 三种继承方式 优先级public&gt;protected&gt;private 公共继承 保护继承 私有继承 class Base1 &#123; public: int a; protected: int b; private: int c;&#125;;class Son1 : public Base1 &#123; public: void fun() &#123; a = 10; // 父类中的公共权限成员，到子类中依然是公共权限 b = 20; // 父类中的保护权限成员，到子类中依然是保护权限 // c = 30; // 报错，父类中的私有权限成员，到子类访问不到 &#125;&#125;;class Son2 : protected Base1 &#123; public: void fun() &#123; a = 10; // 父类中的公共权限成员，到子类中是保护权限 b = 20; // 父类中的保护权限成员，到子类中是保护权限 // c = 30; // 报错，父类中的私有权限成员，到子类访问不到 &#125;&#125;;class Son3 : private Base1 &#123; public: void fun() &#123; a = 10; // 父类中的公共权限成员，到子类中是私有权限 b = 20; // 父类中的保护权限成员，到子类中是私有权限 // c = 30; // 报错，父类中的私有权限成员，到子类访问不到 &#125;&#125;;class GrandSon3 : public Son3 &#123; public: void func() &#123; // a=100; // b=100; // c=100; // 父类不可访问或为私有，子类均不能访问 &#125;&#125;;void test02() &#123; Son1 s1; s1.a = 100; // s1.b=100; // 到Son1中b是保护权限，类外访问不到 // s1.c=100; // 到Son1中c是无法访问的 Son2 s2; // s2.a = 200; // 到Son2中a是保护权限，类外访问不到 // s2.b=200; // 到Son2中b是保护权限，类外访问不到 // s2.c=200; // 到Son2中c是无法访问的 Son3 s3; // s3.a = 300; // 到Son3中a是私有权限，类外访问不到 // s3.b=300; // 到Son3中b是私有权限，类外访问不到 // s3.c=300; // 到Son3中c是无法访问的&#125; 继承中的对象模型 class Base3 &#123; public: int a; protected: int b; private: int c;&#125;;class Son4 : public Base3 &#123; public: int d;&#125;;void test03() &#123; cout &lt;&lt; &quot;sizeof(Son4):&quot; &lt;&lt; sizeof(Son4) &lt;&lt; endl; // 16 // 父类中的所有非静态成员属性都会被子类继承下来 // 父类中的私有成员变量属性是被编译器隐藏了，因此访问不到，但确实被继承了&#125; 继承中的构造和析构顺序 class Base4 &#123; public: Base4() &#123; cout &lt;&lt; &quot;Base4-begin&quot; &lt;&lt; endl; &#125; ~Base4() &#123; cout &lt;&lt; &quot;Base4-end&quot; &lt;&lt; endl; &#125;&#125;;class Son5 : public Base4 &#123; public: Son5() &#123; cout &lt;&lt; &quot;Son5-begin&quot; &lt;&lt; endl; &#125; ~Son5() &#123; cout &lt;&lt; &quot;Son5-end&quot; &lt;&lt; endl; &#125;&#125;;void test04() &#123; // Base4 b; // 继承中的构造和析构的顺序如下： // 先构造父类，再构造子类，析构的顺序与构造相反 Son5 s;&#125; 继承中同名成员处理方式 class Base5 &#123; public: Base5() &#123; a = 10; &#125; void func() &#123; cout &lt;&lt; &quot;Base5-func()&quot; &lt;&lt; endl; &#125; void func(int a) &#123; cout &lt;&lt; &quot;Base5-func(&quot; &lt;&lt; a &lt;&lt; &quot;)&quot; &lt;&lt; endl; &#125; int a;&#125;;class Son6 : public Base5 &#123; public: Son6() &#123; a = 100; &#125; void func() &#123; cout &lt;&lt; &quot;Son6-func()&quot; &lt;&lt; endl; &#125; int a;&#125;;void test05() &#123; // 1.同名成员属性处理方式 Son6 s; cout &lt;&lt; s.a &lt;&lt; endl; cout &lt;&lt; s.Base5::a &lt;&lt; endl; // 如果通过子类对象访问父类中的同名对象，需要加作用域 // 2.同名成员函数处理方式 s.func(); s.Base5::func(); // s.func(100);//报错，若重名，子类会隐藏所有父类同名的函数 s.Base5::func(100); // 如果通过子类对象访问父类中的同名函数，需要加作用域&#125;// 继承中同名静态成员处理方式class Base6 &#123; public: Base6() &#123; a = 10; &#125; static void func() &#123; cout &lt;&lt; &quot;Base6-func()&quot; &lt;&lt; endl; &#125; static void func(int a) &#123; cout &lt;&lt; &quot;Base6-func(&quot; &lt;&lt; a &lt;&lt; &quot;)&quot; &lt;&lt; endl; &#125; static int a;&#125;;int Base6::a = 10;class Son7 : public Base6 &#123; public: Son7() &#123; a = 100; &#125; static void func() &#123; cout &lt;&lt; &quot;Son7-func()&quot; &lt;&lt; endl; &#125; static int a;&#125;;int Son7::a = 100;void test06() &#123; // 1.同名静态成员属性处理方式： // (1).通过对象访问 Son7 s; cout &lt;&lt; s.a &lt;&lt; endl; cout &lt;&lt; s.Base6::a &lt;&lt; endl; // (2).通过类名访问 cout &lt;&lt; Son7::a &lt;&lt; endl; cout &lt;&lt; Son7::Base6::a &lt;&lt; endl; // 第一个::代表通过类名访问，第二个::代表访问父类作用域下 // 2.同名静态成员函数处理方式： // (1).通过对象访问 s.func(); s.Base6::func(); s.Base6::func(100); // 如果通过子类对象访问父类中的同名函数，需要加作用域 // (2).通过类名访问 Son7::func(); Son7::Base6::func(); Son7::Base6::func(100);&#125; 多继承语法 class Base7 &#123; public: Base7() &#123; a = 10; &#125; int a;&#125;;class Base8 &#123; public: Base8() &#123; a = 100; &#125; int a;&#125;;class Son8 : public Base7, public Base8 &#123; public: Son8() &#123; c = 200; d = 300; &#125; int c, d;&#125;;void test07() &#123; Son8 s; cout &lt;&lt; &quot;sizeof(s)&quot; &lt;&lt; sizeof(s) &lt;&lt; endl; // 当父类中出现同名成员时，需要加作用域区分 cout &lt;&lt; &quot;s.Base7::a&quot; &lt;&lt; s.Base7::a &lt;&lt; endl; cout &lt;&lt; &quot;s.Base8::a&quot; &lt;&lt; s.Base8::a &lt;&lt; endl;&#125;// 菱形继承// 定义：两个派生类继承同一个基类，又有某个类同时继承两个派生类class Animal &#123; public: int age;&#125;;// 利用虚继承可以解决菱形继承的问题// Animal类成为虚基类class Sheep : virtual public Animal &#123;&#125;;class Tuo : virtual public Animal &#123;&#125;;class YangTuo : public Sheep, public Tuo &#123;&#125;;void test08() &#123; YangTuo y; y.Sheep::age = 18; y.Tuo::age = 28; // 当出现菱形继承，两个父类拥有相同的数据，需要加作用域区分 cout &lt;&lt; y.Sheep::age &lt;&lt; endl; cout &lt;&lt; y.Tuo::age &lt;&lt; endl; cout &lt;&lt; y.age &lt;&lt; endl;&#125; 5.多态 class Animal &#123; public: virtual void speak() &#123; cout &lt;&lt; &quot;speaking&quot; &lt;&lt; endl; &#125; // key code&#125;;class Cat : public Animal &#123; public: void speak() &#123; cout &lt;&lt; &quot;Cat-speaking&quot; &lt;&lt; endl; &#125;&#125;;class Dog : public Animal &#123; public: void speak() &#123; cout &lt;&lt; &quot;Dog-speaking&quot; &lt;&lt; endl; &#125;&#125;;void do_speak(Animal&amp; animal) &#123; //地址早绑定,在编译阶段就确定函数地址 animal.speak(); // 如果想让猫说话,需要地址晚绑定,故使用virtual关键字&#125; 动态多态满足条件: 1.有继承关系 2.子类重写父类的虚函数 动态多态使用 父类的指针或者引用执行子类对象 void test01() &#123; Cat cat; Dog dog; do_speak(cat); do_speak(dog); cout &lt;&lt; sizeof(Animal); // 指针占的空间&#125; 纯虚函数和抽象类 纯虚函数语法: 当类中含有纯虚函数,则这个类为抽象类 class Base &#123; public: virtual void func() = 0; // 纯虚函数 // 抽象类特点: // 1.无法实例化对象 // 2.抽象类的子类必须重写父类的纯虚函数,否则也为抽象类&#125;;class Son : public Base &#123; public: void func() &#123; cout &lt;&lt; &quot;Son-func()&quot; &lt;&lt; endl; &#125;&#125;;void test02() &#123; // Base b; // new Base; // 报错,抽象类无法实例化对象 Son s; // 子类必须重写父类的纯虚函数,否则无法实例化 s.func(); Base* base = new Son; base-&gt;func();&#125;// 虚析构与纯虚析构class Animal1 &#123; public: Animal1() &#123;&#125; virtual void speak() = 0; // virtual ~Animal1() &#123;&#125; // 利用虚析构可以解决父类指针释放子类对象不干净的问题 // 纯虚析构： // 纯虚析构需要声明也需要实现 // 有了纯虚析构之后，这个类也属于抽象类，无法实例化对象 virtual ~Animal1() = 0;&#125;;Animal1::~Animal1() &#123; cout &lt;&lt; &quot;纯虚析构&quot; &lt;&lt; endl;&#125;class Cat1 : public Animal1 &#123; public: Cat1(string name) &#123; this-&gt;name = new string(name); &#125; void speak() &#123; cout &lt;&lt; *name &lt;&lt; &quot; Cat1-speaking&quot; &lt;&lt; endl; &#125; ~Cat1() &#123; if (this-&gt;name != NULL) &#123; delete this-&gt;name; this-&gt;name = NULL; &#125; &#125; string* name;&#125;;void test03() &#123; Animal1* animal = new Cat1(&quot;Tom&quot;); animal-&gt;speak(); // 父类指针在析构时候，不会调用子类中的析构函数，导致子类如果有堆区属性，出现内存泄露 delete animal;&#125; Summary: 1.虚析构或纯虚析构就是用来解决通过父类指针释放子类对象 2.如果子类没有堆区数据，可以不写为虚析构或纯虚析构 3.拥有纯虚析构函数的类是抽象类

 Cpp_part3
 1.Constructor and destructor 构造和析构函数
destructor 析构
class Engine &#123;&#125;;class Car &#123;    Engine e;    Engine* pe;&#125;;class Test &#123;    int* p;  // handle句柄    int m;   // value   public:    Test(int i);    // void clean();    ~Test();&#125;;// Test::Test() &#123;&#125;// 报错，析构会形成野指针，造成程序崩溃Test::~Test() &#123;    cout &lt;&lt; &quot;destruct&quot; &lt;&lt; endl;    delete p;&#125;Test::Test(int i) &#123;    cout &lt;&lt; &quot;construct&quot; &lt;&lt; endl;    p = new int(i);&#125;// void Test::clean() &#123;//     delete p;// &#125;
 2.Static 静态变量
static 静态的
 Summary
1.static local var 一次构造，最后释放
2.static global function
本文件使用（将函数的可链接范围从默认从全局域限制为文件域）
3.static attribute 本类所有对象的共享内存
4.static method ,可以用本类类名直接调用，但内部不可操作非静态
// static// 静态局部变量void fun() &#123;    static int i = 0;    i++;    cout &lt;&lt; i &lt;&lt; endl;&#125;void fun_in_other_file();extern int g_int;// 声明 vs 定义//  对于变量而言，声明和定义的区别是你是否为其分配内存//  文件声明static只能在自己里面使用//  全局函数默认携带externclass Static &#123;    static int i;    int j;   public:    Static(int ai, int aj);&#125;;Static ::Static(int ai, int aj) &#123;    // i = ai;    // 报错，不允许修改（初始化）全局变量    j = aj;    // j++;    // 报错，无法正常访问    // 静态成员函数无this指针，所以也不能用this指针&#125;int Static::i = 100;
