#include &lt;bits/stdc++.h&gt;using namespace std;#define M 100007#define N 1007#define INF 0x3f3f3f3f#define ll long long#define db doubleint main(int argc, char* argv[]) &#123;    // malloc free    // new delete    static int a;    Test t(1);  //栈区    // t.clean();    // stack vs. heap    /*  int* i = new int;        int* j = new int;        cout &lt;&lt; i &lt;&lt; endl;        cout &lt;&lt; j &lt;&lt; endl;        if (1) &#123;            int m;            //结束自动析构        &#125; */    Test* t2 = new Test(3);  //堆区    delete t2;    //全局变量在main之前创建，main之后释放    test01();    // 设计模式design pattern    return 0;&#125;

