 Cpp_part5
 1.operator 重载运算符
class Account &#123;    int aid;    char* name;    int balance;       public:    Account(int id, int ab);    void SaveMoney(int money);    Account&amp; operator+(int money);    Account&amp; operator++();    Account operator++(int);&#125;;Account::Account(int id, int ab) &#123;    this-&gt;aid = id;    this-&gt;balance = ab;&#125;void Account::SaveMoney(int money) &#123;    this-&gt;balance += money;&#125;Account&amp; Account::operator+(int money) &#123;    this-&gt;balance += money;    return *this;&#125;Account Account::operator++(int) &#123;    Account a(*this);    this-&gt;balance++;    cout &lt;&lt; &quot;a++&quot; &lt;&lt; endl;    return a;&#125;  //带占位符的为后加加Account&amp; Account::operator++() &#123;    this-&gt;balance++;    cout &lt;&lt; &quot;++a&quot; &lt;&lt; endl;    return *this;&#125;void test01() &#123;    Account a(1001, 100);    a.SaveMoney(100);    a = a + 100;    a++;    ++a;&#125;
 2.new vs malloc
分配空间方面无区别，行为有区别，new会调用构造函数，而malloc不会调用构造
new = malloc + construction
delete = destruct + free [注意顺序问题]
class Test &#123;    int* p;   public:    Test();&#125;;Test::Test() &#123;    cout &lt;&lt; &quot;construction&quot; &lt;&lt; endl;    cout &lt;&lt; sizeof(Test) &lt;&lt; endl;  // 只有构造函数时，sizeof(Test)为1&#125;void test02() &#123;    // new vs. malloc    Test t;    Test* p = (Test*)malloc(sizeof(Test));    Test* q = new Test();&#125;
 Main part
#include &lt;bits/stdc++.h&gt;using namespace std;int main() &#123;    test01();  // Operator    test02();  // new delete    return 0;&#125;

 Cpp_part6
 1.inheritance 继承
延伸类，子类
class Base &#123;    int i;   public:    Base();    Base(int ai);&#125;;Base::Base(int ai) &#123;    this-&gt;i = ai;&#125;
写该函数必须保留父类默认构造，否则创建子类时会报错
Base::Base() &#123;    cout &lt;&lt; &quot;construct Base&quot; &lt;&lt; endl;&#125;class Derived : public Base &#123;    int j;   public:    Derived();    Derived(int ai, int aj);&#125;;Derived::Derived() &#123;    cout &lt;&lt; &quot;construct Derived&quot; &lt;&lt; endl;&#125;Derived::Derived(int ai, int aj) : Base(ai) &#123;    this-&gt;j = aj;    cout &lt;&lt; &quot;construct Derived&quot; &lt;&lt; endl;&#125;void test01() &#123;    Derived d;    //构建子类对象会调用父类构造函数，先父后子，析构函数同理（先子后父）    cout &lt;&lt; sizeof(Derived) &lt;&lt; endl;&#125;
class Engine &#123;    int i;   public:    Engine();    Engine(int ai);&#125;;Engine::Engine() &#123;    cout &lt;&lt; &quot;construct Engine&quot; &lt;&lt; endl;&#125;Engine::Engine(int ai) &#123;    this-&gt;i = ai;    cout &lt;&lt; &quot;construct Engine&quot; &lt;&lt; endl;&#125;class Car &#123;    Engine e;    int j;    int k;   public:    Car();    Car(int m);    Car(int ai, int aj);&#125;;Car::Car(int m) : j(m), k(j) &#123;    //按照变量定义顺序初始化，即k(m),j(k)会出现j为垃圾数的情况    cout &lt;&lt; &quot;test Car&quot; &lt;&lt; endl;    cout &lt;&lt; &quot;j:&quot; &lt;&lt; j &lt;&lt; endl;    cout &lt;&lt; &quot;k:&quot; &lt;&lt; k &lt;&lt; endl;&#125;Car::Car() : e(1) &#123;    cout &lt;&lt; &quot;construct Car&quot; &lt;&lt; endl;&#125;Car::Car(int ai, int aj) : e(ai) &#123;    this-&gt;j = aj;    cout &lt;&lt; &quot;construct Car&quot; &lt;&lt; endl;&#125;void test02() &#123;    Car c;    Car d(2);&#125;
 2.Polymorphic 多态
多态 Polymorphic:简单而言一行函数可能在不同情况调用不同的代码
class Pet &#123;    int i;   public:    virtual void speak();  //虚函数    virtual void sleep();&#125;;void Pet::speak() &#123;    cout &lt;&lt; &quot;Pet::speak&quot; &lt;&lt; endl;&#125;void Pet::sleep() &#123;    cout &lt;&lt; &quot;Pet::sleep&quot; &lt;&lt; endl;&#125;// 函数名是函数的首指针class Cat : public Pet &#123;   public:    void speak();&#125;;void Cat::speak() &#123;    cout &lt;&lt; &quot;miao miao&quot; &lt;&lt; endl;&#125;class Dog : public Pet &#123;   public:    void speak();&#125;;void Dog::speak() &#123;    cout &lt;&lt; &quot;wang wang&quot; &lt;&lt; endl;&#125;void handle(Pet&amp; pet) &#123;    pet.speak();    // binding:绑定，将一次函数调用与函数入口相对应的过程    // early binding    // later binding(runtime binding,dynamic binding)[多态]    // v-table 虚函数表    // v-ptr 虚指针    /*    // 代码区：函数（代码），常量，lib    // 全局变量区    // runtime memory:    // 1.stack 2.heap    */&#125;void test03() &#123;    Cat c;    c.speak();    handle(c);    Dog d;    d.speak();    handle(d);    //子类继承关系不要削弱父类的接口    cout &lt;&lt; sizeof(Pet) &lt;&lt; endl;    Cat c1, c2;    int* p = (int*)&amp;c1;    cout &lt;&lt; *p &lt;&lt; endl;    p = (int*)&amp;c2;    cout &lt;&lt; *p &lt;&lt; endl;&#125;
 Main part
#include &lt;bits/stdc++.h&gt;using namespace std;int main() &#123;    test01();    test02();    test03();    return 0;&#125;

 Cpp_part7
 1.abstract class 抽象类
 abstract class抽象类(第一类高级抽象)
 抽象类的限制：
1.抽象类不能实例化
2.对子类的继承复用性仍然存在
3.抽象类的作用在于提纲挈领
4.纯虚函数通常没有函数体，但可以有函数体
5.抽象类的纯虚函数通常都重写，但可以不重写，但会无法实例化
class Pet &#123;    int age;   public:    //  pure virtual 纯虚函数    virtual void speak() = 0;    virtual void sleep() = 0;&#125;;// void Pet::speak() &#123;//     cout &lt;&lt; &quot;Pet speak&quot; &lt;&lt; endl;// &#125;class Dog : public Pet &#123;   public:    // override    virtual void speak();    virtual void sleep();&#125;;void Dog::speak() &#123;    cout &lt;&lt; &quot;wang wang&quot; &lt;&lt; endl;&#125;void Dog::sleep() &#123;    cout &lt;&lt; &quot;dog sleep&quot; &lt;&lt; endl;&#125;void handle(Pet&amp; pet) &#123;    // 不加引用是拷贝构造的一个父类对象，所以会调用父类的speak()    // never pass by value    pet.speak();&#125;void test01() &#123;    Dog dog;    // a = 10;    handle(dog);    dog.sleep();&#125;
 2.虚函数
虚函数
1.constructor是唯一的确认的调用，不会和多态产生关系
2.destructor大多与多态产生关系
3.串联(类似java的interface)(第二类高级抽象)
class Test &#123;   public:    Test();    virtual ~Test();    // 父类为虚函数才能调用子类析构&#125;;Test::Test() &#123;&#125;Test::~Test() &#123;    cout &lt;&lt; &quot;~Test&quot; &lt;&lt; endl;&#125;class Derived : public Test &#123;   public:    Derived();    ~Derived();&#125;;Derived::Derived() &#123;&#125;Derived::~Derived() &#123;    cout &lt;&lt; &quot;~Derived&quot; &lt;&lt; endl;&#125;void fun(Test* p) &#123;    delete p;&#125;void test02() &#123;    Dog dog;    Dog* pdog = new Dog;    // Pet pet;    // Pet* ppet = new Dog;    Derived* p = new Derived;    fun(p);&#125;class Fly_object &#123;   public:    virtual void fly() = 0;&#125;;class Animal &#123;   public:    void fly();&#125;;class Bird : public Animal, public Fly_object &#123;   public:    void fly();&#125;;void Bird::fly() &#123;    cout &lt;&lt; &quot;Bird fly&quot; &lt;&lt; endl;&#125;class Machine &#123;   public:    void fly();&#125;;class Airplane : public Machine, public Fly_object &#123;   public:    void fly();&#125;;void Airplane::fly() &#123;    cout &lt;&lt; &quot;Airplane fly&quot; &lt;&lt; endl;&#125;void follow(Fly_object&amp; f) &#123;    f.fly();&#125;void test03() &#123;    Bird b;    Airplane a;    follow(b);    follow(a);&#125;
 3.template 模板
// 代码重用的另一类拷贝形式//  container 容器//  模板template &lt;typename T&gt;class Stack &#123;    T pool[100];    int top;   public:    Stack();    T Pop();    void Push(T a);&#125;;template &lt;typename T&gt;Stack&lt;T&gt;::Stack() : top(-1) &#123;&#125;template &lt;typename T&gt;T Stack&lt;T&gt;::Pop() &#123;    return pool[top--];&#125;template &lt;typename T&gt;void Stack&lt;T&gt;::Push(T a) &#123;    pool[++top] = a;&#125;void test04() &#123;    Stack&lt;int&gt; s;    for (int i = 0; i &lt; 10; i++) &#123;        s.Push(i * i);    &#125;    for (int i = 0; i &lt; 10; i++) &#123;        cout &lt;&lt; s.Pop() &lt;&lt; endl;    &#125;    Stack&lt;double&gt; ds;    for (int i = 0; i &lt; 10; i++) &#123;        ds.Push(i * i + 0.1);    &#125;    for (int i = 0; i &lt; 10; i++) &#123;        cout &lt;&lt; ds.Pop() &lt;&lt; endl;    &#125;&#125;
 STL:Standard Template Library 动态增长的万能容器
void test05() &#123;    vector&lt;int&gt; v;    for (int i = 0; i &lt; 2000; i++) &#123;        v.push_back(i);    &#125;    cout &lt;&lt; v.size() &lt;&lt; endl;    v.pop_back();    cout &lt;&lt; v.back() &lt;&lt; endl;    cout &lt;&lt; v[200] &lt;&lt; endl;&#125;
