package note_file.Class_Object.Inherit;public class Demo &#123;  public static void main(String[] args) &#123;    Fu f = new Fu();    f.show();    Zi z1 = new Zi();    // 复习：主要在new时就已经使用了无参构造方法的调用    // Zi中无参构造方法被调用时会先调用Fu的无参构造方法    z1.method();    // 调用父辈继承    z1.show();    Zi z2 = new Zi(19);    // Zi中带参构造方法被调用时会先调用Fu的无参构造方法    z2.method();  &#125;&#125;
