package note_file.Class_Object.Inherit;public class Fu &#123;  public int age = 40;  public void show() &#123;    System.out.println(&quot;Fu_age:\t\t&quot; + age);  &#125;  public Fu() &#123;    System.out.println(&quot;Fu无参构造方法被调用&quot;);  &#125;  public Fu(int age) &#123;    System.out.println(&quot;Fu带参构造方法被调用&quot;);  &#125;  // 以上两个方法为方法重载&#125;
 Zi.java
package note_file.Class_Object.Inherit;public class Zi extends Fu &#123;  // 上面一行使用了继承,一个子类只能继承一个父类，但可以存在多层继承  public int height = 175;  public int age = 20;  // 子类有相同变量时会覆盖父类的继承  public void method() &#123;    int age = 30;    System.out.println(&quot;Zi_temp_age:\t&quot; + age);    // age的访问顺序为方法-&gt;成员变量-&gt;父辈成员变量,若要越级访问成员变量需要使用this指针，若要越级访问父辈成员变量需要使用super指针    System.out.println(&quot;Zi_age:\t\t&quot; + this.age);    System.out.println(&quot;Fu_age\t\t&quot; + super.age);    System.out.println(&quot;Zi_height:\t&quot; + height);  &#125;  // 子类有相同方法时会覆盖父类的继承  // 子类不能重写父类的private方法  public Zi() &#123;    System.out.println(&quot;Zi无参构造方法被调用&quot;);  &#125;  public Zi(int age) &#123;    super(20);// 通过这种方法调用父辈的带参构造方法，一般不写默认存在一个super();    System.out.println(&quot;Zi带参构造方法被调用&quot;);  &#125;  // 类中已经写了带参的构造方法，系统将不再提供无参的构造方法&#125;

