package note_file.Class_Object.Inner_Class;public class Outer &#123;  private int num1 = 10;  private class Inner_first &#123;    // 在类里面定义类即为内部类    public void show() &#123;      System.out.println(num1);    &#125;  &#125;// 成员内部类   // 注：内部类的作用是防止外界访问，故多为private  public void Inner_first_demo() &#123;    Inner_first i = new Inner_first();    i.show();  &#125;  public void Inner_second_demo() &#123;    int num2 = 20;    class Inner_second &#123;      public void show() &#123;        System.out.println(num1);        System.out.println(num2);      &#125;    &#125;// 局部内部类     // [tips:注意定义类时Inner_second后没有括号(),否则会报错(因为这不是一个方法)]    Inner_second i = new Inner_second();    i.show();  &#125;  public void Inner_third_demo() &#123;    new Inner_third() &#123;      // 这里的Inner_third是创建的一个接口      @Override      public void show() &#123;        System.out.println(&quot;匿名内部类&quot;);      &#125;      // 创建匿名内部类    &#125;.show();// 匿名内部类的本质是一个继承该类或者实现该接口的子类匿名对象，故可以调用方法(show();)    // 也可以调用如下方法实现匿名内部类    // Inter i=new Inner_third() &#123;    // @Override    // public void show() &#123;    // System.out.println(&quot;匿名内部类&quot;);    // &#125;    // &#125;    // i.show();  &#125;  /*   * Summary:   * 1.内部类可以直接访问外部类的成员，包括私有   * 2.外部类要访问内部类的成员，必须创建对象   */&#125;

