package note_file.Basis.Collection_Class;import java.util.ArrayList;import java.util.Collection;import java.util.Iterator;public class Collection_demo1 &#123;  public static void main(String[] args) &#123;    // 创建Collection集合对象    Collection&lt;String&gt; c = new ArrayList&lt;&gt;();// 多态构造    // 添加元素    c.add(&quot;hello&quot;);    c.add(&quot;world&quot;);    c.add(&quot;java&quot;);    System.out.println(c);    // 删除元素    if (c.contains(&quot;hello&quot;)) &#123;// 判断是否存在指定元素      c.remove(&quot;hello&quot;);    &#125;    // 遍历    // 方法一    for (int i = 0; i &lt; c.size(); i++) &#123;      System.out.println(((ArrayList&lt;String&gt;) c).get(i));// 向下转型,注意用ArrayList&lt;&gt;时要加类型    &#125;    // 方法二    Iterator&lt;String&gt; it = c.iterator();// 迭代器    while (it.hasNext()) &#123;      String s = it.next();      System.out.println(s);    &#125;    if (!c.isEmpty()) &#123;// 判断是否为空集合      c.clear();// 清空    &#125;  &#125;&#125;
