package note_file.Basis.Collection_Class;import java.util.ArrayList;import java.util.Collection;import java.util.Iterator;import java.util.LinkedList;import java.util.List;import java.util.ListIterator;public class List_demo1 &#123;  public static void main(String[] args) &#123;    List&lt;String&gt; list = new ArrayList&lt;&gt;();    /*     * List特点:[感觉就是队列]     * 1.有序：存储和取出元素顺序相同     * 2.可重复：存储的元素可以重复     */    list.add(&quot;hello&quot;);    list.add(&quot;world&quot;);    list.add(&quot;java&quot;);    list.add(&quot;world&quot;);    list.add(3, &quot;NBA champion&quot;);// 在index处插入element    list.remove(2);    list.remove(&quot;hello&quot;);    list.set(2, &quot;Stephen Curry&quot;);// 修改index处的值为element    // 遍历    // 方法一    Iterator&lt;String&gt; it = list.iterator();    while (it.hasNext()) &#123;      String s = it.next();      /*       * if (s.equals(&quot;world&quot;)) &#123;// 此代码会引起并发修改异常       * list.add(&quot;JDK&quot;);       * &#125;       */      // 迭代器运行过程中代码不能修改集合的长度，否则就会出现并发修改异常      System.out.println(s);    &#125;    // 方法二    for (int i = 0; i &lt; list.size(); i++) &#123;      String s = list.get(i);      if (s.equals(&quot;world&quot;)) &#123;        list.add(&quot;JDK&quot;);      &#125;      System.out.println(list.get(i));    &#125; // 这种遍历方式可以做如上操作    System.out.println(list);    // listIterator    ListIterator&lt;String&gt; lit = list.listIterator();    while (lit.hasNext()) &#123;      String s = lit.next();      if (s.equals(&quot;world&quot;)) &#123;        lit.add(&quot;Java&quot;);      &#125;      System.out.println(s);    &#125; // 这种方法不会出现并行修改异常    while (lit.hasPrevious()) &#123;      String s = lit.previous();      System.out.println(s);    &#125;    // 有点鸡肋，必须先向后才能向前    // 增强for循环    for (String s : list) &#123;      System.out.println(s);    &#125; // 本质是Iterator迭代器    /*     * ArrayList底层数据结构为数组     * LinkedList底层数据结构为链表     */    LinkedList&lt;String&gt; linked_list = new LinkedList&lt;String&gt;();    linked_list.add(&quot;hello&quot;);    linked_list.add(&quot;world&quot;);    linked_list.add(&quot;java&quot;);    // LinkedList遍历    Iterator&lt;String&gt; linked_it = linked_list.iterator();    while (linked_it.hasNext()) &#123;      System.out.println(linked_it.next());    &#125;    for (String s : linked_list) &#123;      System.out.println(s);    &#125;    // LinkedList的特有操作    linked_list.addFirst(&quot;NBA&quot;);// 头结点操作    linked_list.addLast(&quot;Curry&quot;);// 尾结点操作    System.out.println(linked_list.removeFirst());// 删除头结点并返回    System.out.println(linked_list.removeLast());// 删除尾结点并返回    System.out.println(linked_list.getFirst());// 获得第一个元素    System.out.println(linked_list.getLast());// 获得尾元素    System.out.println(linked_list.getClass());// 获得类[这个不是特有]  &#125;&#125;

