package note_file.Basis.Date_Class;import java.util.Calendar;public class Calendar_Class &#123;  public static void main(String[] args) &#123;    // 获得对象    Calendar c = Calendar.getInstance();// 通过源代码发现是通过多态创造的对象    print_date(c);    c.add(Calendar.YEAR, -3);// 减去3年    c.add(Calendar.MONTH, 6);    print_date(c);    c.set(Calendar.YEAR, 2022);    print_date(c);    c.set(2012, 11, 27);// 注意print_date时会把月加一，故输出12月要设置为11月    print_date(c);  &#125;  public static void print_date(Calendar c) &#123;    int year = c.get(Calendar.YEAR);    int month = c.get(Calendar.MONTH) + 1;// month从0开始，所以要加一    int date = c.get(Calendar.DATE);    System.out.println(year + &quot;年&quot; + month + &quot;月&quot; + date + &quot;日&quot;);  &#125;&#125;
