 3.Map_Class
Map_Classpackage note_file.Basis.Map_Class;import java.util.Collection;import java.util.HashMap;import java.util.Map;import java.util.Set;import java.util.Map.Entry;/* * Map集合特点: * Interface Map&lt;K,V&gt; K:键的类型 V:值的类型 * 1.将键映射到值的对象，不能包含重复的键，每个键可以映射到一个值 * 2.创建Map对象采用多态的方法，具体实现类HashMap */public class Map_demo1 &#123;  public static void main(String[] args) &#123;    Map&lt;String, String&gt; map = new HashMap&lt;&gt;();    // Map用put方法添加    map.put(&quot;21373191&quot;, &quot;charles&quot;);    map.put(&quot;21373188&quot;, &quot;tom&quot;);    map.put(&quot;21373181&quot;, &quot;jarry1&quot;);    map.put(&quot;21373182&quot;, &quot;jarry1&quot;);    // 当值重复时会加入Map中    map.put(&quot;21373181&quot;, &quot;jarry2&quot;);    // 当键重复时会覆盖原来键的值    System.out.println(map);// 输出结果没有按顺序    System.out.println(map.remove(&quot;21373182&quot;));// 按键删除，返回该键对应的值    if (map.containsKey(&quot;21373181&quot;)) &#123;      map.put(&quot;21373181&quot;, &quot;jarry&quot;);    &#125;    if (map.containsValue(&quot;charles&quot;)) &#123;      System.out.println(map.size());    &#125;    System.out.println(map.get(&quot;21373191&quot;));// get根据键获取值，没有则返回null    Set&lt;String&gt; keySet = map.keySet();    for (String key : keySet) &#123;      System.out.println(key);    &#125; // keySet用于获取键的集合    Collection&lt;String&gt; values = map.values();    for (String val : values) &#123;      System.out.println(val);    &#125; // Values用于获取值的集合    // Map集合遍历    // 方法1    for (String key : keySet) &#123;      String value = map.get(key);      System.out.println(key + &quot;,&quot; + value);    &#125;    // 方法2    Set&lt;Entry&lt;String, String&gt;&gt; entrySet = map.entrySet();    for (Entry&lt;String, String&gt; me : entrySet) &#123;      System.out.println(me.getKey() + &quot;,&quot; + me.getValue());    &#125;    if (!map.isEmpty()) &#123;      map.clear();    &#125;  &#125;&#125;

