package note_file.Basis.Object_Class;public class Object_Class &#123;  public static void main(String[] args) &#123;    Student s1 = new Student();    s1.setName(&quot;charles&quot;);    s1.setAge(19);    System.out.println(s1);// note_file.Basis.Object_Class.Student@28a418fc    /*     * 重写前为：     * public String toString() &#123;     * return getClass().getName() + &quot;@&quot; + Integer.toHexString(hashCode());     * &#125;     */    System.out.println(s1.toString());// 选中后按F3可以看到源代码    Student s2 = new Student();    s2.setName(&quot;Lily&quot;);    s2.setAge(43);    // System.out.println(s1 == s2);[这种方式是比较地址是否相同]    System.out.println(s1.equals(s2));// 这种方式是比较内容是否相同,但需要重写,若不重写和上面一行代码作用相同    /*     * 源码：     * public boolean equals(Object obj) &#123;     * return (this == obj);     * &#125;     */  &#125;&#125;
 student.java
package note_file.Basis.Object_Class;public class Student &#123;  // 默认继承Object方法  private String name;  private int age;  public Student() &#123;  &#125;  public Student(String name, int age) &#123;    this.name = name;    this.age = age;  &#125;  public String getName() &#123;    return name;  &#125;  public void setName(String name) &#123;    this.name = name;  &#125;  public int getAge() &#123;    return age;  &#125;  public void setAge(int age) &#123;    this.age = age;  &#125;  @Override  public String toString() &#123;    return &quot;Student [age=&quot; + age + &quot;, name=&quot; + name + &quot;]&quot;;  &#125;// 建议子类重写toString方法,利用Alt+Shift+S后按toString(),即可重写  @Override  public boolean equals(Object obj) &#123;    if (this == obj)      // 若地址相同，直接返回true      return true;    if (obj == null)      // 判断参数是否为null      return false;    if (getClass() != obj.getClass())      // 判断两个对象是否来自同一个类      return false;    Student other = (Student) obj;// 向下转型    if (age != other.age)      return false;    if (name == null) &#123;      if (other.name != null)        return false;    &#125; else if (!name.equals(other.name))      return false;    return true;  &#125;// 建议子类重写equals方法,同时生成了hashCode(),删除即可&#125;

