 HashSet_Class
package note_file.Basis.Set_Class;/* * HashSet集合特点: * 1.底层数据结构是哈希表 * 2.对集合的迭代顺序不作任何保证，元素存储和取出的顺序不一定一致 * 3.没有带索引的方法，所以不能使用for循环遍历 * 4.由于是Set集合，所以不能含有重复元素 * 5.HashSet集合存储元素，要保证元素的唯一性，需要重写hashCode()和equals() */import java.util.HashSet;public class HashSet_Class &#123;  public static void main(String[] args) &#123;    HashSet&lt;String&gt; hs = new HashSet&lt;&gt;();    hs.add(&quot;hello&quot;);    hs.add(&quot;world&quot;);    hs.add(&quot;java&quot;);    // 遍历    for (String s : hs) &#123;      System.out.println(s);    &#125;    // 无重复元素    hs.add(&quot;java&quot;);    System.out.println(hs);// 未按顺序  &#125;&#125;
 LinkedHashSet_Class
package note_file.Basis.Set_Class;import java.util.LinkedHashSet;/** LinkedHashSet特点:* 1.hash表和链表实现的Set接口，具有可预测的迭代次序* 2.由链表保证元素有序，也就是说元素的存储和取出顺序一致* 3.由hash表保证元素唯一，也就是说没有重复元素*/public class LinkedHashSet_Class &#123;  public static void main(String[] args) &#123;    LinkedHashSet&lt;String&gt; lhs = new LinkedHashSet&lt;&gt;();    lhs.add(&quot;hello&quot;);    lhs.add(&quot;world&quot;);    lhs.add(&quot;java&quot;);    for (String s : lhs) &#123;      System.out.println(s);    &#125;    lhs.add(&quot;world&quot;);    System.out.println(lhs);  &#125;&#125;
 Set_demo1.java
package note_file.Basis.Set_Class;import java.util.HashSet;import java.util.Iterator;import java.util.Set;public class Set_demo1 &#123;  /*   * Set特点：   * 1.Set是不包含重复元素的集合   * 2.没有带索引的方法，所以不能使用for循环遍历   * 3.Set是一个接口，不能直接建立对象   * HashSet   */  public static void main(String[] args) &#123;    Set&lt;String&gt; set = new HashSet&lt;String&gt;();    set.add(&quot;hello&quot;);    set.add(&quot;world&quot;);    set.add(&quot;java&quot;);    // 两种遍历方法    for (String s : set) &#123;      System.out.println(s);    &#125;    Iterator&lt;String&gt; it = set.iterator();    while (it.hasNext()) &#123;      System.out.println(it.next());    &#125;    // 不包含重复元素    set.add(&quot;world&quot;);    System.out.println(set);  &#125;&#125;
 Student_hash.java
package note_file.Basis.Set_Class;public class Student_hash implements Comparable&lt;Student_hash&gt; &#123;  private String name;  private int age;  public Student_hash() &#123;  &#125;  public Student_hash(String name, int age) &#123;    this.name = name;    this.age = age;  &#125;  public String getName() &#123;    return name;  &#125;  public void setName(String name) &#123;    this.name = name;  &#125;  public int getAge() &#123;    return age;  &#125;  public void setAge(int age) &#123;    this.age = age;  &#125;  @Override  public int hashCode() &#123;    final int prime = 31;    int result = 1;    result = prime * result + age;    result = prime * result + ((name == null) ? 0 : name.hashCode());    return result;  &#125;  @Override  public boolean equals(Object obj) &#123;    if (this == obj)      return true;    if (obj == null)      return false;    if (getClass() != obj.getClass())      return false;    Student_hash other = (Student_hash) obj;    if (age != other.age)      return false;    if (name == null) &#123;      if (other.name != null)        return false;    &#125; else if (!name.equals(other.name))      return false;    return true;  &#125;  // 排序时需要在类中连接Comparable接口并重写如下方法compareTo  @Override  public int compareTo(Student_hash o) &#123;    int num = this.age - o.age;    // 升序就把this放前面，降序就把this放后面    int num2 = num == 0 ? this.name.compareTo(o.name) : num;// String中自带compareTo以实现字母序    return num2;  &#125;&#125;
 TreeSet_Class
package note_file.Basis.Set_Class;import java.util.Comparator;/* * TreeSet集合特点: * 1.元素有序，具体排序方式取决于构造方法 * 2.没有带索引的方法，所以不能使用普通for循环遍历 * 3.由于是Set集合，所以不包含重复元素 */import java.util.TreeSet;public class TreeSet_Class &#123;  public static void main(String[] args) &#123;    TreeSet&lt;Integer&gt; ts = new TreeSet&lt;&gt;();// 存储类型为对应的包装类型    ts.add(10);// 自动装箱    ts.add(40);    ts.add(30);    ts.add(50);    ts.add(30);// 不包含重复元素    for (Integer i : ts) &#123;      System.out.println(i);    &#125; // 自动排序    // 创建学生集合并按年龄从小到大排序，年龄相同时按字母序    TreeSet&lt;Student_hash&gt; t = new TreeSet&lt;&gt;(new Comparator&lt;Student_hash&gt;() &#123;      @Override      public int compare(Student_hash o1, Student_hash o2) &#123;        int num = o1.getAge() - o2.getAge();        int num2 = num == 0 ? o1.getName().compareTo(o2.getName()) : num;// String中自带compareTo以实现字母序        return num2;      &#125;    &#125;);// 类似快排的cmp,但实际底层数据结构是hash加链表    // 这里可以用Comparator构造排序规则，也可以在Student_hash类中连接Comparable接口并重写规则    Student_hash s1 = new Student_hash(&quot;charles&quot;, 19);    Student_hash s2 = new Student_hash(&quot;Lily&quot;, 43);    Student_hash s3 = new Student_hash(&quot;angel&quot;, 17);    Student_hash s4 = new Student_hash(&quot;Lily&quot;, 43);    t.add(s1);    t.add(s2);    t.add(s3);    t.add(s4);    for (Student_hash i : t) &#123;      System.out.println(i.getName() + &quot; &quot; + i.getAge());    &#125;  &#125;&#125;

