package note_file.Basis.Thread_Class.Box;public class Box &#123;  private int milk;  private boolean state = false;  public synchronized void put(int milk) &#123;    if (state) &#123;      try &#123;        wait();// 使该线程处于等待中      &#125; catch (InterruptedException e) &#123;        e.printStackTrace();      &#125;    &#125;    this.milk = milk;    System.out.println(&quot;送奶工将第&quot; + this.milk + &quot;瓶奶放入奶箱&quot;);    state = true;    notifyAll();// 唤醒其他等待的线程  &#125;  public synchronized void get() &#123;    if (!state) &#123;      try &#123;        wait();      &#125; catch (InterruptedException e) &#123;        e.printStackTrace();      &#125;    &#125;    System.out.println(&quot;用户拿到第&quot; + this.milk + &quot;瓶奶&quot;);    state = false;    notifyAll();  &#125;&#125;
