package note_file.Basis.Thread_Class;import java.util.concurrent.locks.Lock;import java.util.concurrent.locks.ReentrantLock;public class Sell_ticket implements Runnable &#123;  private int tickets = 100;  private Lock lock = new ReentrantLock();// 设置锁  /*   * (non-Javadoc)   *    * @see java.lang.Runnable#run()   */  @Override  public void run() &#123;    while (true) &#123;      try &#123;        lock.lock();        if (tickets &gt; 0) &#123;          try &#123;            Thread.sleep(100);          &#125; catch (InterruptedException e) &#123;            e.printStackTrace();          &#125;          System.out.println(Thread.currentThread().getName() + &quot;正在出售第&quot; + (101 - tickets) + &quot;张票&quot;);          tickets--;        &#125;      &#125; finally &#123;        lock.unlock();      &#125;    &#125;  &#125;&#125;
 Thread_demo1.java
package note_file.Basis.Thread_Class;public class Thread_demo1 &#123;  public static void main(String[] args) &#123;    MyThread my1 = new MyThread();    MyThread my2 = new MyThread();    my1.run();    my2.run();    // 以上两行代码未启动线程    // 设置名称    // 方法1    my1.setName(&quot;charles&quot;);    my2.setName(&quot;Lily&quot;);    my1.start();    my2.start();    // 方法2：此方法需要重写方法    MyThread my3 = new MyThread(&quot;charles&quot;);    MyThread my4 = new MyThread(&quot;Lily&quot;);    my3.start();    my4.start();    // 方法3    System.out.println(Thread.currentThread().getName());// 返回当前执行线程的名字    // void start()导致此线程开始执行，Java虚拟机调用此线程的run方法    // 由运行结果可知运行为多线程运行    /*     * 线程调度     * 1.线程调度分为分时调度和抢占式调度，而java为抢占式调度     */    MyThread by = new MyThread(&quot;公交车&quot;);    MyThread ty = new MyThread(&quot;火车&quot;);    System.out.println(by.getPriority());    System.out.println(ty.getPriority());// 线程的默认优先级为5    ty.setPriority(4);// 优先级为[1,10]    // 注：优先级高仅仅是排名靠前的几率高    by.start();    ty.start();    /*     * 多线程的实现方式有两种:     * 1.继承Thread类     * 2.实现runnable接口     */  &#125;&#125;
