package note_file.Basis.other;public class Constant_value &#123;  public static void main(String[] args) &#123;    System.out.println(&quot;Hello World&quot;);    System.out.println(&quot;Hello Java&quot;);    int a = 10;    System.out.println(a);    boolean b = true;    System.out.println(b);    char c = &#x27;A&#x27;;    System.out.println(c);    float f = 13.14f;    System.out.println(f);    byte e = 10;    System.out.println(e);    int num1 = 10, num2 = 20;    System.out.println(num1 + num2);    // 字符串拼接    System.out.println(&quot;i&#x27;m &quot; + &quot;charles&quot;);    System.out.println(20 + 2002 + &quot; NBA Champion&quot;);  &#125;&#125; Control_Statement
package note_file.Basis.other;import java.util.Scanner;import java.util.Random;public class Control_Statement &#123;  public static void main(String[] args) &#123;    try (Scanner sc = new Scanner(System.in)) &#123;      int a = sc.nextInt();      int b = sc.nextInt();      if (a &gt; b) &#123;        System.out.println(a - b);      &#125; else if (a &lt; b) &#123;        System.out.println(b - a);      &#125; else &#123;        System.out.println(&quot;a和b相等&quot;);      &#125;      switch (a) &#123;        case 1:          System.out.println(&quot;good&quot;);          break;        case 2:          System.out.println(&quot;excellent&quot;);          break;        default:          System.out.println(&quot;sorry&quot;);      &#125;      for (int i = 1; i &lt;= a; i++) &#123;        System.out.println(&quot;b:&quot; + b);      &#125;    &#125;    Random r = new Random();    // 获取随机数    int num = r.nextInt(10);    // 随机数范围0&lt;=num&lt;10    System.out.println(&quot;num:&quot; + num);  &#125;&#125; Input
package note_file.Basis.other;import java.util.Scanner;// 导包public class Input &#123;  public static void main(String[] args) &#123;    // 创建对象    try (Scanner sc = new Scanner(System.in)) &#123;// 这行try是自动修复后自己添加的，暂时不知道是什么作用      // 接收数据      int x = sc.nextInt();      // 输出数据      System.out.println(&quot;x:&quot; + x);    &#125;  &#125;&#125; Integer_Class
package note_file.Basis.other;public class Integer_Class &#123;  public static void main(String[] args) &#123;    /*     * 基本数据类型和包装类之间的转化：     * byte-&gt;Byte;     * short-&gt;Short;     * int-&gt;Integer;     * long-&gt;Long;     * float-&gt;Float;     * double-&gt;Double;     * char-&gt;Character;     * boolean-&gt;Boolean;     * String本身就是包装类,底层为char[]数组     */    System.out.println(Integer.MAX_VALUE);    System.out.println(Integer.MIN_VALUE);    // Integer i1 = new Integer(100);    // System.out.println(i1);[该方法已过时，但可以使用，与valueof()效果相同]    Integer i_1 = Integer.valueOf(100);    System.out.println(i_1);    // Integer i2 = new Integer(&quot;100&quot;);//注：所写字符串必须为数字构成的字符串    // System.out.println(i2);[该方法已过时，但可以使用，与valueof()效果相同]    Integer i_2 = Integer.valueOf(&quot;100&quot;);    System.out.println(i_2);    // int -&gt; String 的转化    int number = 100;    // 方法1：    String s1 = &quot;&quot; + number;    System.out.println(s1);    // 方法2：    String s2 = String.valueOf(number);    System.out.println(s2);    // String -&gt; int 的转化    String s = &quot;100&quot;;    // 方法1：String-&gt;Integer-&gt;int    Integer it1 = Integer.valueOf(s);    int i1 = it1.intValue();    System.out.println(i1);    // 方法2：String-&gt;int    int i2 = Integer.parseInt(s);    System.out.println(i2);    // 自动装箱和拆箱：    // 1.装箱：把基本数据类型转化为相应的包装类类型    // 2.拆箱：把包装类类型转化为基本数据类型    Integer i = Integer.valueOf(100);// 装箱    Integer ii = 100;// 自动装箱    i = i.intValue() + 200;// i.intValue()为拆箱    ii += 200;// 自动拆箱(自动拆箱的前提为ii不为null)    System.out.println(ii);    // 将重构(即快速引进变量)改为了快捷键Shift+Alt+Z  &#125;&#125; Math_Class
package note_file.Basis.other;import java.util.Scanner;public class Math_Class &#123;  public static void main(String[] args) &#123;    try (Scanner sc = new Scanner(System.in)) &#123;      int a = sc.nextInt();      int b = sc.nextInt();      double c = sc.nextDouble();      double d = sc.nextDouble();      System.out.println(Math.abs(a));      System.out.println(Math.ceil(c));      System.out.println(Math.floor(d));      System.out.println(Math.round(c));      System.out.println(Math.max(a, b));      System.out.println(Math.min(a, b));      System.out.println(Math.pow(c, d));    &#125;    System.out.println(Math.random());    // 返回[0.0,1.0)为double的正值[通过乘以一定的倍数或强制类型转化以获得固定范围的随机数]  &#125;&#125; Method
package note_file.Basis.other;import java.util.Scanner;public class Method &#123;  public static void main(String[] args) &#123;    try (Scanner sc = new Scanner(System.in)) &#123;      int val = sc.nextInt();      if (is_Even(val)) &#123;        System.out.println(true);      &#125; else &#123;        System.out.println(false);      &#125;      System.out.println(sum(val, val));      System.out.println(sum(val, val, val));      change_num(val);      System.out.println(val);    &#125;  &#125;  public static boolean is_Even(int num) &#123;    if (num % 2 == 0) &#123;      return true;    &#125; else &#123;      return false;    &#125;  &#125;  // Java中叫方法，也就是C中的函数，使用方法和C中几乎相同  public static int sum(int a, int b, int c) &#123;    return a + b + c;  &#125;  public static int sum(int a, int b) &#123;    return a + b;  &#125;  // 以上几行代码为方法重载(类型不同或数量不同均可，返回值不同不可)  public static void change_num(int num) &#123;    num = 20;  &#125;  // 调用形参，不发生值变化&#125; String_Class
package note_file.Basis.other;import java.util.Scanner;public class String_Class &#123;  public static void main(String[] args) &#123;    // 空对象    String s1 = new String();    System.out.println(&quot;s1:&quot; + s1);    // 字符数组    char[] chs = &#123; &#x27;a&#x27;, &#x27;b&#x27;, &#x27;c&#x27; &#125;;    String s2 = new String(chs);    System.out.println(&quot;s2:&quot; + s2);    // 字节数组    byte[] bys = &#123; 97, 98, 99 &#125;;    String s3 = new String(bys);    System.out.println(&quot;s3:&quot; + s3);    // 直接赋值(最常用)    String s4 = &quot;abc&quot;;    System.out.println(&quot;s4:&quot; + s4);    // 字符串比较    System.out.println(s3.equals(s4));    // 遍历字符串    try (Scanner sc = new Scanner(System.in)) &#123;      String s5 = sc.nextLine();      for (int i = 0; i &lt; s5.length(); i++) &#123;        System.out.println(s5.charAt(i));        /* 返回指定索引处的char值 */      &#125;    &#125;    // 注意字符串的拼接可以直接使用+  &#125;&#125; StringBuilder_Class
package note_file.Basis.other;public class StringBuilder_Class &#123;  public static void main(String[] args) &#123;    // 空对象    StringBuilder sb1 = new StringBuilder();    sb1.append(&quot;hello world&quot;);    // 字符串添加    System.out.println(&quot;sb1:&quot; + sb1);    System.out.println(&quot;sb1.length():&quot; + sb1.length());    // 可变字符串对象    StringBuilder sb2 = new StringBuilder(&quot;hello world&quot;);    System.out.println(&quot;sb2:&quot; + sb2);    System.out.println(&quot;sb2.length():&quot; + sb2.length());    // 字符串删除(删除start &lt;= str &lt; end)    sb1.delete(5, 11);    System.out.println(&quot;sb1:&quot; + sb1);    System.out.println(&quot;sb1.length():&quot; + sb1.length());    // 链式编程    sb1.append(&quot; world&quot;).append(&quot; Java&quot;).append(&quot; C++&quot;);    System.out.println(&quot;sb1:&quot; + sb1);    System.out.println(&quot;sb1.length():&quot; + sb1.length());    // 反转字符串    sb1.reverse();    System.out.println(&quot;sb1:&quot; + sb1);    System.out.println(&quot;sb1.length():&quot; + sb1.length());    // String和StringBuilder的相互转化    // 1.StringBuilder转化为String    StringBuilder sb3 = new StringBuilder();    sb3.append(&quot;NBA champion&quot;);    String s3 = sb3.toString();    System.out.println(&quot;s3:&quot; + s3);    // 2.String转化为StringBuilder    String s4 = &quot;GSW&quot;;    StringBuilder sb4 = new StringBuilder(s4);    System.out.println(&quot;sb4:&quot; + sb4);  &#125;&#125; System_Class
package note_file.Basis.other;public class System_Class &#123;  public static void main(String[] args) &#123;    System.out.println(&quot;begin&quot;);    System.out.println(System.currentTimeMillis());    // 返回1970年到现在的时间差，毫秒为单位    System.out.println(System.currentTimeMillis() * 1.0 / 1000 / 60 / 60 / 24 / 365 + &quot;年&quot;);    // 转化为年    // 记录代码运行时间：    long start = System.currentTimeMillis();    for (int i = 0; i &lt; 10000; i++) &#123;      System.out.println(i);    &#125;    long end = System.currentTimeMillis();    System.out.println(end - start + &quot;毫秒&quot;);    System.exit(0);    System.out.println(&quot;end&quot;);  &#125;&#125;

