package note_file.other.Generic;import java.util.ArrayList;import java.util.Collection;import java.util.Iterator;import java.util.List;public class Generic_demo &#123;  // 泛型  public static void main(String[] args) &#123;    Collection&lt;String&gt; c = new ArrayList&lt;&gt;();    c.add(&quot;hello&quot;);    c.add(&quot;world&quot;);    // c.add(100);因为利用了泛型(即&lt;&gt;中的内容以限制变量类型)，所以这里会报错,若不用&lt;&gt;则会正常输出，但会有警告    Iterator&lt;String&gt; it = c.iterator();    while (it.hasNext()) &#123;      Object obj = it.next();      System.out.println(obj);    &#125;    // 泛型类    Generic_Class&lt;String&gt; g1 = new Generic_Class&lt;&gt;();    g1.setT(&quot;杜金阳&quot;);    System.out.println(g1.getT());    Generic_Class&lt;Integer&gt; g2 = new Generic_Class&lt;&gt;();    g2.setT(100);    System.out.println(g2.getT());    // 泛型方法    Generic_method g = new Generic_method();    g.show(&quot;杜金阳&quot;);    g.show(100);    // 泛型接口    Generic_interface&lt;String&gt; g3 = new Generic_Impl&lt;&gt;();    g3.show(&quot;Lily&quot;);    Generic_interface&lt;Integer&gt; g4 = new Generic_Impl&lt;&gt;();    g4.show(19);    // 类型通配符    // 注：在以下demo中Integer父类是Number，Number父类为Object    List&lt;?&gt; list1 = new ArrayList&lt;Object&gt;();    List&lt;?&gt; list2 = new ArrayList&lt;Number&gt;();    List&lt;?&gt; list3 = new ArrayList&lt;Integer&gt;();    // List&lt;? extends Number&gt; list4 = new ArrayList&lt;Object&gt;();[报错]    // extends表示该类型及子类型[类型通配符上限]    List&lt;? extends Number&gt; list5 = new ArrayList&lt;Number&gt;();    List&lt;? extends Number&gt; list6 = new ArrayList&lt;Integer&gt;();    List&lt;? super Number&gt; list7 = new ArrayList&lt;Object&gt;();    List&lt;? super Number&gt; list8 = new ArrayList&lt;Number&gt;();    // List&lt;? super Number&gt; list9 = new ArrayList&lt;Integer&gt;();[报错]    // super表示该类型及父类型[类型通配符下限]  &#125;&#125;
