package note_file.other.Interface_demo.Function_Interface;import java.util.function.Predicate;public class Predicate_demo &#123;  public static void main(String[] args) &#123;    boolean b1 = checkString1(&quot;hello&quot;, s -&gt; s.length() &gt; 8);    System.out.println(b1);    boolean b2 = checkString2(&quot;hello world&quot;, s -&gt; s.length() &gt; 8);    System.out.println(b2);    boolean b3 = checkString3(&quot;hello world&quot;, s -&gt; s.length() &gt; 8, s -&gt; s.length() &lt; 15);    System.out.println(b3);    boolean b4 = checkString4(&quot;hello world&quot;, s -&gt; s.length() &gt; 8, s -&gt; s.length() &lt; 15);    System.out.println(b4);  &#125;  public static boolean checkString1(String s, Predicate&lt;String&gt; pre) &#123;    // Predicate接口通常用于参数是否满足指定的条件    return pre.test(s);  &#125;  public static boolean checkString2(String s, Predicate&lt;String&gt; pre) &#123;    return pre.negate().test(s);    /*     * 相当于return !pre.test(s);     */  &#125;  public static boolean checkString3(String s, Predicate&lt;String&gt; pre1, Predicate&lt;String&gt; pre2) &#123;    return pre1.and(pre2).test(s);// 逻辑和操作  &#125;  public static boolean checkString4(String s, Predicate&lt;String&gt; pre1, Predicate&lt;String&gt; pre2) &#123;    return pre1.or(pre2).test(s);// 逻辑或操作  &#125;&#125;
