package note_file.other.IO.IOStream_Class;//字符流import java.io.BufferedReader;import java.io.BufferedWriter;import java.io.FileInputStream;import java.io.FileOutputStream;import java.io.FileReader;import java.io.FileWriter;import java.io.IOException;import java.io.InputStream;import java.io.InputStreamReader;import java.io.OutputStream;import java.io.OutputStreamWriter;public class ConversionStream_demo &#123;  public static void main(String[] args) throws IOException &#123;    OutputStream fos = new FileOutputStream(        &quot;D:\\coding_file\\study\\JAVA_file\\file_for_VScode\\note_file\\other\\IO\\IOStream_Class\\fos.txt&quot;);    OutputStreamWriter osw = new OutputStreamWriter(fos, &quot;UTF-8&quot;);    osw.write(&quot;中国&quot;);    osw.flush();// 记得写完要刷新    InputStream fis = new FileInputStream(        &quot;D:\\coding_file\\study\\JAVA_file\\file_for_VScode\\note_file\\other\\IO\\IOStream_Class\\fos.txt&quot;);    InputStreamReader isr = new InputStreamReader(fis, &quot;UTF-8&quot;);    int ch;    while ((ch = isr.read()) != -1) &#123;      System.out.print((char) ch);    &#125;    // 字符流写数据的五种方法    osw.write(97);// 此时字符流位于缓冲区，未写入文件，需要之后flush刷新流才能写入文件    osw.flush();    char[] chs = &#123; &#x27;a&#x27;, &#x27;b&#x27;, &#x27;c&#x27;, &#x27;d&#x27;, &#x27;e&#x27;, &#x27;\r&#x27;, &#x27;\n&#x27; &#125;;    osw.write(chs);    osw.write(chs, 0, 2);    osw.write(&quot;abcde\r\n&quot;);    osw.write(&quot;abcde\r\n&quot;, 0, &quot;abcd&quot;.length());    // 字符流读入数据的两种方式    isr.read();    isr.read(chs);    // 字符缓冲流    FileWriter fw = new FileWriter(        &quot;D:\\coding_file\\study\\JAVA_file\\file_for_VScode\\note_file\\other\\IO\\IOStream_Class\\fos.txt&quot;);    BufferedWriter bw = new BufferedWriter(fw);    bw.write(&quot;hello\r\n&quot;);    bw.write(&quot;world\r\n&quot;);    bw.flush();    FileReader fr = new FileReader(        &quot;D:\\coding_file\\study\\JAVA_file\\file_for_VScode\\note_file\\other\\IO\\IOStream_Class\\fos.txt&quot;);    BufferedReader br = new BufferedReader(fr);    System.out.println(br.readLine());// 读一行数据    int chr;    while ((chr = br.read()) != -1) &#123;      System.out.print((char) chr);    &#125;    bw.newLine();// 写一行分隔符，适应不同系统自动设置    char[] chrs = new char[1024];    int len;    while ((len = br.read(chrs)) != -1) &#123;      System.out.println(new String(chrs, 0, len));    &#125;    osw.close();// 关闭流之前会先flush一次    isr.close();    fos.close();    bw.close();    br.close();    fw.close();    fr.close();  &#125;&#125;
