package note_file.other.IO.IOStream_Class;import java.io.FileOutputStream;import java.io.IOException;//如果用记事本打开可以看懂则为字符流，否则则为字节流public class FileOutputStream_Class &#123;  public static void main(String[] args) throws IOException &#123;    FileOutputStream fos = new FileOutputStream(        &quot;D:\\coding_file\\study\\JAVA_file\\file_for_VScode\\note_file\\other\\IO\\IOStream_Class\\fos.txt&quot;);    fos.write(97);// ASCII码    fos.write(&quot;\n&quot;.getBytes());    // File file = new File(    // &quot;D:\\coding_file\\study\\JAVA_file\\file_for_VScode\\note_file\\other\\IO\\IOStream_Class\\fos.txt&quot;);    // FileOutputStream fos2 = new FileOutputStream(file);    // 这种写法和上面的一样    // 写数据的三种方式    // 方式1:    fos.write(97);    fos.write(98);    fos.write(99);    fos.write(100);    fos.write(101);    fos.write(&quot;\n&quot;.getBytes());    // 方式2:    byte[] bys1 = &#123; 97, 98, 99, 100, 101 &#125;;    fos.write(bys1);    fos.write(&quot;\n&quot;.getBytes());    /*     * 字节流换行细节:     * 1.Windows:\r\n     * 2.linus:\n     * 3.mac:\r     */    byte[] bys2 = &quot;abcde&quot;.getBytes();    fos.write(bys2);    fos.write(&quot;\n&quot;.getBytes());    // 方式3：    fos.write(bys2, 1, bys2.length - 1);// bys2的off位置写len的长度    fos.write(&quot;\n&quot;.getBytes());    // 文件追加写入    FileOutputStream fos2 = new FileOutputStream(        &quot;D:\\coding_file\\study\\JAVA_file\\file_for_VScode\\note_file\\other\\IO\\IOStream_Class\\fos.txt&quot;, true);// append为true代表可以追加写入    try &#123;      fos2.write(&quot;djy gets 100 point\n&quot;.getBytes(&quot;UTF-8&quot;));// 这里面可以编写编码方式，不写也可以    &#125; catch (IOException e) &#123;      e.printStackTrace();    &#125; finally &#123;// finally语句除非JVM强制退出，否则一定会执行      fos2.close();    &#125;    fos.close();    fos2.close();  &#125;&#125;
