package note_file.other.IO.IOStream_Class;import java.io.FileReader;import java.io.FileWriter;import java.io.IOException;import java.util.Properties;import java.util.Set;// Properties作为Map集合使用,底层为Hashtable方法public class Properties_demo &#123;  public static void main(String[] args) throws IOException &#123;    // Properties&lt;String,String&gt; prop=new Properties&lt;&gt;();//错误写法    Properties prop = new Properties();    prop.put(&quot;21373191&quot;, &quot;charles&quot;);    prop.put(&quot;21373119&quot;, &quot;mumu&quot;);    // Properties特有方法    prop.setProperty(&quot;21373188&quot;, &quot;tom&quot;);    System.out.println(prop.getProperty(&quot;21373191&quot;));    Set&lt;String&gt; names = prop.stringPropertyNames();    for (String key : names) &#123;      System.out.println(key);    &#125; // 输出键的集合      // 遍历      // 方式1    Set&lt;Object&gt; keySet = prop.keySet();    for (Object key : keySet) &#123;      Object value = prop.get(key);      System.out.println(key + &quot;,&quot; + value);    &#125;    // 方式2    for (String key : names) &#123;      String value = prop.getProperty(key);      System.out.println(key + &quot;,&quot; + value);    &#125;    // Properties和IO流结合    FileWriter fw = new FileWriter(        &quot;D:\\coding_file\\study\\JAVA_file\\file_for_VScode\\note_file\\other\\IO\\IOStream_Class\\fos.txt&quot;);    prop.store(fw, null);// 第二个参数为描述信息，没有就写null    fw.close();    FileReader fr = new FileReader(        &quot;D:\\coding_file\\study\\JAVA_file\\file_for_VScode\\note_file\\other\\IO\\IOStream_Class\\fos.txt&quot;);    prop.load(fr);    fr.close();    System.out.println(prop);  &#125;&#125;
