package note_file.other.IO.IOStream_Class;import java.io.BufferedReader;import java.io.BufferedWriter;import java.io.FileWriter;import java.io.IOException;import java.io.InputStream;import java.io.InputStreamReader;import java.io.OutputStreamWriter;import java.io.PrintStream;import java.io.PrintWriter;public class System_in_demo &#123;  public static void main(String[] args) throws IOException &#123;    InputStream is = System.in;// 从键盘读入数据    int by;    while ((by = is.read()) != -1) &#123;      System.out.print((char) by);    &#125;    // 通过转换流将字节流转换为字符流[这种方式可以实现读汉字]    InputStreamReader isr = new InputStreamReader(is);    // 使用字符流读一行    BufferedReader br = new BufferedReader(isr);    String s = br.readLine();// 读入字符串    System.out.println(s);    int i = Integer.parseInt(br.readLine());// 读入整数    System.out.println(i);    // 以上代码可以直接用Scanner类进行简化    PrintStream ps = System.out;    // System.out的本质是一个字节输出流    ps.println(&quot;hello&quot;);    ps.print(100);    // 打印流    PrintStream ps2 = new PrintStream(        &quot;D:\\coding_file\\study\\JAVA_file\\file_for_VScode\\note_file\\other\\IO\\IOStream_Class\\fos.txt&quot;);    ps2.write(97);    ps2.flush();    ps2.print(97);// 这行与上面两行作用相同    // 注：使用继承父类的方法写数据，查看时会转码，使用自己的特有方法（如print）时，查看数据原样输出    ps2.println();// 换行    ps2.close();    // 字符打印流    PrintWriter pw = new PrintWriter(new FileWriter(        &quot;D:\\coding_file\\study\\JAVA_file\\file_for_VScode\\note_file\\other\\IO\\IOStream_Class\\fos.txt&quot;), true);// 第二个参数设为true可以实现自动刷新    pw.write(&quot;hello&quot;);    pw.flush();    pw.println(&quot; hello&quot;);    OutputStreamWriter osw = new OutputStreamWriter(ps);    BufferedWriter bw = new BufferedWriter(osw);    bw.newLine();    bw.close();    ps.close();    pw.close();  &#125;&#125;

