package note_file.other.Modifier.Static_demo;public class Student &#123;  public String name;  public int age;  public static String university;  public Student(String name, int age) &#123;    this.name = name;    this.age = age;  &#125;  public void show() &#123;    System.out.println(name + &quot; ,&quot; + age + &quot; ,&quot; + university);  &#125;  public void show1() &#123;    /*     * 非静态的成员方法:     * 1.能访问非静态的成员变量     * 2.能访问静态的成员变量     * 3.能访问非静态的成员方法     * 4.能访问静态的成员方法     */  &#125;  public void show2() &#123;    System.out.println(name);    System.out.println(university);    show1();    show3();  &#125;  public static void show3() &#123;    /*     * 静态的成员变量:     * 1.能访问静态的成员变量     * 2.能访问静态的成员方法     */  &#125;  public static void show4() &#123;    // System.out.println(name);[报错]    System.out.println(university);    // show1();[报错]    show3();  &#125;&#125;


 Modifier.java
package note_file.other.Modifier;public class Modifier &#123;  public void my_Package() &#123;    // 格式:package 包名；(多级包用点分开)    // 自动建包 javac -d ***.java    // 通过import进行导包    // 格式:import 包名；  &#125;  public void my_Modifier() &#123;    /*     * 权限修饰符:     * 1.private :只能在本类内被访问     * 2.默认 :只能在同一个包内被访问     * 3.protected :可以在不同的包的子类里访问     * 4.public:在不同的包的无关类里也可以访问     */    /*     * final:     * 1.被final修饰的方法不可被重写(eg. public final void method();)[最终方法]     * 2.被final修饰的基本类型变量不可被重新赋值，所指地址可以改变(eg. public final int age = 20;)[常量]     * 3.被final修饰的引用类型变量所指的地址不可以被改变，内容可以重新赋值(eg. final Student s=new     * Student();)[常指针]     * 4.被final修饰的类不可被子类继承(eg. public final class Fu();)[最终类]     */    /*     * static:     * 1.被类的所有对象共享     * 2.可以通过类和对象两种方式访问(建议使用类来访问)     * 3.访问特点:     * * 非静态的成员方法:     * (1).能访问非静态的成员变量     * (2).能访问静态的成员变量     * (3).能访问非静态的成员方法     * (4).能访问静态的成员方法     * * 静态的成员变量:     * (1).能访问静态的成员变量     * (2).能访问静态的成员方法     */  &#125;&#125;

