package note_file.other.Net;import java.io.IOException;import java.io.InputStream;import java.net.ServerSocket;import java.net.Socket;public class Server &#123;  public static void main(String[] args) throws IOException &#123;    // 创建绑定到指定端口的服务器套接字    ServerSocket ss = new ServerSocket(10086);    // 侦听要接受此套接字并接受它    Socket s = ss.accept();    // 获取输入流，读数据    InputStream is = s.getInputStream();    byte[] bys = new byte[1024];    int len = is.read(bys);    String data = new String(bys, 0, len);    System.out.println(&quot;数据是:&quot; + data);    s.close();    ss.close();  &#125;&#125;
