package note_file.other.Net;import java.io.IOException;import java.net.DatagramPacket;import java.net.DatagramSocket;public class UCP_Receive_demo &#123;  public static void main(String[] args) throws IOException &#123;    // 创建接收端的Socket对象    DatagramSocket ds = new DatagramSocket(10086);    // 创建一个数据包，用于接受数据    byte[] bys = new byte[1024];    DatagramPacket dp = new DatagramPacket(bys, bys.length);    ds.receive(dp);    // 解析数据包    byte[] data_s = dp.getData();    int len = dp.getLength();    String data = new String(data_s, 0, len);    System.out.println(data);    ds.close();  &#125;&#125;
