package note_file.other.Net;import java.io.IOException;import java.net.DatagramPacket;import java.net.DatagramSocket;import java.net.InetAddress;public class UCP_Send_demo &#123;  public static void main(String[] args) throws IOException &#123;    // 创建发送端的Socket对象    DatagramSocket ds = new DatagramSocket();    // 创建数据，并将数据打包    byte[] bys = &quot;hello udp&quot;.getBytes();    int length = bys.length;    InetAddress address = InetAddress.getByName(&quot;192.168.2.106&quot;);    int port = 10086;// 端口号为[0,65536]均可，[0,1023]最好不要使用    DatagramPacket dp = new DatagramPacket(bys, length, address, port);    ds.send(dp);    ds.close();  &#125;&#125;

