package note_file.other.Reflection;import java.lang.reflect.Constructor;import java.lang.reflect.Field;import java.lang.reflect.InvocationTargetException;import java.lang.reflect.Method;public class Reflect_demo &#123;  public static void main(String[] args) throws ClassNotFoundException, NoSuchMethodException, SecurityException,      InstantiationException, IllegalAccessException, IllegalArgumentException, InvocationTargetException,      NoSuchFieldException &#123;    // 三种方式获得Class对象:    // 1.使用类的class属性来获取该类对应的Class对象    Class&lt;Student&gt; c1 = Student.class;    Class&lt;Student&gt; c2 = Student.class;    System.out.println(c2);    System.out.println(c1 == c2);    System.out.println(&quot;&quot;);    // 2.调用对象getClass()方法    Student s = new Student();    Class&lt;? extends Student&gt; c3 = s.getClass();    System.out.println(c3);    System.out.println(c1 == c3);    System.out.println(&quot;&quot;);    // 3.调用Class类中静态方法forName()    Class&lt;?&gt; c4 = Class.forName(&quot;note_file.other.Reflection.Student&quot;);    System.out.println(c4);    System.out.println(c1 == c4);    System.out.println(&quot;&quot;);    // 反射获取构造方法并使用    Class&lt;?&gt; c = Class.forName(&quot;note_file.other.Reflection.Student&quot;);    Constructor&lt;?&gt;[] cons = c.getConstructors();// 获得公共的构造方法    for (Constructor&lt;?&gt; con : cons) &#123;      System.out.println(con);    &#125;    System.out.println(&quot;&quot;);    Constructor&lt;?&gt;[] d_cons = c.getDeclaredConstructors();// 获得所有构造方法    for (Constructor&lt;?&gt; con : d_cons) &#123;      System.out.println(con);    &#125;    System.out.println(&quot;&quot;);    Constructor&lt;?&gt; con = c.getConstructor();// 获得单个公共构造方法对象    Object obj = con.newInstance();    System.out.println(obj);    System.out.println(&quot;&quot;);    Constructor&lt;?&gt; d_con = c.getDeclaredConstructor();// 获得单个构造方法对象    Object d_obj = d_con.newInstance();    System.out.println(d_obj);    System.out.println(&quot;&quot;);    // 反射获取成员变量并使用    Field[] fields = c.getFields();// 获得公共的成员变量    for (Field field : fields) &#123;      System.out.println(field);    &#125;    System.out.println(&quot;&quot;);    Field[] d_fields = c.getDeclaredFields();// 获得所有的成员变量    for (Field d_field : d_fields) &#123;      System.out.println(d_field);    &#125;    System.out.println(&quot;&quot;);    Field field = c.getField(&quot;address&quot;);// 获得单个的公共成员变量    System.out.println(field);    Constructor&lt;?&gt; con_f = c.getConstructor();    Object obj_f = con_f.newInstance();    field.set(obj_f, &quot;合肥&quot;);// 给obj_f的成员变量field赋值为合肥    System.out.println(obj_f);    System.out.println(&quot;&quot;);    Field d_field = c.getDeclaredField(&quot;age&quot;);// 获得单个的成员变量    System.out.println(d_field);    System.out.println(&quot;&quot;);    // 反射获取成员方法并使用    Method[] methods = c.getMethods();// 获得所有公共方法    // 方法对象反映由该Class对象表示的类或接口的所有公共方法，包括由类或接口声明的对象及超类和超级接口继承的类    for (Method method : methods) &#123;      System.out.println(method);    &#125;    System.out.println(&quot;&quot;);    Method[] d_methods = c.getDeclaredMethods();// 获得所有方法    // 该方法获取的成员方法不包括继承的方法    for (Method d_method : d_methods) &#123;      System.out.println(d_method);    &#125;    Method method = c.getMethod(&quot;method1&quot;);// 获得单个公共方法    Object obj_m = c.getConstructor().newInstance();    method.invoke(obj_m);    Method d_method = c.getDeclaredMethod(&quot;method1&quot;);// 获得单个方法    Object d_obj_m = c.getConstructor().newInstance();    d_method.invoke(d_obj_m);  &#125;&#125;
