package note_file.other.Reflection;public class Student &#123;  // 成员变量：一个私有，一个默认，一个公共  private String name;  int age;  public String address;  // 构造方法：一个私有，一个默认，两个公共  public Student() &#123;  &#125;  private Student(String name) &#123;    this.name = name;  &#125;  Student(String name, int age) &#123;    this.name = name;    this.age = age;  &#125;  public Student(String name, int age, String address) &#123;    this.name = name;    this.age = age;    this.address = address;  &#125;  // 成员方法：一个私有，四个公共  private void function() &#123;    System.out.println(&quot;function&quot;);  &#125;  public void method1() &#123;    System.out.println(&quot;method&quot;);  &#125;  public void method2(String s) &#123;    System.out.println(&quot;method&quot; + s);  &#125;  public String method3(String s, int i) &#123;    return s + &quot;,&quot; + i;  &#125;  @Override  public String toString() &#123;    return &quot;Student&#123;&quot; + &quot;name=&#x27;&quot; + name + &#x27;\&#x27;&#x27; + &quot;,age=&quot; + age + &quot;,address=&quot; + address + &#x27;\&#x27;&#x27; + &#x27;&#125;&#x27;;  &#125;&#125;

