package note_file.other.other;import java.util.Arrays;import java.util.List;import java.util.Set;//可变参数[本质是传入变量形成的数组]public class Args_demo &#123;  public static void main(String[] args) &#123;    System.out.println(sum(10, 120, 30));    System.out.println(sum(1, 2, 3, 4, 5, 6, 7));    // 可变参数的使用    List&lt;String&gt; list = Arrays.asList(&quot;hello&quot;, &quot;world&quot;, &quot;java&quot;);// asList是一个可变参数    // list.add(&quot;NBA&quot;);[报错]    // list.remove(&quot;NBA&quot;);[报错]    list.set(0, &quot;NBA&quot;);    System.out.println(list);    // 只可以进行修改，不能添加或删除    List&lt;String&gt; list_of = List.of(&quot;hello&quot;, &quot;world&quot;, &quot;java&quot;, &quot;world&quot;);    // list_of.add(&quot;NBA&quot;);[报错]    // list_of.remove(&quot;NBA&quot;);[报错]    // list_of.set(0, &quot;NBA&quot;);[报错]    System.out.println(list_of);    // 增删改均不可以    Set&lt;String&gt; set = Set.of(&quot;hello&quot;, &quot;world&quot;, &quot;java&quot;, &quot;world&quot;);    // set.add(&quot;NBA&quot;);[报错]    // set.remove(&quot;NBA&quot;);[报错]    System.out.println(set);    // 增删均不可，Set没有改方法  &#125;  public static int sum(int b, int... a) &#123;// 如果有多个参数，需要将可变参数放在方法体的后面    int sum = 0;    for (int i = 0; i &lt; a.length; i++) &#123;      sum += a[i];    &#125;    return sum * b;  &#125;&#125;
 Stream_demo.java
package note_file.other.other;import java.util.ArrayList;import java.util.HashMap;import java.util.HashSet;import java.util.List;import java.util.Map;import java.util.Set;import java.util.Map.Entry;import java.util.stream.Collectors;import java.util.stream.Stream;public class Stream_demo &#123;  public static void main(String[] args) &#123;    ArrayList&lt;String&gt; array = new ArrayList&lt;&gt;();    array.add(&quot;charles&quot;);    array.add(&quot;张三丰&quot;);    array.add(&quot;张飞&quot;);    array.add(&quot;张无忌&quot;);    // 利用Stream流输出姓张且名字长度为3的集合元素    array.stream().filter(s -&gt; s.startsWith(&quot;张&quot;)).filter(s -&gt; s.length() == 3).forEach(System.out::println);    // Stream流的常见生成方式    // 1.Collection体系的集合可以使用默认方法生成stream()生成流    List&lt;String&gt; list = new ArrayList&lt;&gt;();    list.add(&quot;50&quot;);    list.add(&quot;10&quot;);    list.add(&quot;30&quot;);    list.add(&quot;40&quot;);    list.add(&quot;20&quot;);    Stream&lt;String&gt; list_stream = list.stream();    Set&lt;Integer&gt; set = new HashSet&lt;&gt;();    set.add(10);    set.add(50);    set.add(20);    set.add(30);    set.add(40);    Stream&lt;Integer&gt; set_stream = set.stream();    // 2.Map体系的;    // 2.Map体系的;集合间接生成流    // 2.Map体系的;集合间接生成流    // 2.Map体系的;集合间接生成流    // 2.Map体系的;集合间接生成流集合间接生成流    Map&lt;String, Integer&gt; map = new HashMap&lt;&gt;();    map.put(&quot;charles&quot;, 21373191);    map.put(&quot;Tom&quot;, 21373188);    map.put(&quot;Jerry&quot;, 21373181);    Stream&lt;String&gt; key_stream = map.keySet().stream();    Stream&lt;Integer&gt; value_stream = map.values().stream();    Stream&lt;Entry&lt;String, Integer&gt;&gt; entryset_stream = map.entrySet().stream();    // 3.数组可以通过Stream接口的静态方法of(T...values)生成流    String[] strArray = &#123; &quot;hello&quot;, &quot;world&quot;, &quot;NBA&quot; &#125;;    Stream&lt;String&gt; strArray_stream = Stream.of(strArray);    // Stream流的常见中间操作方法    // 1.利用filter过滤    array.stream().filter(s -&gt; s.startsWith(&quot;张&quot;)).filter(s -&gt; s.length() == 3).forEach(System.out::println);    // 2.利用limit限制符合要求元素的数目    array.stream().limit(3).forEach(System.out::println);    // 3.利用skip跳过一定数量符合要求的元素    array.stream().skip(2).limit(2).forEach(System.out::println);    Stream&lt;String&gt; s1 = array.stream().limit(2);    Stream&lt;String&gt; s2 = array.stream().skip(1);    // 4.concat方法用于合并两个流， distinct()用于输出不重复的元素    Stream.concat(s1, s2).distinct().forEach(System.out::println);    // 5.sorted()默认是按照字母顺序输出    strArray_stream.sorted().forEach(System.out::println);    // 按照字符串长度输出    Stream.of(strArray).sorted((m1, m2) -&gt; m1.length() - m2.length()).forEach(System.out::println);    // 6.字符串转化为int输出[可以使用mapToInt()，使用该方法返回值为IntStream，有许多好用的方法]    list.stream().map(Integer::parseInt).forEach(System.out::println);    int result = list.stream().mapToInt(Integer::parseInt).sum();// 调用IntStream中的sum方法    System.out.println(result);    // 注：以上几种操作可以混合使用    // Stream常见终结操作方法    // 1.forEach()对满足条件元素单独操作    array.stream().forEach(System.out::println);    // 2. count()返回满足条件元素的个数    long count = array.stream().filter(s -&gt; s.startsWith(&quot;张&quot;)).count();    System.out.println(count);    // Stream流的收集操作    Stream&lt;String&gt; filter = list.stream().filter(s -&gt; s.length() == 3);    List&lt;String&gt; names = filter.collect(Collectors.toList());    for (String name : names) &#123;      System.out.println(name);    &#125;    Stream&lt;Integer&gt; filter2 = set.stream().filter(age -&gt; age &gt; 25);    Set&lt;Integer&gt; ages = filter2.collect(Collectors.toSet());    for (int i : ages) &#123;      System.out.println(i);    &#125;    String[] nameArray = &#123; &quot;charles,19&quot;, &quot;Lily,43&quot;, &quot;long,50&quot; &#125;;    Stream&lt;String&gt; filter3 = Stream.of(nameArray).filter(s -&gt; Integer.parseInt(s.split(&quot;,&quot;)[1]) &gt; 25);    Map&lt;String, Integer&gt; map2 = filter3        .collect(Collectors.toMap((s -&gt; s.split(&quot;,&quot;)[0]), s -&gt; Integer.parseInt(s.split(&quot;,&quot;)[1])));    Set&lt;Entry&lt;String, Integer&gt;&gt; entrySet = map2.entrySet();    for (Entry&lt;String, Integer&gt; me : entrySet) &#123;      System.out.println(me.getKey() + &quot;,&quot; + me.getValue());    &#125;  &#125;&#125;

搭建项目参考过程 1. 初始化 1.1 创建项目
新建 api_server 文件夹作为项目根目录，并在项目根目录中运行如下的命令，初始化包管理配置文件：
npm init -y
运行如下的命令，安装特定版本的 express：
npm i express@4.17.1
在项目根目录中新建 app.js 作为整个项目的入口文件，并初始化如下的代码：
// 导入 express 模块const express = require(&#x27;express&#x27;)// 创建 express 的服务器实例const app = express()// write your code here...// 调用 app.listen 方法，指定端口号并启动web服务器app.listen(3007, function () &#123; console.log(&#x27;api server running at http://127.0.0.1:3007&#x27;)&#125;) 1.2 配置 cors 跨域
运行如下的命令，安装 cors 中间件：
npm i cors@2.8.5
在 app.js 中导入并配置 cors 中间件：
// 导入 cors 中间件const cors = require(&#x27;cors&#x27;)// 将 cors 注册为全局中间件app.use(cors()) 1.3 配置解析表单数据的中间件
通过如下的代码，配置解析 application/x-www-form-urlencoded 格式的表单数据的中间件：
app.use(express.urlencoded(&#123; extended: false &#125;)) 1.4 初始化路由相关的文件夹
在项目根目录中，新建 router 文件夹，用来存放所有的路由模块
路由模块中，只存放客户端的请求与处理函数之间的映射关系
在项目根目录中，新建 router_handler 文件夹，用来存放所有的 路由处理函数模块
路由处理函数模块中，专门负责存放每个路由对应的处理函数
1.5 初始化用户路由模块
在 router 文件夹中，新建 user.js 文件，作为用户的路由模块，并初始化代码如下：
const express = require(&#x27;express&#x27;)// 创建路由对象const router = express.Router()// 注册新用户router.post(&#x27;/reguser&#x27;, (req, res) =&gt; &#123; res.send(&#x27;reguser OK&#x27;)&#125;)// 登录router.post(&#x27;/login&#x27;, (req, res) =&gt; &#123; res.send(&#x27;login OK&#x27;)&#125;)// 将路由对象共享出去module.exports = router
在 app.js 中，导入并使用 用户路由模块 ：
// 导入并注册用户路由模块const userRouter = require(&#x27;./router/user&#x27;)app.use(&#x27;/api&#x27;, userRouter) 1.6 抽离用户路由模块中的处理函数
目的：为了保证 路由模块 的纯粹性，所有的 路由处理函数，必须抽离到对应的 路由处理函数模块 中
在 /router_handler/user.js 中，使用 exports 对象，分别向外共享如下两个 路由处理函数 ：
/** * 在这里定义和用户相关的路由处理函数，供 /router/user.js 模块进行调用 */// 注册用户的处理函数exports.regUser = (req, res) =&gt; &#123; res.send(&#x27;reguser OK&#x27;)&#125;// 登录的处理函数exports.login = (req, res) =&gt; &#123; res.send(&#x27;login OK&#x27;)&#125;
将 /router/user.js 中的代码修改为如下结构：
const express = require(&#x27;express&#x27;)const router = express.Router()// 导入用户路由处理函数模块const userHandler = require(&#x27;../router_handler/user&#x27;)// 注册新用户router.post(&#x27;/reguser&#x27;, userHandler.regUser)// 登录router.post(&#x27;/login&#x27;, userHandler.login)module.exports = router 2. 登录注册 2.1 新建 ev_users 表
在 my_db_01 数据库中，新建 ev_users 表如下：
2.2 安装并配置 mysql 模块
在 API 接口项目中，需要安装并配置 mysql 这个第三方模块，来连接和操作 MySQL 数据库
运行如下命令，安装 mysql 模块：
npm i mysql@2.18.1
在项目根目录中新建 /db/index.js 文件，在此自定义模块中创建数据库的连接对象：
// 导入 mysql 模块const mysql = require(&#x27;mysql&#x27;)// 创建数据库连接对象const db = mysql.createPool(&#123; host: &#x27;127.0.0.1&#x27;, user: &#x27;root&#x27;, password: &#x27;admin123&#x27;, database: &#x27;my_db_01&#x27;,&#125;)// 向外共享 db 数据库连接对象module.exports = db 2.3 注册 2.3.0 实现步骤
检测表单数据是否合法 检测用户名是否被占用 对密码进行加密处理 插入新用户
2.3.1 检测表单数据是否合法
判断用户名和密码是否为空
// 接收表单数据const userinfo = req.body// 判断数据是否合法if (!userinfo.username || !userinfo.password) &#123; return res.send(&#123; status: 1, message: &#x27;用户名或密码不能为空！&#x27; &#125;)&#125; 2.3.2 检测用户名是否被占用
导入数据库操作模块：
const db = require(&#x27;../db/index&#x27;)
定义 SQL 语句：
const sql = `select * from ev_users where username=?`
执行 SQL 语句并根据结果判断用户名是否被占用：
db.query(sql, [userinfo.username], function (err, results) &#123; // 执行 SQL 语句失败 if (err) &#123; return res.send(&#123; status: 1, message: err.message &#125;) &#125; // 用户名被占用 if (results.length &gt; 0) &#123; return res.send(&#123; status: 1, message: &#x27;用户名被占用，请更换其他用户名！&#x27; &#125;) &#125; // TODO: 用户名可用，继续后续流程...&#125;) 2.3.3 对密码进行加密处理
为了保证密码的安全性，不建议在数据库以 明文 的形式保存用户密码，推荐对密码进行 加密存储
在当前项目中，使用 bcryptjs 对用户密码进行加密，优点：
加密之后的密码，无法被逆向破解 同一明文密码多次加密，得到的加密结果各不相同，保证了安全性
运行如下命令，安装指定版本的 bcryptjs ：
npm i bcryptjs@2.4.3
在 /router_handler/user.js 中，导入 bcryptjs ：
const bcrypt = require(&#x27;bcryptjs&#x27;)
在注册用户的处理函数中，确认用户名可用之后，调用 bcrypt.hashSync(明文密码, 随机盐的长度) 方法，对用户的密码进行加密处理：
// 对用户的密码,进行 bcrype 加密，返回值是加密之后的密码字符串userinfo.password = bcrypt.hashSync(userinfo.password, 10) 2.3.4 插入新用户
定义插入用户的 SQL 语句：
const sql = &#x27;insert into ev_users set ?&#x27;
调用 db.query() 执行 SQL 语句，插入新用户：
db.query(sql, &#123; username: userinfo.username, password: userinfo.password &#125;, function (err, results) &#123; // 执行 SQL 语句失败 if (err) return res.send(&#123; status: 1, message: err.message &#125;) // SQL 语句执行成功，但影响行数不为 1 if (results.affectedRows !== 1) &#123; return res.send(&#123; status: 1, message: &#x27;注册用户失败，请稍后再试！&#x27; &#125;) &#125; // 注册成功 res.send(&#123; status: 0, message: &#x27;注册成功！&#x27; &#125;)&#125;) 2.4 优化 res.send() 代码
在处理函数中，需要多次调用 res.send() 向客户端响应 处理失败 的结果，为了简化代码，可以手动封装一个 res.cc() 函数
在 app.js 中，所有路由之前，声明一个全局中间件，为 res 对象挂载一个 res.cc() 函数 ：
// 响应数据的中间件app.use(function (req, res, next) &#123; // status = 0 为成功； status = 1 为失败； 默认将 status 的值设置为 1，方便处理失败的情况 res.cc = function (err, status = 1) &#123; res.send(&#123; // 状态 status, // 状态描述，判断 err 是 错误对象 还是 字符串 message: err instanceof Error ? err.message : err, &#125;) &#125; next()&#125;) 2.5 优化表单数据验证
表单验证的原则：前端验证为辅，后端验证为主，后端永远不要相信前端提交过来的任何内容
在实际开发中，前后端都需要对表单的数据进行合法性的验证，而且，后端做为数据合法性验证的最后一个关口，在拦截非法数据方面，起到了至关重要的作用。 单纯的使用 if...else... 的形式对数据合法性进行验证，效率低下、出错率高、维护性差。因此，推荐使用第三方数据验证模块，来降低出错率、提高验证的效率与可维护性，让后端程序员把更多的精力放在核心业务逻辑的处理上。
安装 @hapi/joi 包，为表单中携带的每个数据项，定义验证规则：
npm install @hapi/joi@17.1.0
安装 @escook/express-joi 中间件，来实现自动对表单数据进行验证的功能：
npm i @escook/express-joi
新建 /schema/user.js 用户信息验证规则模块，并初始化代码如下：
const joi = require(&#x27;@hapi/joi&#x27;)/** * string() 值必须是字符串 * alphanum() 值只能是包含 a-zA-Z0-9 的字符串 * min(length) 最小长度 * max(length) 最大长度 * required() 值是必填项，不能为 undefined * pattern(正则表达式) 值必须符合正则表达式的规则 */// 用户名的验证规则const username = joi.string().alphanum().min(1).max(10).required()// 密码的验证规则const password = joi .string() .pattern(/^[\S]&#123;6,12&#125;$/) .required()// 注册和登录表单的验证规则对象exports.reg_login_schema = &#123; // 表示需要对 req.body 中的数据进行验证 body: &#123; username, password, &#125;,&#125;
修改 /router/user.js 中的代码如下：
const express = require(&#x27;express&#x27;)const router = express.Router()// 导入用户路由处理函数模块const userHandler = require(&#x27;../router_handler/user&#x27;)// 1. 导入验证表单数据的中间件const expressJoi = require(&#x27;@escook/express-joi&#x27;)// 2. 导入需要的验证规则对象const &#123; reg_login_schema &#125; = require(&#x27;../schema/user&#x27;)// 注册新用户// 3. 在注册新用户的路由中，声明局部中间件，对当前请求中携带的数据进行验证// 3.1 数据验证通过后，会把这次请求流转给后面的路由处理函数// 3.2 数据验证失败后，终止后续代码的执行，并抛出一个全局的 Error 错误，进入全局错误级别中间件中进行处理router.post(&#x27;/reguser&#x27;, expressJoi(reg_login_schema), userHandler.regUser)// 登录router.post(&#x27;/login&#x27;, userHandler.login)module.exports = router
在 app.js 的全局错误级别中间件中，捕获验证失败的错误，并把验证失败的结果响应给客户端：
const joi = require(&#x27;@hapi/joi&#x27;)// 错误中间件app.use(function (err, req, res, next) &#123; // 数据验证失败 if (err instanceof joi.ValidationError) return res.cc(err) // 未知错误 res.cc(err)&#125;) 2.6 登录 2.6.0 实现步骤
检测表单数据是否合法 根据用户名查询用户的数据 判断用户输入的密码是否正确 生成 JWT 的 Token 字符串
2.6.1 检测登录表单的数据是否合法
将 /router/user.js 中 登录 的路由代码修改如下：
// 登录的路由router.post(&#x27;/login&#x27;, expressJoi(reg_login_schema), userHandler.login) 2.6.2 根据用户名查询用户的数据
接收表单数据：
const userinfo = req.body
定义 SQL 语句：
const sql = `select * from ev_users where username=?`
执行 SQL 语句，查询用户的数据：
db.query(sql, userinfo.username, function (err, results) &#123; // 执行 SQL 语句失败 if (err) return res.cc(err) // 执行 SQL 语句成功，但是查询到数据条数不等于 1 if (results.length !== 1) return res.cc(&#x27;登录失败！&#x27;) // TODO：判断用户输入的登录密码是否和数据库中的密码一致&#125;) 2.6.3 判断用户输入的密码是否正确
核心实现思路：调用 bcrypt.compareSync(用户提交的密码, 数据库中的密码) 方法比较密码是否一致
返回值是布尔值（true 一致、false 不一致）
具体的实现代码如下： // 拿着用户输入的密码,和数据库中存储的密码进行对比const compareResult = bcrypt.compareSync(userinfo.password, results[0].password)// 如果对比的结果等于 false, 则证明用户输入的密码错误if (!compareResult) &#123; return res.cc(&#x27;登录失败！&#x27;)&#125;// TODO：登录成功，生成 Token 字符串 2.6.4 生成 JWT 的 Token 字符串
核心注意点：在生成 Token 字符串的时候，一定要剔除 密码 和 头像 的值
通过 ES6 的高级语法，快速剔除 密码 和 头像 的值：
// 剔除完毕之后，user 中只保留了用户的 id, username, nickname, email 这四个属性的值const user = &#123; ...results[0], password: &#x27;&#x27;, user_pic: &#x27;&#x27; &#125;
运行如下的命令，安装生成 Token 字符串的包：
npm i jsonwebtoken@8.5.1
在 /router_handler/user.js 模块的头部区域，导入 jsonwebtoken 包：
// 用这个包来生成 Token 字符串const jwt = require(&#x27;jsonwebtoken&#x27;)
创建 config.js 文件，并向外共享 加密 和 还原 Token 的 jwtSecretKey 字符串：
module.exports = &#123; jwtSecretKey: &#x27;itheima No1. ^_^&#x27;,&#125;
将用户信息对象加密成 Token 字符串：
// 导入配置文件const config = require(&#x27;../config&#x27;)// 生成 Token 字符串const tokenStr = jwt.sign(user, config.jwtSecretKey, &#123; expiresIn: &#x27;10h&#x27;, // token 有效期为 10 个小时&#125;)
将生成的 Token 字符串响应给客户端：
res.send(&#123; status: 0, message: &#x27;登录成功！&#x27;, // 为了方便客户端使用 Token，在服务器端直接拼接上 Bearer 的前缀 token: &#x27;Bearer &#x27; + tokenStr,&#125;) 2.7 配置解析 Token 的中间件
运行如下的命令，安装解析 Token 的中间件：
npm i express-jwt@5.3.3
在 app.js 中注册路由之前，配置解析 Token 的中间件：
// 导入配置文件const config = require(&#x27;./config&#x27;)// 解析 token 的中间件const expressJWT = require(&#x27;express-jwt&#x27;)// 使用 .unless(&#123; path: [/^\/api\//] &#125;) 指定哪些接口不需要进行 Token 的身份认证app.use(expressJWT(&#123; secret: config.jwtSecretKey &#125;).unless(&#123; path: [/^\/api\//] &#125;))
在 app.js 中的 错误级别中间件 里面，捕获并处理 Token 认证失败后的错误：
// 错误中间件app.use(function (err, req, res, next) &#123; // 省略其它代码... // 捕获身份认证失败的错误 if (err.name === &#x27;UnauthorizedError&#x27;) return res.cc(&#x27;身份认证失败！&#x27;) // 未知错误...&#125;) 3. 个人中心 3.1 获取用户的基本信息 3.1.0 实现步骤
初始化 路由 模块 初始化 路由处理函数 模块 获取用户的基本信息
3.1.1 初始化路由模块
创建 /router/userinfo.js 路由模块，并初始化如下的代码结构：
// 导入 expressconst express = require(&#x27;express&#x27;)// 创建路由对象const router = express.Router()// 获取用户的基本信息router.get(&#x27;/userinfo&#x27;, (req, res) =&gt; &#123; res.send(&#x27;ok&#x27;)&#125;)// 向外共享路由对象module.exports = router
在 app.js 中导入并使用个人中心的路由模块：
// 导入并使用用户信息路由模块const userinfoRouter = require(&#x27;./router/userinfo&#x27;)// 注意：以 /my 开头的接口，都是有权限的接口，需要进行 Token 身份认证app.use(&#x27;/my&#x27;, userinfoRouter) 3.1.2 初始化路由处理函数模块
创建 /router_handler/userinfo.js 路由处理函数模块，并初始化如下的代码结构：
// 获取用户基本信息的处理函数exports.getUserInfo = (req, res) =&gt; &#123; res.send(&#x27;ok&#x27;)&#125;
修改 /router/userinfo.js 中的代码如下：
const express = require(&#x27;express&#x27;)const router = express.Router()// 导入用户信息的处理函数模块const userinfo_handler = require(&#x27;../router_handler/userinfo&#x27;)// 获取用户的基本信息router.get(&#x27;/userinfo&#x27;, userinfo_handler.getUserInfo)module.exports = router 3.1.3 获取用户的基本信息
在 /router_handler/userinfo.js 头部导入数据库操作模块：
// 导入数据库操作模块const db = require(&#x27;../db/index&#x27;)
定义 SQL 语句：
// 根据用户的 id，查询用户的基本信息// 注意：为了防止用户的密码泄露，需要排除 password 字段const sql = `select id, username, nickname, email, user_pic from ev_users where id=?`
调用 db.query() 执行 SQL 语句：
// 注意：req 对象上的 user 属性，是 Token 解析成功，express-jwt 中间件帮我们挂载上去的db.query(sql, req.user.id, (err, results) =&gt; &#123; // 1. 执行 SQL 语句失败 if (err) return res.cc(err) // 2. 执行 SQL 语句成功，但是查询到的数据条数不等于 1 if (results.length !== 1) return res.cc(&#x27;获取用户信息失败！&#x27;) // 3. 将用户信息响应给客户端 res.send(&#123; status: 0, message: &#x27;获取用户基本信息成功！&#x27;, data: results[0], &#125;)&#125;) 3.2 更新用户的基本信息 3.2.0 实现步骤
定义路由和处理函数 验证表单数据 实现更新用户基本信息的功能
3.2.1 定义路由和处理函数
在 /router/userinfo.js 模块中，新增 更新用户基本信息 的路由：
// 更新用户的基本信息router.post(&#x27;/userinfo&#x27;, userinfo_handler.updateUserInfo)
在 /router_handler/userinfo.js 模块中，定义并向外共享 更新用户基本信息 的路由处理函数：
// 更新用户基本信息的处理函数exports.updateUserInfo = (req, res) =&gt; &#123; res.send(&#x27;ok&#x27;)&#125; 3.2.2 验证表单数据
在 /schema/user.js 验证规则模块中，定义 id，nickname，email 的验证规则如下：
// 定义 id, nickname, emial 的验证规则const id = joi.number().integer().min(1).required()const nickname = joi.string().required()const email = joi.string().email().required()
并使用 exports 向外共享如下的 验证规则对象：
// 验证规则对象 - 更新用户基本信息exports.update_userinfo_schema = &#123; body: &#123; id, nickname, email, &#125;,&#125;
在 /router/userinfo.js 模块中，导入验证数据合法性的中间件：
// 导入验证数据合法性的中间件const expressJoi = require(&#x27;@escook/express-joi&#x27;)
在 /router/userinfo.js 模块中，导入需要的验证规则对象：
// 导入需要的验证规则对象const &#123; update_userinfo_schema &#125; = require(&#x27;../schema/user&#x27;)
在 /router/userinfo.js 模块中，修改 更新用户的基本信息 的路由如下：
// 更新用户的基本信息router.post(&#x27;/userinfo&#x27;, expressJoi(update_userinfo_schema), userinfo_handler.updateUserInfo) 3.2.3 实现更新用户基本信息的功能
定义待执行的 SQL 语句：
const sql = `update ev_users set ? where id=?`
调用 db.query() 执行 SQL 语句并传参：
db.query(sql, [req.body, req.body.id], (err, results) =&gt; &#123; // 执行 SQL 语句失败 if (err) return res.cc(err) // 执行 SQL 语句成功，但影响行数不为 1 if (results.affectedRows !== 1) return res.cc(&#x27;修改用户基本信息失败！&#x27;) // 修改用户信息成功 return res.cc(&#x27;修改用户基本信息成功！&#x27;, 0)&#125;) 3.3 重置密码 3.3.0 实现步骤
定义路由和处理函数 验证表单数据 实现重置密码的功能
3.3.1 定义路由和处理函数
在 /router/userinfo.js 模块中，新增 重置密码 的路由：
// 重置密码的路由router.post(&#x27;/updatepwd&#x27;, userinfo_handler.updatePassword)
在 /router_handler/userinfo.js 模块中，定义并向外共享 重置密码 的路由处理函数：
// 重置密码的处理函数exports.updatePassword = (req, res) =&gt; &#123; res.send(&#x27;ok&#x27;)&#125; 3.3.2 验证表单数据
核心验证思路：旧密码与新密码，必须符合密码的验证规则，并且新密码不能与旧密码一致！
在 /schema/user.js 模块中，使用 exports 向外共享如下的 验证规则对象：
// 验证规则对象 - 重置密码exports.update_password_schema = &#123; body: &#123; // 使用 password 这个规则，验证 req.body.oldPwd 的值 oldPwd: password, // 使用 joi.not(joi.ref(&#x27;oldPwd&#x27;)).concat(password) 规则，验证 req.body.newPwd 的值 // 解读： // 1. joi.ref(&#x27;oldPwd&#x27;) 表示 newPwd 的值必须和 oldPwd 的值保持一致 // 2. joi.not(joi.ref(&#x27;oldPwd&#x27;)) 表示 newPwd 的值不能等于 oldPwd 的值 // 3. .concat() 用于合并 joi.not(joi.ref(&#x27;oldPwd&#x27;)) 和 password 这两条验证规则 newPwd: joi.not(joi.ref(&#x27;oldPwd&#x27;)).concat(password), &#125;,&#125;
在 /router/userinfo.js 模块中，导入需要的验证规则对象：
// 导入需要的验证规则对象const &#123; update_userinfo_schema, update_password_schema &#125; = require(&#x27;../schema/user&#x27;)
并在 重置密码的路由 中，使用 update_password_schema 规则验证表单的数据，示例代码如下：
router.post(&#x27;/updatepwd&#x27;, expressJoi(update_password_schema), userinfo_handler.updatePassword) 3.3.3 实现重置密码的功能
根据 id 查询用户是否存在：
// 定义根据 id 查询用户数据的 SQL 语句const sql = `select * from ev_users where id=?`// 执行 SQL 语句查询用户是否存在db.query(sql, req.user.id, (err, results) =&gt; &#123; // 执行 SQL 语句失败 if (err) return res.cc(err) // 检查指定 id 的用户是否存在 if (results.length !== 1) return res.cc(&#x27;用户不存在！&#x27;) // TODO：判断提交的旧密码是否正确&#125;)
判断提交的 旧密码 是否正确：
// 在头部区域导入 bcryptjs 后，// 即可使用 bcrypt.compareSync(提交的密码，数据库中的密码) 方法验证密码是否正确// compareSync() 函数的返回值为布尔值，true 表示密码正确，false 表示密码错误const bcrypt = require(&#x27;bcryptjs&#x27;)// 判断提交的旧密码是否正确const compareResult = bcrypt.compareSync(req.body.oldPwd, results[0].password)if (!compareResult) return res.cc(&#x27;原密码错误！&#x27;)
对新密码进行 bcrypt 加密之后，更新到数据库中：
// 定义更新用户密码的 SQL 语句const sql = `update ev_users set password=? where id=?`// 对新密码进行 bcrypt 加密处理const newPwd = bcrypt.hashSync(req.body.newPwd, 10)// 执行 SQL 语句，根据 id 更新用户的密码db.query(sql, [newPwd, req.user.id], (err, results) =&gt; &#123; // SQL 语句执行失败 if (err) return res.cc(err) // SQL 语句执行成功，但是影响行数不等于 1 if (results.affectedRows !== 1) return res.cc(&#x27;更新密码失败！&#x27;) // 更新密码成功 res.cc(&#x27;更新密码成功！&#x27;, 0)&#125;) 3.4 更新用户头像 3.4.0 实现步骤
定义路由和处理函数 验证表单数据 实现更新用户头像的功能
3.4.1 定义路由和处理函数
在 /router/userinfo.js 模块中，新增 更新用户头像 的路由：
// 更新用户头像的路由router.post(&#x27;/update/avatar&#x27;, userinfo_handler.updateAvatar)
在 /router_handler/userinfo.js 模块中，定义并向外共享 更新用户头像 的路由处理函数：
