在 /schema/user.js 验证规则模块中，定义 avatar 的验证规则如下：
// dataUri() 指的是如下格式的字符串数据：// data:image/png;base64,VE9PTUFOWVNFQ1JFVFM=const avatar = joi.string().dataUri().required()
并使用 exports 向外共享如下的 验证规则对象：
// 验证规则对象 - 更新头像exports.update_avatar_schema = &#123; body: &#123; avatar, &#125;,&#125;
在 /router/userinfo.js 模块中，导入需要的验证规则对象：
const &#123; update_avatar_schema &#125; = require(&#x27;../schema/user&#x27;)
在 /router/userinfo.js 模块中，修改 更新用户头像 的路由如下：
router.post(&#x27;/update/avatar&#x27;, expressJoi(update_avatar_schema), userinfo_handler.updateAvatar) 3.4.3 实现更新用户头像的功能
定义更新用户头像的 SQL 语句：
const sql = &#x27;update ev_users set user_pic=? where id=?&#x27;
调用 db.query() 执行 SQL 语句，更新对应用户的头像：
db.query(sql, [req.body.avatar, req.user.id], (err, results) =&gt; &#123; // 执行 SQL 语句失败 if (err) return res.cc(err) // 执行 SQL 语句成功，但是影响行数不等于 1 if (results.affectedRows !== 1) return res.cc(&#x27;更新头像失败！&#x27;) // 更新用户头像成功 return res.cc(&#x27;更新头像成功！&#x27;, 0)&#125;) 4. 文章分类管理 4.1 新建 ev_article_cate 表 4.1.1 创建表结构
4.1.2 新增两条初始数据
4.2 获取文章分类列表 4.2.0 实现步骤
