修改 /router/artcate.js 中的代码如下：
const express = require(&#x27;express&#x27;)const router = express.Router()// 导入文章分类的路由处理函数模块const artcate_handler = require(&#x27;../router_handler/artcate&#x27;)// 获取文章分类的列表数据router.get(&#x27;/cates&#x27;, artcate_handler.getArticleCates)module.exports = router 4.2.3 获取文章分类列表数据
在 /router_handler/artcate.js 头部导入数据库操作模块：
// 导入数据库操作模块const db = require(&#x27;../db/index&#x27;)
定义 SQL 语句：
// 根据分类的状态，获取所有未被删除的分类列表数据// is_delete 为 0 表示没有被 标记为删除 的数据const sql = &#x27;select * from ev_article_cate where is_delete=0 order by id asc&#x27;
调用 db.query() 执行 SQL 语句：
db.query(sql, (err, results) =&gt; &#123; // 1. 执行 SQL 语句失败 if (err) return res.cc(err) // 2. 执行 SQL 语句成功 res.send(&#123; status: 0, message: &#x27;获取文章分类列表成功！&#x27;, data: results, &#125;)&#125;) 4.3 新增文章分类 4.3.0 实现步骤
