// 导入定义验证规则的模块const joi = require(&#x27;@hapi/joi&#x27;)// 定义 分类名称 和 分类别名 的校验规则const name = joi.string().required()const alias = joi.string().alphanum().required()// 校验规则对象 - 添加分类exports.add_cate_schema = &#123; body: &#123; name, alias, &#125;,&#125;
在 /router/artcate.js 模块中，使用 add_cate_schema 对数据进行验证：
