定义查重的 SQL 语句：
// 定义查询 分类名称 与 分类别名 是否被占用的 SQL 语句const sql = `select * from ev_article_cate where name=? or alias=?`
调用 db.query() 执行查重的操作：
// 执行查重操作db.query(sql, [req.body.name, req.body.alias], (err, results) =&gt; &#123; // 执行 SQL 语句失败 if (err) return res.cc(err) // 判断 分类名称 和 分类别名 是否被占用 if (results.length === 2) return res.cc(&#x27;分类名称与别名被占用，请更换后重试！&#x27;) // 分别判断 分类名称 和 分类别名 是否被占用 if (results.length === 1 &amp;&amp; results[0].name === req.body.name) return res.cc(&#x27;分类名称被占用，请更换后重试！&#x27;) if (results.length === 1 &amp;&amp; results[0].alias === req.body.alias) return res.cc(&#x27;分类别名被占用，请更换后重试！&#x27;) // TODO：新增文章分类&#125;) 4.3.4 实现新增文章分类的功能
