// 校验规则对象 - 根据 Id 获取分类exports.get_cate_schema = &#123; params: &#123; id, &#125;,&#125;
在 /router/artcate.js 模块中，导入需要的验证规则对象，并在路由中使用：
// 导入根据 Id 获取分类的验证规则对象const &#123; get_cate_schema &#125; = require(&#x27;../schema/artcate&#x27;)// 根据 Id 获取文章分类的路由router.get(&#x27;/cates/:id&#x27;, expressJoi(get_cate_schema), artcate_handler.getArticleById) 4.5.3 实现获取文章分类的功能
定义根据 Id 获取文章分类的 SQL 语句：
const sql = `select * from ev_article_cate where id=?`
调用 db.query() 执行 SQL 语句：
db.query(sql, req.params.id, (err, results) =&gt; &#123; // 执行 SQL 语句失败 if (err) return res.cc(err) // SQL 语句执行成功，但是没有查询到任何数据 if (results.length !== 1) return res.cc(&#x27;获取文章分类数据失败！&#x27;) // 把数据响应给客户端 res.send(&#123; status: 0, message: &#x27;获取文章分类数据成功！&#x27;, data: results[0], &#125;)&#125;) 4.6 根据 Id 更新文章分类数据 4.6.0 实现步骤
定义路由和处理函数 验证表单数据 查询 分类名称 与 分类别名 是否被占用 实现更新文章分类的功能
4.6.1 定义路由和处理函数
在 /router/artcate.js 模块中，添加 更新文章分类 的路由：
// 更新文章分类的路由router.post(&#x27;/updatecate&#x27;, artcate_handler.updateCateById)
在 /router_handler/artcate.js 模块中，定义并向外共享 更新文章分类 的路由处理函数：
// 更新文章分类的处理函数exports.updateCateById = (req, res) =&gt; &#123; res.send(&#x27;ok&#x27;)&#125; 4.6.2 验证表单数据
在 /schema/artcate.js 验证规则模块中，使用 exports 向外共享如下的 验证规则对象：
// 校验规则对象 - 更新分类exports.update_cate_schema = &#123; body: &#123; Id: id, name, alias, &#125;,&#125;
在 /router/artcate.js 模块中，导入需要的验证规则对象，并在路由中使用：
// 导入更新文章分类的验证规则对象const &#123; update_cate_schema &#125; = require(&#x27;../schema/artcate&#x27;)// 更新文章分类的路由router.post(&#x27;/updatecate&#x27;, expressJoi(update_cate_schema), artcate_handler.updateCateById) 4.5.4 查询分类名称与别名是否被占用
定义查重的 SQL 语句：
// 定义查询 分类名称 与 分类别名 是否被占用的 SQL 语句const sql = `select * from ev_article_cate where Id&lt;&gt;? and (name=? or alias=?)`
调用 db.query() 执行查重的操作：
// 执行查重操作db.query(sql, [req.body.Id, req.body.name, req.body.alias], (err, results) =&gt; &#123; // 执行 SQL 语句失败 if (err) return res.cc(err) // 判断 分类名称 和 分类别名 是否被占用 if (results.length === 2) return res.cc(&#x27;分类名称与别名被占用，请更换后重试！&#x27;) if (results.length === 1 &amp;&amp; results[0].name === req.body.name) return res.cc(&#x27;分类名称被占用，请更换后重试！&#x27;) if (results.length === 1 &amp;&amp; results[0].alias === req.body.alias) return res.cc(&#x27;分类别名被占用，请更换后重试！&#x27;) // TODO：更新文章分类&#125;) 4.5.5 实现更新文章分类的功能
定义更新文章分类的 SQL 语句：
const sql = `update ev_article_cate set ? where Id=?`
调用 db.query() 执行 SQL 语句：
db.query(sql, [req.body, req.body.Id], (err, results) =&gt; &#123; // 执行 SQL 语句失败 if (err) return res.cc(err) // SQL 语句执行成功，但是影响行数不等于 1 if (results.affectedRows !== 1) return res.cc(&#x27;更新文章分类失败！&#x27;) // 更新文章分类成功 res.cc(&#x27;更新文章分类成功！&#x27;, 0)&#125;) 5. 文章管理 5.1 新建 ev_articles 表
5.2 发布新文章 5.2.0 实现步骤
初始化路由模块 初始化路由处理函数模块 使用 multer 解析表单数据 验证表单数据 实现发布文章的功能
5.2.1 初始化路由模块
创建 /router/article.js 路由模块，并初始化如下的代码结构：
// 导入 expressconst express = require(&#x27;express&#x27;)// 创建路由对象const router = express.Router()// 发布新文章router.post(&#x27;/add&#x27;, (req, res) =&gt; &#123; res.send(&#x27;ok&#x27;)&#125;)// 向外共享路由对象module.exports = router
在 app.js 中导入并使用文章的路由模块：
// 导入并使用文章路由模块const articleRouter = require(&#x27;./router/article&#x27;)// 为文章的路由挂载统一的访问前缀 /my/articleapp.use(&#x27;/my/article&#x27;, articleRouter) 5.2.2 初始化路由处理函数模块
创建 /router_handler/article.js 路由处理函数模块，并初始化如下的代码结构：
// 发布新文章的处理函数exports.addArticle = (req, res) =&gt; &#123; res.send(&#x27;ok&#x27;)&#125;
修改 /router/article.js 中的代码如下：
const express = require(&#x27;express&#x27;)const router = express.Router()// 导入文章的路由处理函数模块const article_handler = require(&#x27;../router_handler/article&#x27;)// 发布新文章router.post(&#x27;/add&#x27;, article_handler.addArticle)module.exports = router 5.2.3 使用 multer 解析表单数据
注意：使用 express.urlencoded() 中间件无法解析 multipart/form-data 格式的请求体数据。
当前项目，推荐使用 multer 来解析 multipart/form-data 格式的表单数据。https://www.npmjs.com/package/multer
运行如下的终端命令，在项目中安装 multer：
npm i multer@1.4.2
在 /router_handler/article.js 模块中导入并配置 multer：
// 导入解析 formdata 格式表单数据的包const multer = require(&#x27;multer&#x27;)// 导入处理路径的核心模块const path = require(&#x27;path&#x27;)// 创建 multer 的实例对象，通过 dest 属性指定文件的存放路径const upload = multer(&#123; dest: path.join(__dirname, &#x27;../uploads&#x27;) &#125;)
修改 发布新文章 的路由如下：
// 发布新文章的路由// upload.single() 是一个局部生效的中间件，用来解析 FormData 格式的表单数据// 将文件类型的数据，解析并挂载到 req.file 属性中// 将文本类型的数据，解析并挂载到 req.body 属性中router.post(&#x27;/add&#x27;, upload.single(&#x27;cover_img&#x27;), article_handler.addArticle)
在 /router_handler/article.js 模块中的 addArticle 处理函数中，将 multer 解析出来的数据进行打印：
// 发布新文章的处理函数exports.addArticle = (req, res) =&gt; &#123; console.log(req.body) // 文本类型的数据 console.log(&#x27;--------分割线----------&#x27;) console.log(req.file) // 文件类型的数据 res.send(&#x27;ok&#x27;)&#125;) 5.2.4 验证表单数据
实现思路：通过 express-joi 自动验证 req.body 中的文本数据；通过 if 判断手动验证 req.file 中的文件数据；
创建 /schema/article.js 验证规则模块，并初始化如下的代码结构：
// 导入定义验证规则的模块const joi = require(&#x27;@hapi/joi&#x27;)// 定义 标题、分类Id、内容、发布状态 的验证规则const title = joi.string().required()const cate_id = joi.number().integer().min(1).required()const content = joi.string().required().allow(&#x27;&#x27;)const state = joi.string().valid(&#x27;已发布&#x27;, &#x27;草稿&#x27;).required()// 验证规则对象 - 发布文章exports.add_article_schema = &#123; body: &#123; title, cate_id, content, state, &#125;,&#125;
在 /router/article.js 模块中，导入需要的验证规则对象，并在路由中使用：
// 导入验证数据的中间件const expressJoi = require(&#x27;@escook/express-joi&#x27;)// 导入文章的验证模块const &#123; add_article_schema &#125; = require(&#x27;../schema/article&#x27;)// 发布新文章的路由// 注意：在当前的路由中，先后使用了两个中间件：// 先使用 multer 解析表单数据// 再使用 expressJoi 对解析的表单数据进行验证router.post(&#x27;/add&#x27;, upload.single(&#x27;cover_img&#x27;), expressJoi(add_article_schema), article_handler.addArticle)
在 /router_handler/article.js 模块中的 addArticle 处理函数中，通过 if 判断客户端是否提交了 封面图片：
// 发布新文章的处理函数exports.addArticle = (req, res) =&gt; &#123; // 手动判断是否上传了文章封面 if (!req.file || req.file.fieldname !== &#x27;cover_img&#x27;) return res.cc(&#x27;文章封面是必选参数！&#x27;) // TODO：表单数据合法，继续后面的处理流程...&#125;) 5.2.5 实现发布文章的功能
整理要插入数据库的文章信息对象：
// 导入处理路径的 path 核心模块const path = require(&#x27;path&#x27;)const articleInfo = &#123; // 标题、内容、状态、所属的分类Id ...req.body, // 文章封面在服务器端的存放路径 cover_img: path.join(&#x27;/uploads&#x27;, req.file.filename), // 文章发布时间 pub_date: new Date(), // 文章作者的Id author_id: req.user.id,&#125;
定义发布文章的 SQL 语句：
const sql = `insert into ev_articles set ?`
调用 db.query() 执行发布文章的 SQL 语句：
// 导入数据库操作模块const db = require(&#x27;../db/index&#x27;)// 执行 SQL 语句db.query(sql, articleInfo, (err, results) =&gt; &#123; // 执行 SQL 语句失败 if (err) return res.cc(err) // 执行 SQL 语句成功，但是影响行数不等于 1 if (results.affectedRows !== 1) return res.cc(&#x27;发布文章失败！&#x27;) // 发布文章成功 res.cc(&#x27;发布文章成功&#x27;, 0)&#125;)
在 app.js 中，使用 express.static() 中间件，将 uploads 目录中的图片托管为静态资源：
// 托管静态资源文件app.use(&#x27;/uploads&#x27;, express.static(&#x27;./uploads&#x27;))

简易hw1程序对拍器分享 对于hw1的作业而言，题目要求我们去括号并尽可能化简表达式，但在化简过程中由于式子较为复杂，表达式常常会难以判断是否化简正确，所以设计合适的对拍器就显得十分重要。 思路介绍 当我想到这个问题时当时主要有两种思路，第一种是使用赋值法，将变量x,y,z进行赋值（可能选用质数会比较好，数据不容易相同），这也是当时在实验1时我们所解的程序可以达到的功能（当然不完善），这种方法在大部分时间可以使用，但还是相对复杂且需要决定初始变量值，还有一定可能会出现结果相同表达式不同的情况，所以我主要想介绍下第二种思路。 第二种思路就是将输入和自己程序跑出的输出进行相同转化后比较是否相同（例如降幂顺序排列之类的），这样本身当然也有很大的编程难度，但是python中的simpify函数很好的给我们提供了这个功能（注意是simpify[转化]而不是simplify[简化]）,借助sympy.sympify()方法，我们能够将字符串类型的表达式转换为通用数学表达式。这样只需要依靠对拍结果字符串比较就知道是否正确了。 附上简易代码： import sympyimport osMy_path = &#x27;D:/coding_file/study/Lesson/oo_lesson/OO/test/hw1&#x27;def judge_equal(expr_in, expr_out): simpy_in = sympy.core.sympify(expr_in) simpy_out = sympy.core.sympify(expr_out) if (simpy_in.equals(simpy_out)): print(&quot;success!!!&quot;) else: print(&quot;failed!!!&quot;) with open(My_path+&#x27;/error_log.txt&#x27;, &#x27;a+&#x27;) as h: h.write(&quot;expr_in:&quot;+str(expr_in)+&quot;
&quot;) h.write(&quot;simpy_in:&quot;+str(simpy_in)+&quot;
&quot;) h.write(&quot;expr_out:&quot;+str(expr_out)+&quot;
&quot;) h.write(&quot;simpy_out:&quot;+str(simpy_out)+&quot;
&quot;) h.write(&quot;---------------------------
&quot;)os.chdir(My_path)os.system(&#x27;python production.py&#x27;)os.system(&#x27;java -jar hw1_test.jar &lt; in.txt &gt; out.txt&#x27;)with open(My_path+&#x27;/in.txt&#x27;, &#x27;r+&#x27;) as f: expr_in = f.read().rstrip()with open(My_path+&#x27;/out.txt&#x27;, &#x27;r+&#x27;) as g: expr_out = g.read().rstrip()judge_equal(expr_in, expr_out) 说明 其中error_log.txt为错误数据的日志，hw1_test.jar为自己java工程的工件，in.txt为依靠production.py随机生成的数据，My_Path为该测试文件夹的路径，将这几个文件放于该文件夹下即可使用（当然记得装sympy包，这是成熟6系人的基本素养orz）
PS：在有数据生成器的情况下只需要加入for循环即可完成多次自动化测试
简易hacker机 import sympyimport osMy_path = &#x27;D:/coding_file/study/Lesson/oo_lesson/OO/test/hw1&#x27;names = [&#x27;hw1_test&#x27;] # other person jar namedef judge_equal(expr_in, expr_out, name): simpy_in = sympy.core.sympify(expr_in) simpy_out = sympy.core.sympify(expr_out) if (simpy_in.equals(simpy_out)): print(&quot;&gt;&gt;&gt;&gt;&gt;The comparison result with &quot;+str(name) + &quot; is:&quot;) print(&quot;success!!!&quot;) else: print(&quot;&gt;&gt;&gt;&gt;&gt;The comparison result with &quot;+str(name) + &quot; is:&quot;) print(&quot;failed!!!&quot;) with open(My_path+&#x27;/src/error_log.txt&#x27;, &#x27;a+&#x27;) as h: h.write(str(name)+&quot;:error&quot;+&quot;
&quot;) h.write(&quot;expr_in:&quot;+str(expr_in)+&quot;
&quot;) h.write(&quot;simpy_in:&quot;+str(simpy_in)+&quot;
&quot;) h.write(&quot;expr_out:&quot;+str(expr_out)+&quot;
&quot;) h.write(&quot;simpy_out:&quot;+str(simpy_out)+&quot;
&quot;) h.write(&quot;---------------------------
&quot;)num = 0os.chdir(My_path)while(num &lt;= 5000): print(&#x27;num = &#x27; + str(num)) i = 0 os.system(&#x27;python production.py&#x27;) while i &lt;= len(names)-1: os.system(&#x27;java -jar &#x27;+str(names[i])+&#x27;.jar &lt; src/in.txt &gt; src/out.txt&#x27;) with open(My_path+&#x27;/src/in.txt&#x27;, &#x27;r+&#x27;) as f: expr_in = f.read().rstrip() with open(My_path+&#x27;/src/out.txt&#x27;, &#x27;r+&#x27;) as g: expr_out = g.read().rstrip() judge_equal(expr_in, expr_out, names[i]) i = i+1 num = num+1

基础控件 Text Text 用来展示一行或多行的文本内容，效果等同于 UILabel，但更加优秀。 如果要创建 Text， 只需通过 Text(&quot;SwiftUI&quot;) 即可创建； 采用链式语法，也可以为文本添加多项属性，如字体、颜色、阴影、上左下右的间距等。 示例： Text(&quot;SwiftUI&quot;) .foregroundColor(.orange) .bold() .font(.system(.largeTitle)) .fontWeight(.medium) .italic() .shadow(color: .black, radius: 1, x: 0, y: 2)
HStack 和 VStack 控件用于承载多个视图，在后面会提到。
TextField TextField 用来添加普通的输入框，一般常用作文本输入。 示例： TextField(self.$name, placeholder: self.nameText, onEditingChanged: &#123; changed in print(&quot;onEditing: \(changed)&quot;)&#125;) &#123; print(&quot;userName: \(self.name)&quot;) self.endEditing(true)&#125;&#125;.padding(10).frame(height: 50).textFieldStyle(RoundedBorderTextFieldStyle()).padding(EdgeInsets(top: 0, leading: 20, bottom: 0, trailing: 20))
SecureField SecureField 一般作为密码输入时使用，使用方式与 TextField 并无差别，示例与运行效果同上 TextField。 Image Image 控件用于展示图片。 示例： Image(&quot;icon&quot;) .resizable() .frame(width: 100, height: 100, alignment: .center)
WebImage webImage 用于下载网络图片，使用的 URLSession下载成功后替换原有 Image；你也可以在 downloadWebImage 方法中使用 Kingfisher 。 示例： var body: some View &#123; Image(uiImage: self.uiImage ?? placeholderImage) .resizable() .onAppear(perform: downloadWebImage) .frame(width: 80, height: 80, alignment: .center) .onTapGesture &#123; print(&quot;Tap &quot;) &#125; &#125;
Button Button 用于响应点击事件。 示例： Button(action: &#123; print(&quot;Tap&quot;)&#125;) &#123; Text(&quot;I&#x27;m a Button&quot;)&#125; EditButton EditButton 用以触发编辑状态，使用时只需在 navigationBarItems 设置即可。 示例： navigationBarItems(trailing: EditButton())
Picker Picker 可自定义数据源的选择器。 示例: Picker(selection: $leftIndex, label: Text(&quot;Picker&quot;)) &#123; ForEach(0..&lt;leftSource.count) &#123; Text(self.leftSource[$0]).tag($0) &#125; &#125;.frame(width: UIScreen.main.bounds.width/2)
DatePicker DatePicker 用于选择绝对日期的控件。 示例： DatePicker(selection: $server.date, in: server.spaceDate, displayedComponents: .date, label: &#123; Text(&quot;&quot;) &#125;)
Toggle Toggle 用于切换选中状态。 示例： Toggle(isOn: $isOn) &#123; Text(&quot;State: \(self.isOn == true ? &quot;开&quot;:&quot;关&quot;)&quot;)&#125;.padding(20)
Slider Slider 用于从有限值范围中选值的控件。 示例： Slider(value: $data.rating)
Stepper Stepper 用以增加或减少数值。 示例： Stepper(value: $value, step: 2, onEditingChanged: &#123; c in print(c)&#125;) &#123; Text(&quot;Stepper Value: \(self.value)&quot;) &#125;.padding(50)
WebView WebView 用于展示一个打开的网页。 示例: struct WebViewPage : UIViewRepresentable &#123; func makeUIView(context: Context) -&gt; WKWebView &#123; return WKWebView() &#125; func updateUIView(_ uiView: WKWebView, context: Context) &#123; let req = URLRequest(url: URL(string: &quot;https://www.apple.com&quot;)!) uiView.load(req) &#125;&#125;
UIViewController UIViewController 用于展示在 SwiftUI 中打开 UIKit 的 UIViewController ，并且在 UIViewController 中打开 SwiftUI View。 示例: 先定义： struct ControllerPage&lt;T: UIViewController&gt; : UIViewControllerRepresentable &#123; typealias UIViewControllerType = UIViewController func makeUIViewController(context: UIViewControllerRepresentableContext&lt;ControllerPage&gt;) -&gt; UIViewController &#123; return T() &#125; func updateUIViewController(_ uiViewController: UIViewController, context: UIViewControllerRepresentableContext&lt;ControllerPage&gt;) &#123; debugPrint(&quot;\(#function)：\(type(of: T.self))&quot;) &#125; &#125; 然后调用： NavigationButton(destination: ControllerPage&lt;UIKitController&gt;()) &#123; PageRow(title: &quot;UIViewController&quot;,subTitle: &quot;打开 UIViewController&quot;)&#125;
布局 HStack HStack 用于将子视图排列在水平线上的视图。 示例: HStack &#123; Text(&quot;made in China.&quot;) Divider() // Just add a line. Text(&quot;the People&#x27;s Republic Of China.&quot;)&#125;
VStack VStack 用于将子视图排列在垂直线上的视图。 示例: VStack &#123; Text(&quot;made in China.&quot;) Divider() // Just add a line. Text(&quot;the People&#x27;s Republic Of China.&quot;)&#125;
ZStack ZStack 用于覆盖子视图，在两轴上对齐。 示例: ZStack &#123; Text(&quot;made in China.&quot;) Divider() // Just add a line. Text(&quot;the People&#x27;s Republic Of China.&quot;)&#125;
List List 列表容器，用以显示一列数据。 示例: List(0..&lt;5) &#123; item in Text(&quot;Hello World !&quot;)&#125;.navigationBarTitle(Text(&quot;List&quot;), displayMode: .large)
ScrollView ScrollView 是一个滚动视图容器。 示例: ScrollView &#123; Text(&quot;SwiftUI&quot;).padding(20) Divider() Image(&quot;icon&quot;).resizable() .frame(width: 300, height: 300, alignment: .center) Divider() Text(&quot;Views and ... user interface.&quot;) &#125; .border(Color.gray.gradient, width: 1) .cornerRadius(10) .padding(10) .navigationBarTitle(Text(&quot;ScrollView&quot;))
ForEach ForEach 用于根据已有数据的集合展示视图。 示例: let data = (0..&lt;5)var body: some View &#123; ForEach(data) &#123; e in Text(&quot;Hello \(e)&quot;) .bold() .font(.system(size: 25, design: .monospaced)) .padding(5)&#125;
Group Group 用于集合多个视图，对 Group 设置的属性，将作用于每个子视图。 示例: Group &#123; Text(&quot;Hello World !&quot;) Text(&quot;Hello World !&quot;) &#125;
Section Section 用于创建带头/尾部的视图内容，一般结合 List 组件使用。 示例: Section(header: Text(&quot;I&#x27;m header&quot;), footer: Text(&quot;I&#x27;m footer&quot;)) &#123; ForEach(0..&lt;3) &#123; Text(&quot;Hello \($0)&quot;) &#125;&#125;
Form Form 是对一组数据输入进行控制的容器。 Example: Form &#123; TextField(&quot;First Name&quot;, text: $firstName) TextField(&quot;Last Name&quot;, text: $lastName)&#125;
NavigationView NavigationView 用于创建包含顶部导航栏的视图容器。 示例: NavigationView &#123; Text(&quot;🧚‍♂️🧚‍♀️🧜‍♂️🧜‍♀️🧞‍♂️🧞‍♀️&quot;).blur(radius: 5) Text(&quot;Swifter Swifter&quot;) .bold() .foregroundColor(.orange) .font(.largeTitle) &#125; .navigationBarTitle(Text(&quot;NavigationView&quot;))
TabView TabView 用于创建包含底部 TabBar 的视图容器。 示例: TabView(selection: $index) &#123; ForEach(0..&lt;imgs.count) &#123; item in TabItemPage(index: item) .tabItem&#123; Image(self.imgs[item]) Text(&quot;\(item)&quot;) &#125; .tag(item) &#125;&#125;
Alert Alert 用于展示一个弹框提醒，需要与点击事件关联起来。 示例: alert(isPresented: $showAlert, content: &#123; Alert(title: Text(&quot;确定要支付这100000000美元吗？&quot;), message: Text(&quot;请谨慎操作\n一旦确认，钱款将立即转入对方账户&quot;), primaryButton: .destructive(Text(&quot;确认&quot;)) &#123; print(&quot;转出中...&quot;) &#125;, secondaryButton: .cancel()) &#125;).navigationBarTitle(Text(&quot;Alert&quot;))
ActionSheet ActionSheet 用于弹出一个选择框。 示例: ActionSheet(title: Text(&quot;Title&quot;), message: Text(&quot;Message&quot;), buttons: [.default(Text(&quot;Default&quot;), onTrigger: &#123; print(&quot;Default&quot;) self.showSheet = false &#125;),.destructive(Text(&quot;destructive&quot;), onTrigger: &#123; print(&quot;destructive&quot;) self.showSheet = false &#125;),.cancel(&#123; print(&quot;Cancel&quot;) self.showSheet = false &#125;)]) 使用： .actionSheet(isPresented: $showSheet, content: &#123;sheet&#125;)
Modal Modal 用于弹出一个视图。 示例: Modal(Text(&quot;Modal View&quot;),onDismiss: &#123; print(&quot;View Dismiss !&quot;)&#125;)
Popover Popover 用于弹出一个视图，样式见下方运行结果。 示例: .popover(isPresented: $showPop, content: &#123; ImagePage() &#125;)

网络应用
Vue.js 2.0 版本推荐使用 axios 来完成 ajax 请求。
axios基本使用 &lt;!DOCTYPE html&gt;&lt;html lang=&quot;en&quot;&gt;&lt;head&gt; &lt;meta charset=&quot;UTF-8&quot; /&gt; &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot; /&gt; &lt;meta http-equiv=&quot;X-UA-Compatible&quot; content=&quot;ie=edge&quot; /&gt; &lt;title&gt;axios基本使用&lt;/title&gt;&lt;/head&gt;&lt;body&gt; &lt;input type=&quot;button&quot; value=&quot;get请求&quot; class=&quot;get&quot;&gt; &lt;input type=&quot;button&quot; value=&quot;post请求&quot; class=&quot;post&quot;&gt; &lt;!-- 官网提供的 axios 在线地址 --&gt; &lt;script src=&quot;https://unpkg.com/axios/dist/axios.min.js&quot;&gt;&lt;/script&gt; &lt;script&gt; /* 接口1:随机笑话 请求地址:https://autumnfish.cn/api/joke/list 请求方法:get 请求参数:num(笑话条数,数字) 响应内容:随机笑话 */ document.querySelector(&quot;.get&quot;).onclick = function () &#123; axios.get(&quot;https://autumnfish.cn/api/joke/list?num=6&quot;) // axios.get(&quot;https://autumnfish.cn/api/joke/list1234?num=6&quot;) .then(function (response) &#123; console.log(response); &#125;,function(err)&#123; console.log(err); &#125;) &#125; /* 接口2:用户注册 请求地址:https://autumnfish.cn/api/user/reg 请求方法:post 请求参数:username(用户名,字符串) 响应内容:注册成功或失败 */ document.querySelector(&quot;.post&quot;).onclick = function () &#123; axios.post(&quot;https://autumnfish.cn/api/user/reg&quot;,&#123;username:&quot;盐焗西兰花&quot;&#125;) .then(function(response)&#123; console.log(response); console.log(this.skill); &#125;,function (err) &#123; console.log(err); &#125;) &#125; &lt;/script&gt;&lt;/body&gt;&lt;/html&gt;
axios必须先导入才可以使用 使用get或post方法即可发送对应的请求 then方法中的回调函数会在请求成功或失败时触发 通过回调函数的形参可以获取响应内容,或错误信息
axios+vue &lt;!DOCTYPE html&gt;&lt;html lang=&quot;en&quot;&gt;&lt;head&gt; &lt;meta charset=&quot;UTF-8&quot;&gt; &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt; &lt;meta http-equiv=&quot;X-UA-Compatible&quot; content=&quot;ie=edge&quot;&gt; &lt;title&gt;axios+vue&lt;/title&gt;&lt;/head&gt;&lt;body&gt; &lt;div id=&quot;app&quot;&gt; &lt;input type=&quot;button&quot; value=&quot;获取笑话&quot; @click=&quot;getJoke&quot;&gt; &lt;p&gt; &#123;&#123; joke &#125;&#125;&lt;/p&gt; &lt;/div&gt; &lt;!-- 官网提供的 axios 在线地址 --&gt; &lt;script src=&quot;https://unpkg.com/axios/dist/axios.min.js&quot;&gt;&lt;/script&gt; &lt;!-- 开发环境版本，包含了有帮助的命令行警告 --&gt; &lt;script src=&quot;https://cdn.jsdelivr.net/npm/vue/dist/vue.js&quot;&gt;&lt;/script&gt; &lt;script&gt; /* 接口:随机获取一条笑话 请求地址:https://autumnfish.cn/api/joke 请求方法:get 请求参数:无 响应内容:随机笑话 */ var app = new Vue(&#123; el:&quot;#app&quot;, data:&#123; joke:&quot;很好笑的笑话&quot; &#125;, methods: &#123; getJoke:function()&#123; // console.log(this.joke); var that = this; axios.get(&quot;https://autumnfish.cn/api/joke&quot;).then(function(response)&#123; // console.log(response) console.log(response.data); // console.log(this.joke); that.joke = response.data; &#125;,function (err) &#123; &#125;) &#125; &#125;, &#125;) &lt;/script&gt;&lt;/body&gt;&lt;/html&gt;
axios回调函数中的this已经改变,无法访问到data中数据 把this保存起来,回调函数中直接使用保存的this即可 和本地应用的最大区别就是改变了数据来源

本地应用
通过Vue实现常见的网页效果 学习Vue指令,以案例巩固知识点 Vue指令指的是,以v-开头的一组特殊语法
v-text &lt;!DOCTYPE html&gt;&lt;html lang=&quot;en&quot;&gt;&lt;head&gt; &lt;meta charset=&quot;UTF-8&quot;&gt; &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt; &lt;meta http-equiv=&quot;X-UA-Compatible&quot; content=&quot;ie=edge&quot;&gt; &lt;title&gt;v-text指令&lt;/title&gt;&lt;/head&gt;&lt;body&gt; &lt;div id=&quot;app&quot;&gt; &lt;h2 v-text=&quot;message+&#x27;!&#x27;&quot;&gt;深圳&lt;/h2&gt; &lt;h2 v-text=&quot;info+&#x27;!&#x27;&quot;&gt;深圳&lt;/h2&gt; &lt;h2&gt;&#123;&#123; message +&#x27;!&#x27;&#125;&#125;深圳&lt;/h2&gt; &lt;/div&gt; &lt;!-- 开发环境版本，包含了有帮助的命令行警告 --&gt; &lt;script src=&quot;https://cdn.jsdelivr.net/npm/vue/dist/vue.js&quot;&gt;&lt;/script&gt; &lt;script&gt; var app = new Vue(&#123; el:&quot;#app&quot;, data:&#123; message:&quot;黑马程序员!!!&quot;, info:&quot;前端与移动教研部&quot; &#125; &#125;) &lt;/script&gt;&lt;/body&gt;&lt;/html&gt;
v-text指令的作用是:设置标签的内容(textContent) 默认写法会替换全部内容,使用差值表达式&#123;&#123;&#125;&#125;可以替换指定内容 内部支持写表达式
v-html
HTML 属性中的值应使用 v-bind 指令
&lt;!DOCTYPE html&gt;&lt;html lang=&quot;en&quot;&gt;&lt;head&gt; &lt;meta charset=&quot;UTF-8&quot;&gt; &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt; &lt;meta http-equiv=&quot;X-UA-Compatible&quot; content=&quot;ie=edge&quot;&gt; &lt;title&gt;v-html指令&lt;/title&gt;&lt;/head&gt;&lt;body&gt; &lt;div id=&quot;app&quot;&gt;&lt;/div&gt; &lt;!-- 开发环境版本，包含了有帮助的命令行警告 --&gt; &lt;script src=&quot;https://cdn.jsdelivr.net/npm/vue/dist/vue.js&quot;&gt;&lt;/script&gt; &lt;script&gt; var app = new Vue(&#123; el:&quot;#app&quot;, data:&#123; content:&quot;黑马程序员&quot; &#125; &#125;) &lt;/script&gt;&lt;/body&gt;&lt;/html&gt;
v-html指令的作用是:设置元素的innerHTML 内容中有html结构会被解析为标签 v-text指令无论内容是什么,只会解析为文本 解析文本使用v-text,需要解析html结构使用v-html
v-on &lt;!DOCTYPE html&gt;&lt;html lang=&quot;en&quot;&gt;&lt;head&gt; &lt;meta charset=&quot;UTF-8&quot;&gt; &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt; &lt;meta http-equiv=&quot;X-UA-Compatible&quot; content=&quot;ie=edge&quot;&gt; &lt;title&gt;v-on补充&lt;/title&gt;&lt;/head&gt;&lt;body&gt; &lt;div id=&quot;app&quot;&gt; &lt;input type=&quot;button&quot; value=&quot;点击&quot; @click=&quot;doIt(666,&#x27;老铁&#x27;)&quot;&gt; &lt;input type=&quot;text&quot; @keyup.enter=&quot;sayHi&quot;&gt; &lt;/div&gt; &lt;!-- 1.开发环境版本，包含了有帮助的命令行警告 --&gt; &lt;script src=&quot;https://cdn.jsdelivr.net/npm/vue/dist/vue.js&quot;&gt;&lt;/script&gt; &lt;script&gt; var app = new Vue(&#123; el:&quot;#app&quot;, methods: &#123; doIt:function(p1,p2)&#123; console.log(&quot;做it&quot;); console.log(p1); console.log(p2); &#125;, sayHi:function()&#123; alert(&quot;吃了没&quot;); &#125; &#125;, &#125;) &lt;/script&gt;&lt;/body&gt;&lt;/html&gt;
v-on指令的作用是:为元素绑定事件 事件名不需要写on 指令可以简写为@ 绑定的方法定义在methods属性中 方法内部通过this关键字可以访问定义在data中数据
Summary1
创建Vue示例时:el(挂载点),data(数据),methods(方法)
v-on指令的作用是绑定事件,简写为@
方法中通过this,关键字获取data中的数据
v-text指令的作用是:设置元素的文本值,简写为&#123;&#123;&#125;&#125;
v-html指令的作用是:设置元素的innerHTML
v-show &lt;!DOCTYPE html&gt;&lt;html lang=&quot;en&quot;&gt; &lt;head&gt; &lt;meta charset=&quot;UTF-8&quot; /&gt; &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot; /&gt; &lt;meta http-equiv=&quot;X-UA-Compatible&quot; content=&quot;ie=edge&quot; /&gt; &lt;title&gt;v-show指令&lt;/title&gt; &lt;/head&gt; &lt;body&gt; &lt;div id=&quot;app&quot;&gt; &lt;input type=&quot;button&quot; value=&quot;切换显示状态&quot; @click=&quot;changeIsShow&quot;&gt; &lt;input type=&quot;button&quot; value=&quot;累加年龄&quot; @click=&quot;addAge&quot;&gt; &lt;img v-show=&quot;isShow&quot; src=&quot;./img/monkey.gif&quot; alt=&quot;&quot;&gt; &lt;img v-show=&quot;age&gt;=18&quot; src=&quot;./img/monkey.gif&quot; alt=&quot;&quot;&gt; &lt;/div&gt; &lt;!-- 1.开发环境版本，包含了有帮助的命令行警告 --&gt; &lt;script src=&quot;https://cdn.jsdelivr.net/npm/vue/dist/vue.js&quot;&gt;&lt;/script&gt; &lt;script&gt; var app = new Vue(&#123; el:&quot;#app&quot;, data:&#123; isShow:false, age:17 &#125;, methods: &#123; changeIsShow:function()&#123; this.isShow = !this.isShow; &#125;, addAge:function()&#123; this.age++; &#125; &#125;, &#125;) &lt;/script&gt; &lt;/body&gt;&lt;/html&gt;
v-show指令的作用是:根据真假切换元素的显示状态 原理是修改元素的display,实现显示隐藏 指令后面的内容,最终都会解析为布尔值 值为true元素显示,值为false元素隐藏 数据改变之后,对应元素的显示状态会同步更新
v-if &lt;!DOCTYPE html&gt;&lt;html lang=&quot;en&quot;&gt;&lt;head&gt; &lt;meta charset=&quot;UTF-8&quot;&gt; &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt; &lt;meta http-equiv=&quot;X-UA-Compatible&quot; content=&quot;ie=edge&quot;&gt; &lt;title&gt;v-if指令&lt;/title&gt;&lt;/head&gt;&lt;body&gt; &lt;div id=&quot;app&quot;&gt; &lt;input type=&quot;button&quot; value=&quot;切换显示&quot; @click=&quot;toggleIsShow&quot;&gt; &lt;p v-if=&quot;isShow&quot;&gt;黑马程序员&lt;/p&gt; &lt;p v-show=&quot;isShow&quot;&gt;黑马程序员 - v-show修饰&lt;/p&gt; &lt;h2 v-if=&quot;temperature&gt;=35&quot;&gt;热死啦&lt;/h2&gt; &lt;/div&gt; &lt;!-- 开发环境版本，包含了有帮助的命令行警告 --&gt; &lt;script src=&quot;https://cdn.jsdelivr.net/npm/vue/dist/vue.js&quot;&gt;&lt;/script&gt; &lt;script&gt; var app = new Vue(&#123; el:&quot;#app&quot;, data:&#123; isShow:false, temperature:20 &#125;, methods: &#123; toggleIsShow:function()&#123; this.isShow = !this.isShow; &#125; &#125;, &#125;) &lt;/script&gt;&lt;/body&gt;&lt;/html&gt;
v-if指令的作用是:根据表达式的真假切换元素的显示状态 本质是通过操纵dom元素来切换显示状态 表达式的值为true,元素存在于dom树中,为false,从dom树中移除 频繁的切换v-show,反之使用v-if,前者的切换消耗小
v-else 可以用 v-else 指令给 v-if 添加一个 “else” 块 v-else-if v-else-if 在 2.1.0 新增，顾名思义，用作 v-if 的 else-if 块。可以链式的多次使用 v-bind &lt;!DOCTYPE html&gt;&lt;html lang=&quot;en&quot;&gt;&lt;head&gt; &lt;meta charset=&quot;UTF-8&quot;&gt; &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt; &lt;meta http-equiv=&quot;X-UA-Compatible&quot; content=&quot;ie=edge&quot;&gt; &lt;title&gt;v-bind指令&lt;/title&gt; &lt;style&gt; .active&#123; border: 1px solid red; &#125; &lt;/style&gt;&lt;/head&gt;&lt;body&gt; &lt;div id=&quot;app&quot;&gt; &lt;img v-bind:src=&quot;imgSrc&quot; alt=&quot;&quot;&gt; &lt;br&gt; &lt;img :src=&quot;imgSrc&quot; alt=&quot;&quot; :title=&quot;imgTitle+&#x27;!!!&#x27;&quot; :class=&quot;isActive?&#x27;active&#x27;:&#x27;&#x27;&quot; @click=&quot;toggleActive&quot;&gt; &lt;br&gt; &lt;img :src=&quot;imgSrc&quot; alt=&quot;&quot; :title=&quot;imgTitle+&#x27;!!!&#x27;&quot; :class=&quot;&#123;active:isActive&#125;&quot; @click=&quot;toggleActive&quot;&gt; &lt;/div&gt; &lt;!-- 开发环境版本，包含了有帮助的命令行警告 --&gt; &lt;script src=&quot;https://cdn.jsdelivr.net/npm/vue/dist/vue.js&quot;&gt;&lt;/script&gt; &lt;script&gt; var app = new Vue(&#123; el:&quot;#app&quot;, data:&#123; imgSrc:&quot;http://www.itheima.com/images/logo.png&quot;, imgTitle:&quot;黑马程序员&quot;, isActive:false &#125;, methods: &#123; toggleActive:function()&#123; this.isActive = !this.isActive; &#125; &#125;, &#125;) &lt;/script&gt;&lt;/body&gt;&lt;/html&gt;
v-bind指令的作用是:为元素绑定属性 完整写法是 v-bind:属性名 简写的话可以直接省略v-bind,只保留 :属性名 需要动态的增删class建议使用对象的方式
summary2
列表数据使用数组保存 v-bind指令可以设置元素属性,比如src v-show和v-if都可以切换元素的显示状态,频繁切换用v-show
v-for &lt;!DOCTYPE html&gt;&lt;html lang=&quot;en&quot;&gt;&lt;head&gt; &lt;meta charset=&quot;UTF-8&quot;&gt; &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt; &lt;meta http-equiv=&quot;X-UA-Compatible&quot; content=&quot;ie=edge&quot;&gt; &lt;title&gt;v-for指令&lt;/title&gt;&lt;/head&gt;&lt;body&gt; &lt;div id=&quot;app&quot;&gt; &lt;input type=&quot;button&quot; value=&quot;添加数据&quot; @click=&quot;add&quot;&gt; &lt;input type=&quot;button&quot; value=&quot;移除数据&quot; @click=&quot;remove&quot;&gt; &lt;ul&gt; &lt;li v-for=&quot;(it,index) in arr&quot;&gt; &#123;&#123; index+1 &#125;&#125;黑马程序员校区:&#123;&#123; it &#125;&#125; &lt;/li&gt; &lt;/ul&gt; &lt;h2 v-for=&quot;item in vegetables&quot; v-bind:title=&quot;item.name&quot;&gt; &#123;&#123; item.name &#125;&#125; &lt;/h2&gt; &lt;/div&gt; &lt;!-- 1.开发环境版本，包含了有帮助的命令行警告 --&gt; &lt;script src=&quot;https://cdn.jsdelivr.net/npm/vue/dist/vue.js&quot;&gt;&lt;/script&gt; &lt;script&gt; var app = new Vue(&#123; el:&quot;#app&quot;, data:&#123; arr:[&quot;北京&quot;,&quot;上海&quot;,&quot;广州&quot;,&quot;深圳&quot;], vegetables:[ &#123;name:&quot;西兰花炒蛋&quot;&#125;, &#123;name:&quot;蛋炒西蓝花&quot;&#125; ] &#125;, methods: &#123; add:function()&#123; this.vegetables.push(&#123; name:&quot;花菜炒蛋&quot; &#125;); &#125;, remove:function()&#123; this.vegetables.shift(); &#125; &#125;, &#125;) &lt;/script&gt;&lt;/body&gt;&lt;/html&gt;
v-for指令的作用是:根据数据生成列表结构 数组经常和v-for结合使用 语法是( item,index ) in 数据 item 和 index 可以结合其他指令一起使用 数组长度的更新会同步到页面上,是响应式的
v-on补充 &lt;!DOCTYPE html&gt;&lt;html lang=&quot;en&quot;&gt;&lt;head&gt; &lt;meta charset=&quot;UTF-8&quot;&gt; &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt; &lt;meta http-equiv=&quot;X-UA-Compatible&quot; content=&quot;ie=edge&quot;&gt; &lt;title&gt;v-on补充&lt;/title&gt;&lt;/head&gt;&lt;body&gt; &lt;div id=&quot;app&quot;&gt; &lt;input type=&quot;button&quot; value=&quot;点击&quot; @click=&quot;doIt(666,&#x27;老铁&#x27;)&quot;&gt; &lt;input type=&quot;text&quot; @keyup.enter=&quot;sayHi&quot;&gt; &lt;/div&gt; &lt;!-- 1.开发环境版本，包含了有帮助的命令行警告 --&gt; &lt;script src=&quot;https://cdn.jsdelivr.net/npm/vue/dist/vue.js&quot;&gt;&lt;/script&gt; &lt;script&gt; var app = new Vue(&#123; el:&quot;#app&quot;, methods: &#123; doIt:function(p1,p2)&#123; console.log(&quot;做it&quot;); console.log(p1); console.log(p2); &#125;, sayHi:function()&#123; alert(&quot;吃了没&quot;); &#125; &#125;, &#125;) &lt;/script&gt;&lt;/body&gt;&lt;/html&gt;
事件绑定的方法写成函数调用的形式，可以传入自定义参数 定义方法时需要定义形参来接收传入的实参 事件的后面跟上 .修饰符 可以对事件进行限制 .enter 可以限制触发的按键为回车 事件修饰符有多种
v-model &lt;!DOCTYPE html&gt;&lt;html lang=&quot;en&quot;&gt;&lt;head&gt; &lt;meta charset=&quot;UTF-8&quot;&gt; &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt; &lt;meta http-equiv=&quot;X-UA-Compatible&quot; content=&quot;ie=edge&quot;&gt; &lt;title&gt;v-model指令&lt;/title&gt;&lt;/head&gt;&lt;body&gt; &lt;div id=&quot;app&quot;&gt; &lt;input type=&quot;button&quot; value=&quot;修改message&quot; @click=&quot;setM&quot;&gt; &lt;input type=&quot;text&quot; v-model=&quot;message&quot; @keyup.enter=&quot;getM&quot;&gt; &lt;h2&gt;&#123;&#123; message &#125;&#125;&lt;/h2&gt; &lt;/div&gt; &lt;!-- 开发环境版本，包含了有帮助的命令行警告 --&gt; &lt;script src=&quot;https://cdn.jsdelivr.net/npm/vue/dist/vue.js&quot;&gt;&lt;/script&gt; &lt;script&gt; var app = new Vue(&#123; el:&quot;#app&quot;, data:&#123; message:&quot;黑马程序员&quot; &#125;, methods: &#123; getM:function()&#123; alert(this.message); &#125;, setM:function()&#123; this.message =&quot;酷丁鱼&quot;; &#125; &#125;, &#125;) &lt;/script&gt;&lt;/body&gt;&lt;/html&gt;
v-model指令的作用是便捷的设置和获取表单元素的值 绑定的数据会和表单元素值相关联 绑定的数据←→表单元素的值
修饰符 .lazy 在默认情况下， v-model 在 input 事件中同步输入框的值与数据，但你可以添加一个修饰符 lazy ，从而转变为在 change 事件中同步： &lt;!-- 在 &quot;change&quot; 而不是 &quot;input&quot; 事件中更新 --&gt;&lt;input v-model.lazy=&quot;msg&quot; &gt; .number 如果想自动将用户的输入值转为 Number 类型（如果原值的转换结果为 NaN 则返回原值），可以添加一个修饰符 number 给 v-model 来处理输入值： &lt;input v-model.number=&quot;age&quot; type=&quot;number&quot;&gt; 这通常很有用，因为在 type=“number” 时 HTML 中输入的值也总是会返回字符串类型。 .trim 如果要自动过滤用户输入的首尾空格，可以添加 trim 修饰符到 v-model 上过滤输入： &lt;input v-model.trim=&quot;msg&quot;&gt; summary3
列表结构可以通过v-for指令结合数据生成 v-on结合事件修饰符可以对事件进行限制,比如.enter v-on在绑定事件时可以传递自定义参数 通过v-model可以快速的设置和获取表单元素的值 基于数据的开发方式

