;    struct Linknode* next;&#125;* LinkNode;typedef struct &#123;    LinkNode *front, *rear;&#125; LinkQueue;void InitQueue(LinkQueue&amp; Q) &#123;    Q.front = Q.rear = (LinkNode*)malloc(sizeof(LinkNode));    Q.front-&gt;next = NULL;&#125;void testLinkQueue() &#123;    LinkQueue Q;    InitQueue(Q);&#125;bool IsEmpty(LinkQueue Q) &#123;    if (Q.front == Q.rear) &#123;        return true;    &#125; else &#123;        return false;    &#125;&#125;bool IsEmpty(LinkQueue Q) &#123;    if (Q.front == NULL) &#123;        return true;    &#125; else &#123;        return false;    &#125;&#125;void EnQueue(LinkQueue&amp; Q, int x) &#123;    LinkNode* s = (LinkNode*)malloc(sizeof(LinkNode));    s-&gt;data = x;    s-&gt;next = NULL;    Q.rear-&gt;next = s;    Q.rear = s;&#125;void EnQueue(LinkQueue&amp; Q, int x) &#123;    LinkNode* s = (LinkNode*)malloc(sizeof(LinkNode));    s-&gt;data = x;    s-&gt;next = NULL;    if (Q.front == NULL) &#123;        Q.front = s;        Q.rear = s;    &#125; else &#123;        Q.rear-&gt;next = s;        Q.rear = s;    &#125;&#125;bool DeQueue(LinkQueue&amp; Q, int&amp; x) &#123;    if (Q.front == Q.rear) &#123;        return false;    &#125;    LinkNode* p = Q.front-&gt;next;    if (Q.rear == p) &#123;        Q.rear = Q.front;    &#125;    free(p);    return true;&#125;bool DeQueue(LinkQueue&amp; Q, int&amp; x) &#123;    if (Q.front == NULL) &#123;        return false;    &#125;    LinkNode* p = Q.front x = p-&gt;data;    Q.front = p-&gt;next;    if (Q.rear == p) &#123;        Q.rear = NULL;        Q.front = NULL;    &#125;    free(p);    return true;&#125;

