 线性表笔记
#include &lt;ctype.h&gt;#include &lt;limits.h&gt;#include &lt;math.h&gt;#include &lt;stdbool.h&gt;#include &lt;stdio.h&gt;#include &lt;stdlib.h&gt;#include &lt;string.h&gt;// 备注：c语言中无引用，所以下列函数需要通过指针进行修改。（后续笔记同）// 线性表笔记// 顺序表相关函数：#define MaxSize 10typedef struct &#123;    ElemType data[MaxSize];    int length;&#125; SqList;  // 静态分配void InitList(SqList&amp; L) &#123;    int i;    for (i = 0; i &lt; MaxSize; i++) &#123;        L.data[i] = 0;    &#125;    L.length = 0;&#125;  // 顺序表初始化#define InitSize 10typedef struct &#123;    ElemType data;  // 指示动态分配数组的指针    int MaxSize;    int length;&#125; SeqList;  // 动态分配void InitList(SeqList&amp; L) &#123;    L.data = (int*)malloc(InitSize * sizeof(int));    L.length = 0;    L.MaxSize = InitSize;&#125;  // 动态分配初始化void IncreaseSize(SeqList&amp; L, int* len*) &#123;    int* p = L.data;    L.data = (int*)malloc((L.length + len) * sizeof(int));    int i;    for (i = 0; i &lt; L.length; i++) &#123;        L.data[i] = p[i];  // 将数据复制到新区域    &#125;    L.MaxSize += len;  // 顺序表最大长度增加len    free(P);&#125;  // 增加动态数组的长度bool ListInsert(SqList&amp; L, int i, int e) &#123;    // 在表L的位序i的位置插入元素e    if (i &lt; 1 || i &gt; L.length + 1) &#123;        return false;    &#125;  // 判断i的范围是否有效    if (L.length &gt;= MaxSize) &#123;        return false;    &#125;  // 存储空间已满，不能插入    int j;    for (j = L.length; j &gt;= i; j--) &#123;        L.data[j] = L.data[j - 1];    &#125;  // 元素后移    L.data[i - 1] = e;    L.length++;    return true;&#125;  // 顺序表插入bool ListDelete(SqList&amp; L, int i, int&amp; e) &#123;    // 删除表L的位序i的位置的元素    // ，该函数使用前要把e定义为-1把删除的元素带回来    if (i &lt; 1 || i &gt; L.length) &#123;        return false;    &#125;                   // 判断i的范围是否有效    e = L.data[i - 1];  // 将被删除的元素赋值给e    int j;    for (j = i; j &lt; L.length; j++) &#123;        L.data[j - 1] = L.data[j];    &#125;    L.length--;    return true;&#125;  // 顺序表变量删除ElemType GetElem(SqList L, int i) &#123;    return L.data[i - 1];&#125;  // 静（动）态分配按位查找int LocateElem(SeqList L, ElemType e) &#123;    int i;    for (i = 0; i &lt; L.length; i++) &#123;        if (L.data[i] == e) &#123;            return i + 1;        &#125;    &#125;    return 0;&#125;  // 按值查找// 链表的相关函数：// 单链表：typedef struct LNode &#123;    ElemType data;    struct LNode* next;&#125; LNode, *LinkList;bool InitList(LinkList&amp; L) &#123;    L = NULL;    return true;&#125;  // 初始化单链表（不带头结点）bool InitList(LinkList&amp; L) &#123;    L = (LNode*)malloc(sizeof(LNode));    if (L == NULL) &#123;        return false;    &#125;    L-&gt;next = NULL;    return true;&#125;  // 初始化单链表（带头结点）bool ListInsert(LinkList&amp; L, int i, ElemType e) &#123;    if (i &lt; 1) &#123;        return false;    &#125;    LNode* p;    int j = 0;    p = L;  // L指向头结点，头结点是第0个节点    while (p != NULL &amp;&amp; j &lt; i - 1) &#123;        p = p-&gt;next;        j++;    &#125;    if (p == NULL) &#123;        return false;    &#125;    LNode* s = (LNode*)malloc(sizeof(LNode));    s-&gt;data = e;    s-&gt;next = p-&gt;next;    p-&gt;next = s;    return true;&#125;  // 单链表插入数据（带头结点）bool ListInsert(LinkList&amp; L, int i, ElemType e) &#123;    if (i &lt; 1) &#123;        return false;    &#125;    if (i == 1) &#123;        LNode* s = (LNode*)malloc(sizeof(LNode));        s-&gt;data = e;        s-&gt;next = L;        L = s;  // 头指针指向新节点        return true;    &#125;    LNode* p;    int j = 1;    p = L;  // L指向头结点，头结点是第0个节点    while (p != NULL &amp;&amp; j &lt; i - 1) &#123;        p = p-&gt;next;        j++;    &#125;    if (p == NULL) &#123;        return false;    &#125;    LNode* s = (LNode*)malloc(sizeof(LNode));    s-&gt;data = e;    s-&gt;next = p-&gt;next;    p-&gt;next = s;    return true;&#125;  // 单链表插入数据（不带头结点）bool InsertNextNode(LNode** P*, ElemType e) &#123;    if (p == NULL) &#123;        return false;    &#125;    LNode* s = (LNode*)malloc(sizeof(LNode));    if (s == NULL) &#123;        return false;  // 内存分配失败    &#125;    s-&gt;data = e;    s-&gt;next = p-&gt;next;    p-&gt;next = s;    return true;&#125;  // 指定节点的后插操作 （在p节点之后插入元素e)bool InsertPriorNode(LNode** P*, ElemType e) &#123;    if (p == NULL) &#123;        return false;    &#125;    LNode* s = (LNode*)malloc(sizeof(LNode));    if (s == NULL) &#123;        return false;  // 内存分配失败    &#125;    s-&gt;next = p-&gt;next;    p-&gt;next = s;    s-&gt;data = p-&gt;data;    p-&gt;data = e;    return true;&#125;  // 指定节点的前插操作 （在p节点之前插入元素e)bool ListDelete(LinkList&amp; L, int i, ElemType&amp; e) &#123;    if (i &lt; 1) &#123;        return false;    &#125;    LNode* p;    int j = 0;    p = L;    while (p != NULL &amp;&amp; j &lt; i - 1) &#123;        p = p-&gt;next;        j++;    &#125;    if (p == NULL) &#123;        return false;    &#125;    if (p-&gt;next == NULL) &#123;        return false;    &#125;    LNode* q = p-&gt;next;    e = q-&gt;data;    p-&gt;next = q-&gt;next;    free(q);    return true;&#125;  // 按位序删除（带头结点）bool DeleteNode(LNode** p*) &#123;    if (p == NULL) &#123;        return false;    &#125;    LNode* q = p-&gt;next;    p-&gt;data = p-&gt;next-&gt;data;    p-&gt;next = q-&gt;next;    free(q);    return true;&#125;  // 删除指定节点p（该代码无法处理位于最后一个位置的情况）LNode* GetElem(LinkList L, int i) &#123;    if (i &lt; 0) &#123;        return NULL;    &#125;    LNode* p;    int j = 0;    p = L;    while (p != NULL &amp;&amp; j &lt; i) &#123;        p = p-&gt;next;        j++;    &#125;    return p;&#125;  // 按位查找（带头结点）LNode* LocateElem(LinkList L, ElemType e) &#123;    LNode* p = L-&gt;next;    while (p != NULL &amp;&amp; p-&gt;data != e) &#123;        p = p-&gt;next;    &#125;    return p;&#125;  // 按值查找（带头指针）int Length(LinkList L) &#123;    int len = 0;    LNode* p = L;    while (p-&gt;next != NULL) &#123;        p = p-&gt;next;        len++;    &#125;    return len;&#125;  // 求表的长度(带头指针）LinkList List_TailInsert(LinkList&amp; L) &#123;    int x;    L = (LinkList)malloc(sizeof(LNode));    LNode *s, *r = L;    scanf(&quot;%d&quot;, &amp;x);    while (x != 9999) &#123;  // 输入9999表示结束        s = (LNode*)malloc(sizeof(LNode));        s-&gt;data = x;        r-&gt;next = s;        r = s;        scanf(&quot;%d&quot;, &amp;x);    &#125;    r-&gt;next = NULL;    return L;&#125;  // 尾插法建立单链表LinkList List_HeadInsert(LinkList&amp; L) &#123;    LNode* s;    int x;    L = (LinkList)malloc(sizeof(LNode));    L-&gt;next = NULL;    scanf(&quot;%d&quot;, &amp;x);    while (x != 9999) &#123;  // 输入9999表示结束        s = (LNode*)malloc(sizeof(LNode));        s-&gt;data = x;        s-&gt;next = L-&gt;next;        L-&gt;next = s;        scanf(&quot;%d&quot;, &amp;x);    &#125;    return L;&#125;  // 头插法建立单链表// 双链表：typedef struct DNode &#123;    ElemType data;    struct DNode *prior, *next;&#125; DNode, *DLinklist;bool InitDLinkList(DLinklist&amp; L) &#123;    L = (DNode*)malloc(sizeof(DNode));    if (L == NULL) &#123;        return false;    &#125;    L-&gt;prior = NULL;    L-&gt;next = NULL;    return true;&#125;  // 初始化双链表bool Empty(DLinklist L) &#123;    if (L-&gt;next == NULL) &#123;        return true;    &#125; else &#123;        return false;    &#125;&#125;  // 判断双链表是否为空（带头结点）bool InsertNextDNode(DNode** p*, DNode** s*) &#123;    if (p == NULL || s == NULL) &#123;        return false;    &#125;    s-&gt;next = p-&gt;next;    if (p-&gt;next != NULL) &#123;        p-&gt;next-&gt;prior = s;    &#125;    s-&gt;prior = p;    p-&gt;next = s;    return true;&#125;  // 在p节点之后插入s节点bool DeleteNextNode(DNode** p*) &#123;    if (p == NULL) &#123;        return false;    &#125;    DNode* q = p-&gt;next;    if (q == NULL) &#123;        return false;    &#125;    p-&gt;next = q-&gt;next;    if (q-&gt;next != NULL) &#123;        q-&gt;next-&gt;prior = p;    &#125;    free(q);    return true;&#125;  // 删除p节点的后继节点void DestoryList(DLinklist&amp; L) &#123;    while (L-&gt;next != NULL) &#123;        DeleteNextNode(L);    &#125;    free(L);    L = NULL;&#125;  // 销毁双链表// 循环单链表：typedef struct LNode &#123;    ElemType data;    struct LNode* next;&#125; LNode, *LinkList;bool InitList(LinkList&amp; L) &#123;    L = (LNode*)malloc(sizeof(LNode));    if (L == NULL) &#123;        return false;    &#125;    L-&gt;next = L;    return true;&#125;  // 初始化循环单链表bool isTail(LinkList L, LNode** p*) &#123;    if (p-&gt;next == L) &#123;        return true;    &#125; else &#123;        return false;    &#125;&#125;  // 判断节点p是否为循环单链表的表尾节点// 循环双链表：typedef struct LNode &#123;    ElemType data;    struct LNode *prior, *next;&#125; DNode, *DLinkList;bool InitDLinkList(DLinkList&amp; L) &#123;    L = (DNode*)malloc(sizeof(DNode));    if (L == NULL) &#123;        return false;    &#125;    L-&gt;prior = L;    L-&gt;next = L;    return true;&#125;  // 初始化循环双链表bool Empty(DLinkList L) &#123;    if (L-&gt;next == L) &#123;        return true;    &#125; else &#123;        return false;    &#125;&#125;  // 判断节循环双链表是否为空bool isTail(DLinkList L, DNode** p*) &#123;    if (p-&gt;next == L) &#123;        return true;    &#125; else &#123;        return false;    &#125;&#125;  // 判断节点p是否为循环单链表的表尾节点// 静态列表：#define MaxSize 10typedef struct LNode &#123;    ElemType data;    int next;&#125; SLinkList[MaxSize];

game-theory-algorithm 博弈算法 博弈问题的特点 1.博弈模型为两人轮流决策的非合作博弈。即两人轮流进行决策，并且两人都使用最优策略来获取胜利 2.博弈是有限的。即无论两人怎样决策，都会在有限步后决出胜负 3.公平博弈。即两人进行决策所遵循的规则相同 几种常见博弈类型问题 1.巴什博弈
1、问题模型：有一个堆物品，物品数量为n个，两个人轮流从这堆物品中取物品，规定每次至少取一个，最多取m个，最后取光者得胜。 2、解决思路：当n=m+1时，由于一次最多只能取m个，所以无论先取者拿走多少个，后取者都能够一次拿走剩余的物品，后者取胜，所以当一方面对的局势是n%(m+1)=0时，其面临的是必败的局势。所以当n=（m+1)*r+s，（r为任意自然数，s≤m)时,如果先取者要拿走s个物品，如果后取者拿走x（≤m)个，那么先取者再拿走m+1-k个，结果剩下（m+1）（r-1）个，以后保持这样的取法，那么先取者肯定获胜。总之，要保持给对手留下（m+1）的倍数，就能最后获胜。 结论:如果条件是最后取光者得胜，那么当先手面临的局势是n%(m+1)==0，先手必败 #include &lt;stdio.h&gt;int main() &#123; int T; scanf(&quot;%d&quot;, &amp;T); while (T--) &#123; int n, m; scanf(&quot;%d%d&quot;, &amp;n, &amp;m); if (n % (m + 1) == 0) printf(&quot;second win\n&quot;); else printf(&quot;first win\n&quot;); &#125; return 0;&#125; 3、变形：条件不变，改为最后取光的人输。 结论：如果条件是最后取光者失败，那么当先手面临的局势是(n-1)%(m+1)==0时，先手必败。
2.威佐夫博弈
1、问题模型：有两堆各若干个物品，两个人轮流从某一堆或同时从两堆中取同样多的物品，规定每次至少取一个，多者不限，最后取光者得胜。 2、解决思路: 设(ai,bi) (ai ≤bi ,i=0，1，2，…,n)表示两堆物品的数量并称其为局势，如果甲面对(0,0)，那么甲已经输了，这种局势我们称为奇异局势。前几个奇异局势是：(0,0)、(1,2)、(3,5)、(4,7)、(6,10)、(8,13)、(9,15)、(11,18)、(12,20)。任给一个局势(a,b)，如下公式判断它是不是奇异局势：ak=[k(1+√5)/2]，bk=ak+k (k=0，1，2，…,n 方括号表示取整函数)。 3、满足上公式的局势性质： （1）任何自然数都包含在一个且仅有一个奇异局势中。 ​ 由于ak是未在前面出现过的最小自然数，所以有ak&gt;ak-1,而bk=ak+k&gt;ak-1+k-1=bk-1&gt;ak-1,所以性质成立。 （2）任意操作都可将奇异局势变为非奇异局势。 若只改变奇异局势(ak，bk)的某一个分量，那么另一个分量不可能在其他奇异局势中，所以必然是非奇异局势。如果使(ak，bk)的两个分量同时减少，则由于其差不变，且不可能是其他奇异局势的差，因此也是非奇异局势 （3）采用适当的方法，可以将非奇异局势变为奇异局势。 假设面对的局势是（a,b），若 b = a，则同时从两堆中取走 a 个物体，就变为了奇异局势（0，0）；如果a = ak ，b &gt; bk，那么，取走b – bk个物体，即变为奇异局势；如果 a = ak,b &lt; bk ,则同时从两堆中拿走 ak – ab – ak个物体,变为奇异局势（ ab – ak , ab – ak+ b – ak）；如果a &gt; ak,b= ak + k,则从第一堆中拿走多余的数量a – ak 即可；如果a &lt; ak ，b= ak + k,分两种情况，第一种，a=aj （j &lt; k）,从第二堆里面拿走 b – bj 即可； 第二种，a=bj (j&lt;k),从第二堆里面拿走 b – aj 即可。 4、结论：两个人如果都采用正确操作，那么面对非奇异局势，先拿者必胜；反之，则后拿者取胜。 #include &lt;math.h&gt;#include &lt;stdio.h&gt;#include &lt;algorithm&gt;using namespace std;int main() &#123; int a, b; while (~scanf(&quot;%d%d&quot;, &amp;a, &amp;b)) &#123; if (a &gt; b) swap(a, b); int ans = floor((b - a) * (sqrt(5) + 1) / 2); // 判断是否是奇异局势 if (a == ans) printf(&quot;second win\n&quot;); else printf(&quot;first win\n&quot;); &#125; return 0;&#125;
3.斐波那契博弈
1、问题模型： 有一堆个数为n的石子，游戏双方轮流取石子，满足： （1）先手不能在第一次把所有的石子取完； （2）之后每次可以取的石子数介于1到对手刚取的石子数的2倍之间（包含1和对手刚取的石子数的2倍）。 约定取走最后一个石子的人为赢家。 2、解决思路： ​ 当n为Fibonacci数时，先手必败。即存在先手的必败态当且仅当石头个数为Fibonacci数。 证明： 根据“Zeckendorf定理”（齐肯多夫定理）：任何正整数可以表示为若干个不连续的Fibonacci数之和。如n=83=55+21+5+2。我们看看这个分解有什么指导意义：假如先手取2颗，那么后手无法取5颗或更多，而5是一个Fibonacci数，那么一定是先手取走这5颗石子中的最后一颗，同理，接下去先手取走接下来的后21颗中的最后一颗，再取走后55颗中的最后一颗，那么先手赢。 反证：如果n是Fibonacci数，如n=89：记先手一开始所取的石子数为y （1）若y&gt;=34颗（也就是89的向前两项），那么一定后手赢，因为89-34=55=34+21&lt;2*34。 （2）y&lt;34时剩下的石子数x介于55到89之间，它一定不是一个Fibonacci数，把x分解成Fibonacci数：x=55+f[i]+…+f[j]，若，如果f[j]&lt;=2y，那么对B就是面临x局面的先手，所以根据之前的分析，后手只要先取f[j]个即可，以后再按之前的分析就可保证必胜。 #include &lt;iostream&gt;using namespace std;int main() &#123; long long n, temp, a, b; int mark; while (cin &gt;&gt; n) &#123; a = 2; b = 3; mark = 0; while (a &lt;= n) &#123; if (a == n || b == n) mark = 1; else &#123; temp = a + b; a = b; b = temp; // 模拟斐波那契序列 &#125; &#125; if (mark) cout &lt;&lt; &quot;Second win&quot; &lt;&lt; endl; else if (!mark) cout &lt;&lt; &quot;First win&quot; &lt;&lt; endl; &#125; return 0;&#125;
4.尼姆博弈
1、问题模型：有三堆各若干个物品，两个人轮流从某一堆取任意多的物品，规定每次至少取一个，多者不限，最后取光者得胜。 2、解决思路：用（a，b，c）表示某种局势，显证（0，0，0）是第一种奇异局势，无论谁面对奇异局势，都必然失败。第二种奇异局势是（0，n，n），只要与对手拿走一样多的物品，最后都将导致（0，0，0）。 搞定这个问题需要把必败态的规律找出：(a,b,c)是必败态等价于abc=0(^表示异或运算）。 证明:(1)任何从p(a,b,c)=0局面出发的任意局面(a,b,c’);一定有p(a,b,c’)不等于0。否则可以得到c=c’。 ​ (2)任何p(a,b,c)不等于0的局面都可以走向 p(a,b,c)=0的局面 ​ (3)对于 (4,9,13) 这个容易验证是奇异局势 ​ 其中有两个8，两个4，两个1，非零项成对出现，这就是尼姆和为 零的本质。别人要是拿掉13里的8或者1，那你就拿掉对应的9 中的那个8或者1；别人要是拿掉13里的4，你就拿掉4里的4；别人如果拿掉13里的3，就把10作分解，然后想办法满 足非零项成对即可。 3、推广一：如果我们面对的是一个非奇异局势（a，b，c），要如何变为奇异局势呢？假设 a &lt; b&lt; c,我们只要将 c 变为 a^b,即可,因为有如下的运算结果: ab(ab)=(aa)(bb)=0^0=0。要将c 变为a^b，只从 c中减去 c-（a^b） 4、推广二：当石子堆数为n堆时，则推广为当对每堆的数目进行亦或之后值为零是必败态。 #include&lt;stdio.h&gt;int main()&#123; int a,b,c; while(~scanf(&quot;%d%d%d&quot;,&amp;a,&amp;b,&amp;c))&#123; int flag=a^b^c; if(!flag) printf(&quot;second win\n&quot;); else printf(&quot;first win\n&quot;); &#125; return 0;&#125; 5.最大最小原则 最小最大间题(minimax): 用于确定计算机玩家在诸如并字游戏、跳棋、奥赛罗和国际象棋中的哪一步。这类游戏被称为完美信息游戏,因为它可以看到所有可能的动作。拼字游戏并不是一个完美信息的游戏,因为你看不到对手的手,所以无法预测对手的动作。 可以把这个算法想象成人类的思维过程:如果我做这个动作,那么我的对手只能做个动作,每个动作都会让我赢。所以这是正确的选择。 如果你认为所谓最小最大就是穷举过程中找到的最差走法和最佳走法那就错了,既然是对立的概念，当然是两个对象,这里的最小最大是当前轮到 AI走了，AI进行穷举并选择一条对于 AI来说最佳而对于人来说最差的走法,但是再考虑一下,机器也是有限的,对于象棋这样棋盘较大的游戏,穷举完博弈树在当前科技下不可能，因此我们的最小最大算法需要一个深度,即向前走几步,计算机就能在这个指定的比较小的整数下完成对博弈树的穷举。 当遍历若干树枝后不可能就结束了,如果在游戏没有结束的情况下我们还需要一个评价启发函数,这个函数用于判断当前策略的价值,如果使用某走法能赢,就返回一个大的正数;如果这种走法会输,就返回一个大的负值;如果走法会产生和局,就返回一个0左右的数;如果由于当前博弈树深度没办法判断局面,那么评价函数就会返回一个启发值。 下面是有关最大最小原则的一段伪代码。 #include &lt;cstdio&gt;int MaxMin(int depth, int play_mode) &#123; int best = INFINITY(play_mode); //player_mode 是参照物,如果当前落子是人,则返回一个很小的值,反之返回一个很大的值 if (depth &lt;= 0) &#123; //当前以局面为博弈树的根 return Evaluate(); //估值函数 &#125; //生成当前所有走法 GenerateLegalMoves(); //遍历每一个走法 while (MovesLeft()) &#123; //实施走法 MakeNextMove(); //换位思考 int val = -MaxMin(depth - 1, play_mode); //撤销走法 UnmakeMove(); if (val &gt; best) &#123; best = val; &#125; &#125; return best;&#125;

high-precision-algorithm 高精度
​ 在一般的科学计算中，会经常算到小数点后几百位或者更多，当然也可能是几千亿几百亿的大数字。一般这类数字我们统称为高精度数，高精度算法是用计算机对于超大数据的一种模拟加、减、乘、除、乘方、阶乘、开方等运算。 对于一个很大的数字N &gt;= 10^ 100，很显然这样的数字无法在计算机中正常存储。于是， 我们想到了办法，将这个数字拆开，拆成一位一位的或者是四位四位的存储到一个数组中，用一个数组去表示一个数字。这样这个数字就被称谓是高精度数。 对于高精度数，也要像平常数一样做加减乘除以及乘方的运算，于是就有了高精度算法。
1.高精度加法 void high_precision_add(string num1, string num2, string&amp; res) &#123; int l1 = num1.size(), l2 = num2.size(); int len = l1 &gt; l2 ? l1 : l2; int a[N] = &#123;0&#125;, b[N] = &#123;0&#125;; for (int i = l1 - 1; i &gt;= 0; i--) a[l1 - i - 1] = num1.at(i) - &#x27;0&#x27;; for (int i = l2 - 1; i &gt;= 0; i--) b[l2 - i - 1] = num2.at(i) - &#x27;0&#x27;; for (int i = 0; i &lt; len; i++) &#123; a[i] += b[i]; a[i + 1] += a[i] / 10; a[i] %= 10; &#125; if (a[len]) len++; while (!a[len - 1] &amp;&amp; len &gt; 1) len--; for (int i = len - 1; i &gt;= 0; i--) &#123; res += (a[i] + &#x27;0&#x27;); &#125;&#125; 2.高精度乘法 void high_precision_multiply(string num1, string num2, string&amp; res) &#123; int l1 = num1.size(), l2 = num2.size(); int a[N] = &#123;0&#125;, b[N] = &#123;0&#125;, c[N] = &#123;0&#125;; for (int i = l1 - 1; i &gt;= 0; i--) a[l1 - i - 1] = num1.at(i) - &#x27;0&#x27;; for (int i = l2 - 1; i &gt;= 0; i--) b[l2 - i - 1] = num2.at(i) - &#x27;0&#x27;; for (int i = 0; i &lt; l1; i++) &#123; for (int j = 0; j &lt; l2; j++) &#123; c[i + j] += a[i] * b[j]; if (a[i] &gt; 9) &#123; a[i + 1] += a[i] / 10; a[i] %= 10; &#125; &#125; &#125; int len = l1 + l2; for (int i = 0; i &lt; len; i++) &#123; if (c[i] &gt; 9) &#123; c[i + 1] += c[i] / 10; c[i] %= 10; &#125; &#125; while (!c[len - 1] &amp;&amp; len &gt; 1) len--; for (int i = len - 1; i &gt;= 0; i--) &#123; res += (c[i] + &#x27;0&#x27;); &#125;&#125; 3.高精度减法 void high_precision_sub(string num1, string num2, string&amp; res) &#123; int l1 = num1.size(), l2 = num2.size(), flag = 0; if (l1 &lt; l2 || num1.compare(num2) &lt; 0 &amp;&amp; l1 == l2) &#123; flag = 1; &#125; int a[N] = &#123;0&#125;, b[N] = &#123;0&#125;; if (!flag) &#123; for (int i = l1 - 1; i &gt;= 0; i--) a[l1 - i - 1] = num1.at(i) - &#x27;0&#x27;; for (int i = l2 - 1; i &gt;= 0; i--) b[l2 - i - 1] = num2.at(i) - &#x27;0&#x27;; &#125; else &#123; for (int i = l2 - 1; i &gt;= 0; i--) a[l2 - i - 1] = num2.at(i) - &#x27;0&#x27;; for (int i = l1 - 1; i &gt;= 0; i--) b[l1 - i - 1] = num1.at(i) - &#x27;0&#x27;; &#125; int len = l1 &gt; l2 ? l1 : l2; for (int i = 0; i &lt; len; i++) &#123; a[i] -= b[i]; if (a[i] &lt; 0) &#123; a[i + 1] -= 1; a[i] += 10; &#125; &#125; while (!a[len - 1] &amp;&amp; len &gt; 1) len--; if (flag) &#123; res += &#x27;-&#x27;; &#125; for (int i = len - 1; i &gt;= 0; i--) &#123; res += (a[i] + &#x27;0&#x27;); &#125;&#125; 4.高精度除法 void sub(string&amp; num1, string&amp; num2) &#123; int l2 = num2.size(); int low = 0; while (num1.at(low) == &#x27;0&#x27;) low++; for (int i = low; i &lt; l2; i++) num1.at(i) = num1.at(i) - num2.at(i) + &#x27;0&#x27;; for (int i = l2 - 1; i &gt; low; i--) if (num1.at(i) &lt; &#x27;0&#x27;) &#123; num1.at(i) += 10; num1.at(i - 1)--; &#125;&#125;void high_precision_div(string num1, string num2, string&amp; res) &#123; int p = 0, re[N] = &#123;0&#125;; int l1 = num1.size(); int l2 = num2.size(); if (l1 &lt; l2 || (l1 == l2 &amp;&amp; num1.compare(num2) &lt; 0)) res = &quot;0&quot;; else &#123; while (1) &#123; re[p] = 0; while (num1.compare(num2) &gt;= 0) &#123; sub(num1, num2); re[p]++; &#125; p++; if (l1 == l2) break; num2 = &quot;0&quot; + num2; l2++; &#125; int low = 0; while (!re[low]) low++; for (int i = low; i &lt; p; i++) res += (re[i] + &#x27;0&#x27;); &#125;&#125; 模板题 阶乘之和 [NOIP1998 普及组] 阶乘之和 题目描述 用高精度计算出 S=1!+2!+3!+⋯+n!S = 1! + 2! + 3! + \cdots + n!S=1!+2!+3!+⋯+n!（n≤50n \le 50n≤50）。 其中 ! 表示阶乘，定义为 n!=n×(n−1)×(n−2)×⋯×1n!=n\times (n-1)\times (n-2)\times \cdots \times 1n!=n×(n−1)×(n−2)×⋯×1。例如，5!=5×4×3×2×1=1205! = 5 \times 4 \times 3 \times 2 \times 1=1205!=5×4×3×2×1=120。 输入格式 一个正整数 nnn。 输出格式 一个正整数 SSS，表示计算结果。 样例 #1 样例输入 #1 3 样例输出 #1 9 提示 【数据范围】 对于 100%100 \%100% 的数据，1≤n≤501 \le n \le 501≤n≤50。 【其他说明】 注，《深入浅出基础篇》中使用本题作为例题，但是其数据范围只有 n≤20n \le 20n≤20，使用书中的代码无法通过本题。 如果希望通过本题，请继续学习第八章高精度的知识。 AC代码 #include &lt;stdio.h&gt;#include &lt;ctype.h&gt;#include &lt;math.h&gt;#include &lt;limits.h&gt;#include &lt;stdlib.h&gt;#include &lt;stdbool.h&gt;#include &lt;string.h&gt;#define M 100007#define ll long longint a[1005],b[1005],n;int main() &#123; int i,j; scanf(&quot;%d&quot;, &amp;n); a[0]=b[0]=1; for (i=2; i&lt;=n; i++) &#123; for (j=0; j&lt;100; j++) &#123; b[j]*=i; &#125; for (j=0; j&lt;100; j++) &#123; if (b[j]&gt;9) &#123; b[j+1] += b[j]/10; b[j]%=10; &#125; &#125; for (j=0; j&lt;100; j++) &#123; a[j]+=b[j]; if (a[j]&gt;9) &#123; a[j+1] += a[j]/10; a[j]%=10; &#125; &#125; &#125; for (i=100; i&gt;=0&amp;&amp;a[i]==0; i--); for (j=i; j&gt;=0; j--) printf(&quot;%d&quot;, a[j]); return 0;&#125;

 列表标签
&lt;!doctype html&gt;&lt;html&gt;&lt;head&gt;&lt;meta charset=&quot;utf-8&quot;&gt;&lt;title&gt;无标题文档&lt;/title&gt;&lt;!--    清除样式--&gt;    &lt;style&gt;        li&#123;            list-style: none;        &#125;/*        可以注意到小黑点和前面的编号都消失了*/    &lt;/style&gt;&lt;/head&gt;&lt;body&gt;&lt;!--    列表标签--&gt;&lt;!--    ul无序列表--&gt;    &lt;ul type=&quot;square&quot;&gt;&lt;!--        type用于改变li标签的样式（即前面的小点）--&gt;        &lt;li&gt;i&#x27;m first&lt;/li&gt;        &lt;li&gt;i&#x27;m second&lt;/li&gt;        &lt;li&gt;i&#x27;m third&lt;/li&gt;    &lt;/ul&gt;&lt;!--    ol有序列表--&gt;    &lt;ol type=&quot;A&quot;&gt;&lt;!--        type用于改变li标签的样式--&gt;                &lt;li&gt;听妈妈的话&lt;/li&gt;        &lt;li&gt;稻香&lt;/li&gt;        &lt;li&gt;美人鱼&lt;/li&gt;    &lt;/ol&gt;&lt;/body&gt;&lt;/html&gt;
 HTML 列表
 HTML无序列表
无序列表是一个项目的列表，此列项目使用粗体圆点（典型的小黑圆圈）进行标记。
无序列表使用 &lt;ul&gt; 标签
 HTML 有序列表
同样，有序列表也是一列项目，列表项目使用数字进行标记。 有序列表始于 &lt;ol&gt; 标签。每个列表项始于 &lt;li&gt; 标签。
列表项使用数字来标记。
 HTML 自定义列表
自定义列表不仅仅是一列项目，而是项目及其注释的组合。
自定义列表以 &lt;dl&gt; 标签开始。每个自定义列表项以 &lt;dt&gt; 开始。每个自定义列表项的定义以 &lt;dd&gt; 开始。
